local function resolveSafeGuiParent()
    local function canAccessContainer(container)
        if not container then return false end
        local ok = pcall(function()
            local probe = Instance.new("Folder")
            probe.Name = "__HONKUKIProbe"
            probe.Parent = container
            local _ = container:FindFirstChild("__HONKUKIProbe")
            probe:Destroy()
        end)
        return ok
    end
    local genv = (type(getgenv) == "function") and getgenv() or nil
    local huiFn = (genv and genv.gethui) or gethui
    if type(huiFn) == "function" then
        local ok, res = pcall(huiFn)
        if ok and canAccessContainer(res) then
            return res
        end
    end
    local okCg, cg = pcall(function() return game:GetService("CoreGui") end)
    if okCg and canAccessContainer(cg) then
        return cg
    end
    return LocalPlayer:WaitForChild("PlayerGui")
end
