            end
            function SliderObj.SetCustomFormat(fn)
                customFormatFn = fn
                vL.Text = formatValueText(currentVal)
            end
            function SliderObj.RefreshLabel()
                vL.Text = formatValueText(currentVal)
            end
            function SliderObj.Get() return currentVal end
            Box:RegisterRow(frame)
            return SliderObj
        end
