        if low == "e(1)" or low == "e (1)" or low == "e1" or low == "e(2)" or low == "e (2)" or low == "e(3)" then
            return true
        end
        if low:match("^e%s*%(%d+%)$") or low:match("^e%d+$") then
            return true
        end
        if low:find("skate orig", 1, true)
            or low:find("skate_orig", 1, true)
