    local function isPurePlaceholderSoundId(rawStr)
        if type(rawStr) ~= "string" then return true end
        if #rawStr > 128 then return false end
        local trimmed = rawStr:match("^%s*(.-)%s*$") or ""
        if trimmed == "" or trimmed == "0" or trimmed == "rbxassetid://" then return true end
        if trimmed:find("[&%?]") then return false end
        local digits = trimmed:match("^[Rr][Bb][Xx][Aa][Ss][Ss][Ee][Tt][Ii][Dd]://0*(%d+)$") or trimmed:match("^0*(%d+)$")
        return digits == "122929786531506"
    end
    local function resolveEffectiveSoundUri(desc)
        if not desc or not desc:IsA("Sound") then return "" end
        local sid = desc.SoundId or ""
        if not isPurePlaceholderSoundId(sid) then
            return sid
        end
        for _, attrName in ipairs({ "s", "OriginalID" }) do
            local okAttr, val = pcall(function() return desc:GetAttribute(attrName) end)
            if okAttr then
                if type(val) == "string" and not isPurePlaceholderSoundId(val) then
                    return val
                elseif type(val) == "number" and val > 0 and tostring(val) ~= "122929786531506" then
                    return "rbxassetid://" .. tostring(val)
                end
            end
        end
        return ""
    end
