        if bp then
            local bb = bp:FindFirstChild("Boombox")
            local bbS = bb and (bb:FindFirstChild(targetName, true) or bb:FindFirstChild(BAIT_AUDIO_TITLE, true) or bb:FindFirstChild("PlayersChoice", true) or bb:FindFirstChild("120232514292241", true))
            if bbS and bbS:IsA("Sound") and isLegitimateMusicSound(bbS) then
                applySoundName(bbS)
                cachedActiveSound = bbS
                return bbS
            end
            for _, desc in ipairs(bp:GetDescendants()) do
                if desc:IsA("Sound") and isLegitimateMusicSound(desc) then
                    applySoundName(desc)
                    cachedActiveSound = desc
                    return desc
                end
            end
        end
        return nil
    end
