            local text = QuickTextBox.Text or ""
            local clean = text:match("%d+")
            if not clean or clean == "" then
                HONKUKIUI:Notify({
                    Title = "Dynamic Island",
                    Content = AppState.LangMode == "en" and "Please enter a valid Audio ID" or "กรุณาระบุรหัสเพลง (Audio ID) ที่ถูกต้อง",
                    Icon = Icons.Close
                })
                return
            end
            PlaySound(Sounds.Click, 0.8)
            QuickTextBox.Text = ""
            lastUserActionTime = os.clock()
            lastSoundActiveTime = os.clock()
            if _G.HONKUKIPlayMusicFn then
                _G.HONKUKIPlayMusicFn(clean)
            else
                Widget:Show(clean)
            end
        end
        QuickPlayBtn.Activated:Connect(playQuickInput)
        QuickTextBox.Focused:Connect(function()
            Motion.Tween(qiStroke, 0.16, { Color = Theme.AccentCyan, Transparency = 0.12 })
        end)
        QuickTextBox.FocusLost:Connect(function(enter)
