    getActiveQueue = function()
        local list = {}
        local isEn = (AppState.LangMode == "en")
        if AppState.FavoriteItems and #AppState.FavoriteItems > 0 then
            for _, item in ipairs(AppState.FavoriteItems) do
                table.insert(list, {
                    id = tostring(item.id),
                    title = item.title or ("Audio " .. tostring(item.id)),
                    playlist = item.playlist
                })
            end
            if #list > 0 then
                return list, isEn and "Favorites Queue" or "รายการเพลงโปรด"
            end
        end
        local pgui = LocalPlayer:FindFirstChild("PlayerGui")
        if pgui then
            local mg = pgui:FindFirstChild("MainGUIHandler")
            local ma = mg and mg:FindFirstChild("MainAudio")
            local cat = ma and ma:FindFirstChild("Catalog")
            local cont = cat and cat:FindFirstChild("Container")
            local sf = cont and cont:FindFirstChildOfClass("ScrollingFrame")
            local songsFolder = sf and sf:FindFirstChild("Songs")
            if songsFolder then
                for _, item in ipairs(songsFolder:GetChildren()) do
                    if item:IsA("ImageButton") or item:IsA("Frame") then
                        local t = item:FindFirstChild("Title") or item:FindFirstChild("SongName")
                        local idVal = item:FindFirstChild("ID") or item:FindFirstChild("AssetID")
                        if t and idVal then
                            table.insert(list, {
                                title = (t:IsA("TextLabel") and t.Text or tostring(t.Value)),
                                id = tostring(idVal.Value)
                            })
                        end
                    end
                end
            end
        end
        return list, "Brookhaven Catalog"
    end
    local function updatePlaylistButtons()
        local queue = getActiveQueue()
        local hasQueue = #queue > 0
        PrevIcon.ImageTransparency = hasQueue and 0 or 0.50
        NextIcon.ImageTransparency = hasQueue and 0 or 0.50
        PrevBtn.Active = true
        NextBtn.Active = true
        for idx, item in ipairs(queue) do
            if tostring(item.id) == tostring(currentAudioId) then
                currentQueueIdx = idx
                break
            end
        end
    end
    local function updateSongDisplay(audioId, customTitle, customSub)
        currentAudioId = tostring(audioId):match("%d+") or tostring(audioId)
        local cleanId = currentAudioId
        if cleanId == "" or cleanId == "0" then return end
        local queue, queueLabel = getActiveQueue()
        local posStr = ""
        local favCustomTitle = nil
        for idx, item in ipairs(queue) do
            if tostring(item.id) == cleanId then
                currentQueueIdx = idx
                posStr = string.format(" • (%d/%d)", idx, #queue)
                if item.title and not item.title:find("^Audio%s*%d+$") then
                    favCustomTitle = item.title
                end
                break
            end
        end
        local displaySub = (posStr ~= "" and (queueLabel .. posStr)) or customSub or "Brookhaven"
        SubLbl.Text = displaySub
        if customTitle and customTitle ~= "" and not customTitle:find("^Audio%s*%d+$") then
            TitleLbl.Text = customTitle
            CompactTitle.Text = customTitle
            return
        end
        if favCustomTitle then
            TitleLbl.Text = favCustomTitle
            CompactTitle.Text = favCustomTitle
            return
        end
        if songTitleCache[cleanId] then
            TitleLbl.Text = songTitleCache[cleanId].title
            CompactTitle.Text = songTitleCache[cleanId].title
            if posStr == "" then
                SubLbl.Text = songTitleCache[cleanId].artist
            end
            return
        end
        TitleLbl.Text = "Audio " .. cleanId
        CompactTitle.Text = "Audio " .. cleanId
        task.spawn(function()
            local success, res = pcall(function()
                return MarketplaceService:GetProductInfo(tonumber(cleanId), Enum.InfoType.Asset)
            end)
            if success and res and res.Name then
                local t = res.Name
                local a = (res.Creator and res.Creator.Name) or res.CreatorName or "Roblox"
                songTitleCache[cleanId] = { title = t, artist = a }
                if currentAudioId == cleanId then
                    TitleLbl.Text = t
                    CompactTitle.Text = t
                    if posStr == "" then
                        SubLbl.Text = a
                    end
                end
            end
        end)
    end
    local isCardDragging = false
    local isPullingDown = false
    local pullStartY = 0
    local dragStart = Vector3.zero
    local dragTargetStartPos = UDim2.new(0.5, 0, 0.38, 0)
    local scaleBadgeFadeDebounce = nil
    local function applyPlayerScale(newScale, showNotice)
        newScale = math.clamp(math.round(newScale * 100) / 100, 0.50, 1.35)
        AppState.NowPlayingScale = newScale
        if DetachedScale then
            DetachedScale.Scale = newScale
        end
        if HONKUKIUI.IslandMode == "MusicExpanded" and HONKUKIUI.DockScale then
            HONKUKIUI.DockScale.Scale = newScale
        end
        if ScaleBadgeText then
            ScaleBadgeText.Text = string.format("%d%%", math.round(newScale * 100))
        end
        if showNotice and ScaleBadge then
            ScaleBadge.Visible = true
            Motion.Cancel(ScaleBadge)
            ScaleBadge.BackgroundTransparency = 0.15
            ScaleBadgeText.TextTransparency = 0
            if scaleBadgeFadeDebounce then task.cancel(scaleBadgeFadeDebounce) end
            scaleBadgeFadeDebounce = task.delay(1.2, function()
                Tween(ScaleBadge, 0.35, { BackgroundTransparency = 1 })
                Tween(ScaleBadgeText, 0.35, { TextTransparency = 1 }).Completed:Connect(function()
                    ScaleBadge.Visible = false
                end)
            end)
        end
    end
    local function setDetached(detached)
        isDetached = detached
        HONKUKIUI.IsMusicDetached = detached
        local isEn = (AppState.LangMode == "en")
        if isDetached then
            DockBackBtn.Visible = true
            DetachVecStroke.Color = Theme.AccentCyan
            ExpandedCard.Parent = DetachedGlass
            ExpandedCard.Visible = true
            DetachedContainer.Visible = true
            local curScale = AppState.NowPlayingScale or (isMobile and 0.78 or 1.0)
            if DetachedScale then DetachedScale.Scale = curScale end
            Tween(DetachedContainer, 0.28, { Position = freeFloatingPos }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
            SetIslandMode("Collapsed")
            HONKUKIUI:Notify({ Title = "Dynamic Island", Content = isEn and "Detached into floating window" or "แยกหน้าต่างควบคุมออกเป็นหน้าต่างลอยเรียบร้อยแล้ว", Icon = Icons.Check, Duration = 1.6 })
        else
            DockBackBtn.Visible = false
            DetachVecStroke.Color = Color3.fromRGB(255, 255, 255)
            Tween(DetachedContainer, 0.26, { Position = UDim2.new(0.5, 0, 0, AppState.DockOffsetY) }, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
            task.delay(0.24, function()
                DetachedContainer.Visible = false
                ExpandedCard.Parent = DockGlass
                SetIslandMode("MusicExpanded")
                HONKUKIUI:Notify({ Title = "Dynamic Island", Content = isEn and "Re-attached to Dynamic Island" or "จัดเก็บเข้าสู่แถบควบคุม Dynamic Island เรียบร้อยแล้ว", Icon = Icons.Check, Duration = 1.6 })
            end)
        end
    end
    local function setupCardInteraction(handle)
        if not handle then return end
        handle.Active = true
        handle.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if isDetached then
                    isCardDragging = true
                    dragStart = input.Position
                    dragTargetStartPos = DetachedContainer.Position
                else
                    if HONKUKIUI.IslandMode == "MusicExpanded" then
                        isPullingDown = true
                        pullStartY = input.Position.Y
                    end
                end
            end
        end)
    end
    setupCardInteraction(TopRow)
    setupCardInteraction(BottomGripPill)
    setupCardInteraction(ExpandedCard)
    UserInputService.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            if isPullingDown and not isDetached then
                local deltaY = input.Position.Y - pullStartY
                if deltaY > 0 then
                    DockPill.Position = UDim2.new(0.5, 0, 0, AppState.DockOffsetY + math.min(deltaY * 0.65, 45))
                end
                if deltaY >= 22 then
                    isPullingDown = false
                    PlaySound(Sounds.Pop, 0.85)
                    local vp = Camera and Camera.ViewportSize or Vector2.new(1920, 1080)
                    local curScale = AppState.NowPlayingScale or (isMobile and 0.78 or 1.0)
                    local cardW = EXPANDED_MUSIC_WIDTH * curScale
                    local cardH = EXPANDED_MUSIC_HEIGHT * curScale
                    local targetX = math.clamp(input.Position.X, cardW / 2 + 10, vp.X - cardW / 2 - 10)
                    local targetY = math.clamp(input.Position.Y - 25, 10, vp.Y - cardH - 12)
                    freeFloatingPos = UDim2.fromOffset(targetX, targetY)
                    DockPill.Position = UDim2.new(0.5, 0, 0, AppState.DockOffsetY)
                    setDetached(true)
                    isCardDragging = true
                    dragStart = input.Position
                    dragTargetStartPos = freeFloatingPos
                end
            elseif isCardDragging and isDetached then
                local delta = input.Position - dragStart
                local vp = Camera and Camera.ViewportSize or Vector2.new(1920, 1080)
                local curScale = AppState.NowPlayingScale or (isMobile and 0.78 or 1.0)
                local halfW = (EXPANDED_MUSIC_WIDTH * curScale) / 2
                local cardH = EXPANDED_MUSIC_HEIGHT * curScale
                local curX = (dragTargetStartPos.X.Scale * vp.X) + dragTargetStartPos.X.Offset + delta.X
                local curY = (dragTargetStartPos.Y.Scale * vp.Y) + dragTargetStartPos.Y.Offset + delta.Y
                local clampedX = math.clamp(curX, halfW + 10, vp.X - halfW - 10)
                local clampedY = math.clamp(curY, 10, vp.Y - cardH - 12)
                DetachedContainer.Position = UDim2.fromOffset(clampedX, clampedY)
                freeFloatingPos = DetachedContainer.Position
            end
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            if isPullingDown then
                isPullingDown = false
                Tween(DockPill, 0.24, { Position = UDim2.new(0.5, 0, 0, AppState.DockOffsetY) }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
            end
            if isCardDragging then
                isCardDragging = false
            end
        end
    end)
