    local isResizing = false
    local resizeStartScale = 1.0
    local resizeStartInputPos = Vector3.zero
    local hasMovedResize = false
    ResizeGrip.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isResizing = true
            hasMovedResize = false
            resizeStartScale = AppState.NowPlayingScale or (isMobile and 0.78 or 1.0)
            resizeStartInputPos = input.Position
            GripIcon.ImageColor3 = Theme.AccentCyan
            GripIcon.ImageTransparency = 0
            ScaleBadge.Visible = true
            Motion.Cancel(ScaleBadge)
            ScaleBadge.BackgroundTransparency = 0.15
            ScaleBadgeText.TextTransparency = 0
            ScaleBadgeText.Text = string.format("%d%%", math.round(resizeStartScale * 100))
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if isResizing and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - resizeStartInputPos
            if delta.Magnitude > 4 then
                hasMovedResize = true
            end
            local scaleDelta = (delta.X + delta.Y) / 260
            local targetScale = math.clamp(math.round((resizeStartScale + scaleDelta) * 100) / 100, 0.50, 1.35)
            applyPlayerScale(targetScale, false)
            ScaleBadgeText.Text = string.format("%d%%", math.round(targetScale * 100))
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if isResizing and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
            isResizing = false
            GripIcon.ImageColor3 = Color3.fromRGB(160, 160, 170)
            GripIcon.ImageTransparency = 0.35
            if not hasMovedResize then
                local cur = AppState.NowPlayingScale or (isMobile and 0.78 or 1.0)
                local nextPreset = 1.0
                if cur < 0.74 then
                    nextPreset = 0.85
                elseif cur < 0.94 then
                    nextPreset = 1.0
                else
                    nextPreset = isMobile and 0.65 or 0.78
                end
                PlaySound(Sounds.Click, 0.8)
                applyPlayerScale(nextPreset, true)
            else
                PlaySound(Sounds.Pop, 0.7)
                if scaleBadgeFadeDebounce then task.cancel(scaleBadgeFadeDebounce) end
                scaleBadgeFadeDebounce = task.delay(1.2, function()
                    Tween(ScaleBadge, 0.35, { BackgroundTransparency = 1 })
                    Tween(ScaleBadgeText, 0.35, { TextTransparency = 1 }).Completed:Connect(function()
                        ScaleBadge.Visible = false
                    end)
                end)
            end
        end
    end)
