    UserInputService.InputBegan:Connect(function(input)
        if (input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1) then
            if os.clock() - (HONKUKIUI.LastIslandStateChange or 0) < 0.45 then return end
            local pos = input.Position
            local dPos = DockPill.AbsolutePosition
            local dSize = DockPill.AbsoluteSize
            local inside = (pos.X >= dPos.X and pos.X <= dPos.X + dSize.X and pos.Y >= dPos.Y and pos.Y <= dPos.Y + dSize.Y)
            if not inside then
                if HONKUKIUI.IslandMode == "MusicExpanded" and not isDetached then
                    SetIslandMode("MusicCompact")
                elseif HONKUKIUI.IslandMode == "DockTabs" then
                    if HONKUKIUI.IsMusicActive and not isDetached then
                        SetIslandMode("MusicCompact")
                    elseif AppState.DockAutoCollapse then
                        SetIslandMode("Collapsed")
                    end
                end
            end
        end
    end)
