    function Widget:Show(audioId, customTitle, customArtist, playlistContext)
        lastUserActionTime = os.clock()
        lastSoundActiveTime = os.clock()
        isWidgetActive = true
        Widget.IsActive = true
        HONKUKIUI.IsMusicActive = true
        if playlistContext ~= nil then
            activePlaylistContext = playlistContext
        end
        currentAudioId = audioId or currentAudioId
        updatePlaylistButtons()
        updateSongDisplay(currentAudioId, customTitle, customArtist)
        isPlaying = true
        isPaused = false
        currentState = STATE_PLAYING
        lastSongStartedTime = os.clock()
        PlayPauseIcon.Image = Icons.Pause
        updateStarUI()
        if isDetached then
            DetachedContainer.Visible = true
            ExpandedCard.Visible = true
        else
            SetIslandMode("MusicExpanded")
            PlaySound(Sounds.Pop, 0.85)
        end
        if updateConn then updateConn:Disconnect() end
        local lastEqUpdate = 0
        local lastElapsedSec = -1
        local lastTotalSec = -2
        local lastTimeTextReset = false
        local lastIdleBarsSet = false
        local lastSndPoll = 0
        local lastSndRef = nil
        updateConn = RunService.RenderStepped:Connect(function()
            local now = os.clock()
            if not (lastSndRef and lastSndRef.Parent) or (now - lastSndPoll) >= 0.35 then
                lastSndPoll = now
                lastSndRef = getActiveCharSound()
            end
            local snd = lastSndRef
            local isActivelyPlaying = (snd and (snd.Playing or snd.IsPlaying)) or (currentState == STATE_PLAYING and isPlaying and not isPaused)
            local showExpanded = (isDetached and DetachedContainer.Visible and ExpandedCard.Visible) or (not isDetached and HONKUKIUI.IslandMode == "MusicExpanded")
            if (now - lastEqUpdate) >= 0.032 then
                lastEqUpdate = now
                if isActivelyPlaying then
                    lastIdleBarsSet = false
                    if not showExpanded then
                        for idx, b in ipairs(miniEqBars) do
                            local waveH = 3.5 + math.abs(math.sin(now * (7.5 + idx * 1.1) + idx * 0.95)) * 11
                            b.Size = UDim2.new(0, 2.3, 0, waveH)
                        end
                    else
                        for idx, wb in ipairs(expandedEqBars) do
                            local baseH = waveProfile[idx] or 14
                            local waveFactor = 0.45 + 0.55 * math.abs(math.sin(now * (5.5 + (idx % 6) * 0.8) + idx * 0.38))
                            local harmonic = math.sin(now * 7.2 - idx * 0.6) * 3
                            local waveH = math.clamp(baseH * waveFactor + harmonic, 3.5, 50)
                            wb.Size = UDim2.new(0, 3.0, 0, waveH)
                        end
                    end
                elseif not lastIdleBarsSet then
                    lastIdleBarsSet = true
                    for _, b in ipairs(miniEqBars) do b.Size = UDim2.new(0, 2.3, 0, 3.5) end
                    for idx, wb in ipairs(expandedEqBars) do
                        local baseH = waveProfile[idx] or 14
                        wb.Size = UDim2.new(0, 3.0, 0, baseH)
                    end
                end
            end
            if showExpanded then
                if snd and snd.TimeLength and snd.TimeLength > 0 then
                    lastTimeTextReset = false
                    local totLen = snd.TimeLength
                    local curPos = math.clamp(snd.TimePosition, 0, totLen)
                    if isPaused or currentState == STATE_PAUSED then
                        curPos = math.clamp(savedTimePosition, 0, totLen)
                    else
                        savedTimePosition = curPos
                    end
                    local pct = math.clamp(curPos / totLen, 0, 1)
                    TimeFill.Size = UDim2.new(pct, 0, 1, 0)
                    local elSec = math.floor(curPos)
                    local remSec = math.floor(math.max(0, totLen - curPos))
                    if elSec ~= lastElapsedSec then
                        lastElapsedSec = elSec
                        TimeElapsedLbl.Text = string.format("%d:%02d", math.floor(elSec / 60), elSec % 60)
                    end
                    if remSec ~= lastTotalSec then
                        lastTotalSec = remSec
                        TimeTotalLbl.Text = string.format("-%d:%02d", math.floor(remSec / 60), remSec % 60)
                    end
                elseif isPaused or currentState == STATE_PAUSED then
                    local elSec = math.floor(savedTimePosition)
                    if elSec ~= lastElapsedSec then
                        lastElapsedSec = elSec
                        TimeElapsedLbl.Text = string.format("%d:%02d", math.floor(elSec / 60), elSec % 60)
                    end
                elseif isActivelyPlaying and lastSongStartedTime > 0 then
                    lastTimeTextReset = false
                    local estPos = math.max(0, now - lastSongStartedTime)
                    savedTimePosition = estPos
                    local elSec = math.floor(estPos)
                    if elSec ~= lastElapsedSec then
                        lastElapsedSec = elSec
                        TimeElapsedLbl.Text = string.format("%d:%02d", math.floor(elSec / 60), elSec % 60)
                    end
                    if lastTotalSec ~= -1 then
                        lastTotalSec = -1
                        TimeTotalLbl.Text = "--:--"
                    end
                elseif not lastTimeTextReset then
                    lastTimeTextReset = true
                    lastElapsedSec = -1
                    lastTotalSec = -2
                    TimeFill.Size = UDim2.new(0, 0, 1, 0)
                    TimeElapsedLbl.Text = "0:00"
                    TimeTotalLbl.Text = "--:--"
                end
            end
        end)
        _G.HONKUKINowPlayingWaveformConn = updateConn
    end
    function Widget:Hide()
        isWidgetActive = false
        Widget.IsActive = false
        HONKUKIUI.IsMusicActive = false
        isPlaying = false
        isPaused = false
        currentState = STATE_STOPPED
        if updateConn then updateConn:Disconnect(); updateConn = nil end
        if isDetached then
            DetachedContainer.Visible = false
        end
        SetIslandMode("Collapsed")
    end
    if _G.HONKUKIMusicDetectorConn then pcall(function() _G.HONKUKIMusicDetectorConn:Disconnect() end) end
    if _G.HONKUKIMusicSignalConns then for _, c in ipairs(_G.HONKUKIMusicSignalConns) do pcall(function() c:Disconnect() end) end end
    _G.HONKUKIMusicSignalConns = {}
    local isDetectorDebounce = false
    local function evaluateMusicPlayback()
        local snd = getActiveCharSound(true)
        if not snd then
            if isWidgetActive and not isDetectorDebounce then
                if isPaused or currentState == STATE_PAUSED then return end
                local silentDuration = os.clock() - lastSoundActiveTime
                if silentDuration > 1.2 and isWidgetActive then
                    local checkSnd = getActiveCharSound(true)
                    if not checkSnd or not (checkSnd.Playing or checkSnd.IsPlaying) then
                        isPlaying = false
                        currentState = STATE_STOPPED
                        PlayPauseIcon.Image = Icons.Play
                        Widget:Hide()
                    end
                end
            end
            return
        end
        local activePlaying = snd.Playing or snd.IsPlaying
        local resolvedSid = nil
        local isMusicPlaying = false
        if activePlaying then
            if isWidgetActive and currentAudioId ~= "" and currentAudioId ~= "0" and snd.Name ~= "WindDiving_Whoosh" then
                isMusicPlaying = true
            else
                resolvedSid = _G.HONKUKIResolveEffectiveSoundUri and _G.HONKUKIResolveEffectiveSoundUri(snd) or (snd.SoundId or "")
                isMusicPlaying = (resolvedSid ~= "" and resolvedSid ~= "rbxassetid://")
            end
        end
        if isMusicPlaying then
            lastSoundActiveTime = os.clock()
            local cleanId = (currentAudioId ~= "" and currentAudioId ~= "0") and currentAudioId or nil
            if not cleanId or cleanId == "" or cleanId == "0" then
                local rawSid = resolvedSid or (_G.HONKUKIResolveEffectiveSoundUri and _G.HONKUKIResolveEffectiveSoundUri(snd) or (snd.SoundId or ""))
                if decodeAudioId then
                    pcall(function() cleanId = decodeAudioId(rawSid) end)
                end
                if not cleanId or cleanId == "" or cleanId == "0" then
                    cleanId = rawSid:match("(%d+)") or ""
                end
            end
            if isPaused or currentState == STATE_PAUSED or not isPlaying then
                isPaused = false
                isPlaying = true
                currentState = STATE_PLAYING
                PlayPauseIcon.Image = Icons.Pause
            end
            if not isWidgetActive and not isDetectorDebounce and cleanId ~= "" and cleanId ~= "0" then
                isDetectorDebounce = true
                Widget:Show(cleanId)
                task.delay(0.35, function() isDetectorDebounce = false end)
            elseif isWidgetActive and cleanId ~= "" and cleanId ~= "0" and cleanId ~= currentAudioId then
                currentAudioId = cleanId
                savedTimePosition = 0
                updatePlaylistButtons()
                updateSongDisplay(cleanId)
                PlayPauseIcon.Image = Icons.Pause
                isPlaying = true
                isPaused = false
                currentState = STATE_PLAYING
                updateStarUI()
            end
        else
            if isWidgetActive and not isDetectorDebounce then
                if isPaused or currentState == STATE_PAUSED then return end
                local silentDuration = os.clock() - lastSoundActiveTime
                if silentDuration > 1.2 and isWidgetActive then
                    local checkSnd = getActiveCharSound(true)
                    if not checkSnd or not (checkSnd.Playing or checkSnd.IsPlaying) then
                        isPlaying = false
                        currentState = STATE_STOPPED
                        PlayPauseIcon.Image = Icons.Play
                        Widget:Hide()
                    end
                end
            end
        end
    end
    local hookedSounds = {}
    local function hookSoundInstance(s)
        if not s or not s:IsA("Sound") or hookedSounds[s] then return end
        if not isLegitimateMusicSound(s, true) then return end
        applySoundName(s)
        hookedSounds[s] = true
        local c1 = s:GetPropertyChangedSignal("Playing"):Connect(function()
            if s.Playing then evaluateMusicPlayback() else task.delay(0.25, evaluateMusicPlayback) end
        end)
        local c2 = s:GetPropertyChangedSignal("SoundId"):Connect(evaluateMusicPlayback)
        local c3 = s.Played:Connect(evaluateMusicPlayback)
        local c4 = s.Stopped:Connect(function() task.delay(0.25, evaluateMusicPlayback) end)
        table.insert(_G.HONKUKIMusicSignalConns, c1)
        table.insert(_G.HONKUKIMusicSignalConns, c2)
        table.insert(_G.HONKUKIMusicSignalConns, c3)
        table.insert(_G.HONKUKIMusicSignalConns, c4)
    end
    local function setupCharWatch(char)
        if not char then return end
        for _, d in ipairs(char:GetDescendants()) do
            if d:IsA("Sound") and isLegitimateMusicSound(d, true) then
                applySoundName(d)
                hookSoundInstance(d)
            end
        end
        local cDesc = char.DescendantAdded:Connect(function(d)
            if d:IsA("Sound") and isLegitimateMusicSound(d, true) then
                applySoundName(d)
                hookSoundInstance(d)
                task.defer(evaluateMusicPlayback)
            end
        end)
        table.insert(_G.HONKUKIMusicSignalConns, cDesc)
    end
    setupCharWatch(LocalPlayer.Character)
    local cChar = LocalPlayer.CharacterAdded:Connect(setupCharWatch)
    table.insert(_G.HONKUKIMusicSignalConns, cChar)
    local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
    if bp then
        for _, d in ipairs(bp:GetDescendants()) do
            if d:IsA("Sound") and isLegitimateMusicSound(d, true) then
                applySoundName(d)
                hookSoundInstance(d)
            end
        end
        local cBpDesc = bp.DescendantAdded:Connect(function(d)
            if d:IsA("Sound") and isLegitimateMusicSound(d, true) then
                applySoundName(d)
                hookSoundInstance(d)
                task.defer(evaluateMusicPlayback)
            end
        end)
        table.insert(_G.HONKUKIMusicSignalConns, cBpDesc)
    end
    local musicDetectorAccum = 0
    _G.HONKUKIMusicDetectorConn = RunService.Heartbeat:Connect(function(dt)
        musicDetectorAccum = musicDetectorAccum + dt
        if musicDetectorAccum < 0.45 then return end
        musicDetectorAccum = 0
        evaluateMusicPlayback()
    end)
    Widget.NextSong = doNextSong
    Widget.PreviousSong = doPrevSong
    Widget.RestartSong = doRestartSong
    Widget.TogglePlayPause = togglePlayPause
    Widget.SetServerVolume = function(val) updateVolumeUI(val); sendServerVolume(val) end
    Widget.SetPlaylistContext = function(plName)
        activePlaylistContext = plName
        updatePlaylistButtons()
        updateSongDisplay(currentAudioId)
    end
    Music.PlaySongFromCatalog = function(self, idx) return playSongFromQueue(idx) end
    Music.TogglePlayPause = function(self) return togglePlayPause() end
    Music.Next = function(self) return doNextSong() end
    Music.Previous = function(self) return doPrevSong() end
    Music.Restart = function(self) return doRestartSong() end
    Music.SetVolume = function(self, val) updateVolumeUI(val); sendServerVolume(val) end
    Music.GetCatalog = function(self) return (getActiveQueue()) end
    Music.Stop = function(self)
        pcall(function()
            if ToolEvent then ToolEvent:FireServer("ToolMusicStop", "", nil) end
            if ScooterEvent then ScooterEvent:FireServer("PickingScooterMusicStop", "", nil) end
            local snd = getActiveCharSound()
            if snd then snd:Stop() end
        end)
        Widget:Hide()
    end
    Widget.Root = DetachedContainer
    Widget.DockPill = DockPill
    Widget.TimeFill = TimeFill
    Widget.VolFill = VolFill
    Widget.PlayPauseBtn = PlayPauseBtn
    Widget.RestartBtn = RestartBtn
    Widget.ExpandBtn = ExpandBtn
    Widget.CloseBtn = CloseBtn
    Widget.StarBtn = StarBtn
    Widget.DetachBtn = DetachBtn
    Widget.DockBackBtn = DockBackBtn
    Widget.BottomGripPill = BottomGripPill
    Widget.SetDetached = setDetached
    Widget.TitleLbl = TitleLbl
    Widget.SubLbl = SubLbl
    Widget.VolText = VolText
    Widget.SetActiveSound = function(self, s)
        if s and s:IsA("Sound") then
            cachedActiveSound = s
        end
    end
    HONKUKIUI.NowPlayingCard = Widget
    return Widget
end
