local function getContrastInk(col)
    local lum = 0.299 * col.R + 0.587 * col.G + 0.114 * col.B
    if lum > 0.72 then
        return Color3.fromRGB(12, 14, 18)
    end
    return Color3.fromRGB(255, 255, 255)
end
