            StatusLabel.Text = isEn and " • Save failed" or " • บันทึกล้มเหลว"
        end
    else
        HONKUKIUI:Notify({
            Title = isEn and "Save Error" or "ไม่สามารถบันทึกได้",
            Content = isEn and "writefile() is not supported" or "สภาพแวดล้อมปัจจุบันไม่รองรับฟังก์ชันการบันทึกไฟล์ (writefile)",
            Icon = Icons.Close,
            Duration = 2.5,
        })
    end
end)
