do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local TweenService = game:GetService("TweenService")
    local Lighting = game:GetService("Lighting")
    local UserInputService = game:GetService("UserInputService")
    local Debris = game:GetService("Debris")
    local HttpService = game:GetService("HttpService")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local TextChatService = nil
    pcall(function() TextChatService = game:GetService("TextChatService") end)
    local LP = Players.LocalPlayer
    if not LP then
        repeat task.wait(0.1); LP = Players.LocalPlayer until LP
    end
    local function getSafeGui()
        return GuiParent or LP:FindFirstChildOfClass("PlayerGui") or LP:WaitForChild("PlayerGui")
    end
    if _G.HONKUKIArsenalConns then
        for _, c in pairs(_G.HONKUKIArsenalConns) do
            pcall(function() if typeof(c) == "RBXScriptConnection" then c:Disconnect() elseif typeof(c) == "Instance" then c:Destroy() end end)
        end
    end
    _G.HONKUKIArsenalConns = {}
    _G.HONKUKIActiveDomains = _G.HONKUKIActiveDomains or {}
    local function trackConn(key, conn)
        if _G.HONKUKIArsenalConns[key] then
            pcall(function()
                if typeof(_G.HONKUKIArsenalConns[key]) == "RBXScriptConnection" then
                    _G.HONKUKIArsenalConns[key]:Disconnect()
                elseif typeof(_G.HONKUKIArsenalConns[key]) == "Instance" then
                    _G.HONKUKIArsenalConns[key]:Destroy()
                end
            end)
        end
        _G.HONKUKIArsenalConns[key] = conn
    end
    local function mkPart(props)
        local p = Instance.new(props.ClassName or "Part")
        p.Anchored = (props.Anchored ~= false)
        p.CanCollide = (props.CanCollide == true)
        p.Massless = (props.Massless ~= false)
        if p:IsA("Part") then
            p.TopSurface = Enum.SurfaceType.Smooth
            p.BottomSurface = Enum.SurfaceType.Smooth
            if props.Shape then p.Shape = props.Shape end
        end
        p.Material = props.Material or Enum.Material.Neon
        p.Color = props.Color or Color3.fromRGB(255, 255, 255)
        p.Size = props.Size or Vector3.new(1, 1, 1)
        p.Transparency = props.Transparency or 0
        if props.CFrame then p.CFrame = props.CFrame end
        if props.Name then p.Name = props.Name end
        p.Parent = props.Parent or workspace
        return p
    end
    local function mkMesh(props)
        local p = Instance.new("Part")
        p.Name = props.Name or "HONKUKI_MeshProp"
        p.Size = props.Size or Vector3.new(2, 2, 2)
        p.CanCollide = (props.CanCollide == true)
        p.Anchored = (props.Anchored ~= false)
        p.Massless = true
        p.Transparency = props.Transparency or 0
        p.Color = props.Color or Color3.new(1, 1, 1)
        p.Material = props.Material or Enum.Material.SmoothPlastic
        if props.CFrame then p.CFrame = props.CFrame end
        p.TopSurface = Enum.SurfaceType.Smooth
        p.BottomSurface = Enum.SurfaceType.Smooth
        local sm = Instance.new("SpecialMesh", p)
        sm.MeshType = Enum.MeshType.FileMesh
        if props.MeshId then
            local mid = tostring(props.MeshId)
            sm.MeshId = mid:find("^rbxassetid://") and mid or ("rbxassetid://" .. mid)
        end
        if props.TextureId then
            local tid = tostring(props.TextureId)
            sm.TextureId = tid:find("^rbxassetid://") and tid or ("rbxassetid://" .. tid)
        end
        if props.Scale then sm.Scale = props.Scale else sm.Scale = Vector3.new(1, 1, 1) end
        if props.VertexColor then sm.VertexColor = props.VertexColor end
        if props.Parent then p.Parent = props.Parent end
        return p, sm
    end
    local function weldTo(p0, p1, c0)
        p1.Anchored = false
        p1.CanCollide = false
        p1.Massless = true
        local w = Instance.new("Weld")
        w.Part0 = p0
        w.Part1 = p1
        w.C0 = c0 or CFrame.identity
        w.Parent = p1
        return w
    end
    local function playSfx(id, vol, spd, parent, dur)
        pcall(function()
            local s = Instance.new("Sound")
            s.SoundId = "rbxassetid://" .. tostring(id):gsub("%D", "")
            s.Volume = vol or 3
            s.PlaybackSpeed = spd or 1
            if typeof(parent) == "Vector3" then
                local a = Instance.new("Attachment", workspace.Terrain)
                a.Position = parent
                s.Parent = a
                Debris:AddItem(a, dur or 8)
            else
                s.Parent = parent or workspace
            end
            s:Play()
            Debris:AddItem(s, dur or 8)
        end)
    end
    local function shakeCamera(intensity, duration, epicenterPos)
        task.spawn(function()
            local cam = workspace.CurrentCamera
            if not cam then return end
            local dMult = 1
            if epicenterPos and LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") then
                local dist = (LP.Character.HumanoidRootPart.Position - epicenterPos).Magnitude
                if dist > 220 then return end
                dMult = math.clamp(1 - (dist / 220), 0.1, 1)
            end
            local st = os.clock()
            while os.clock() - st < (duration or 0.8) do
                local alpha = 1 - ((os.clock() - st) / (duration or 0.8))
                local mag = (intensity or 1.2) * alpha * dMult
                pcall(function()
                    local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                    if hum then
                        hum.CameraOffset = Vector3.new(
                            (math.random() - 0.5) * 2 * mag,
                            (math.random() - 0.5) * 2 * mag,
                            (math.random() - 0.5) * 2 * mag
                        )
                    end
                end)
                RunService.RenderStepped:Wait()
            end
            pcall(function()
                local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                if hum then hum.CameraOffset = Vector3.zero end
            end)
        end)
    end
    local function spawnShockwave(pos, color, maxRadius, dur, folder)
        local parent = folder or workspace
        local ring = mkPart({
            Shape = Enum.PartType.Cylinder,
            Material = Enum.Material.Neon,
            Color = color or Color3.fromRGB(255, 60, 80),
            Size = Vector3.new(0.6, 2, 2),
            CFrame = CFrame.new(pos) * CFrame.Angles(0, 0, math.rad(90)),
            Transparency = 0.15,
            Parent = parent
        })
        TweenService:Create(ring, TweenInfo.new(dur or 0.7, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = Vector3.new(0.2, maxRadius * 2, maxRadius * 2),
            Transparency = 1
        }):Play()
        Debris:AddItem(ring, (dur or 0.7) + 0.1)
        local core = mkPart({
            Shape = Enum.PartType.Ball,
            Material = Enum.Material.Neon,
            Color = color or Color3.fromRGB(255, 200, 100),
            Size = Vector3.new(2, 2, 2),
            CFrame = CFrame.new(pos),
            Transparency = 0.2,
            Parent = parent
        })
        TweenService:Create(core, TweenInfo.new((dur or 0.7) * 0.85, Enum.EasingStyle.Expo, Enum.EasingDirection.Out), {
            Size = Vector3.new(maxRadius * 1.1, maxRadius * 1.1, maxRadius * 1.1),
            Transparency = 1
        }):Play()
        Debris:AddItem(core, dur or 0.8)
        for i = 1, 10 do
            local ang = (i / 10) * math.pi * 2
            local r = maxRadius * 0.45
            local rock = mkPart({
                Material = Enum.Material.Slate,
                Color = Color3.fromRGB(55, 55, 65),
                Size = Vector3.new(2.2, 1.4, 2.8),
                CFrame = CFrame.new(pos + Vector3.new(math.cos(ang) * r, -1.5, math.sin(ang) * r)) * CFrame.Angles(math.rad(math.random(-35, 35)), -ang, math.rad(math.random(-25, 25))),
                Parent = parent
            })
            TweenService:Create(rock, TweenInfo.new((dur or 0.8) + 0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Position = rock.Position + Vector3.new(math.cos(ang) * (maxRadius * 0.4), 2.5, math.sin(ang) * (maxRadius * 0.4)),
                Transparency = 1
            }):Play()
            Debris:AddItem(rock, (dur or 0.8) + 0.5)
        end
    end
