            line1.Size = UDim2.new(1, 0, 0, 2)
            line1.Position = UDim2.new(0, 0, 1, -2)
            line1.BackgroundColor3 = accentColor or Color3.fromRGB(255, 42, 84)
            line1.BorderSizePixel = 0
            local line2 = Instance.new("Frame", botBar)
