            sLbl.Text = tostring(subtitle or "")
            TweenService:Create(topBar, TweenInfo.new(0.35, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Position = UDim2.new(0, 0, 0, 0) }):Play()
            TweenService:Create(botBar, TweenInfo.new(0.35, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Position = UDim2.new(0, 0, 1, -68) }):Play()
            task.delay(duration or 3.8, function()
                if sg and sg.Parent then
                    TweenService:Create(topBar, TweenInfo.new(0.35), { Position = UDim2.new(0, 0, 0, -75) }):Play()
                    TweenService:Create(botBar, TweenInfo.new(0.35), { Position = UDim2.new(0, 0, 1, 75) }):Play()
                    task.wait(0.4)
                    if sg and sg.Parent then sg:Destroy() end
                end
            end)
        end)
    end
