local function createVictimRig(char, isSpectator)
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not (char and hum and hrp) then return nil end
        if isSpectator == nil then
            isSpectator = (char ~= LP.Character)
        end
        local isR15 = (hum.RigType == Enum.HumanoidRigType.R15)
        local animScript = char:FindFirstChild("Animate")
        if animScript and not isSpectator then pcall(function() animScript.Disabled = true end) end
        pcall(function()
            local animator = hum:FindFirstChildOfClass("Animator")
            if animator then
                for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do tr:Stop(0.05) end
            end
            for _, tr in ipairs(hum:GetPlayingAnimationTracks()) do tr:Stop(0.05) end
        end)
        hrp.Anchored = true
        if not isSpectator then
            hum.WalkSpeed = 0
            hum.AutoRotate = false
        end
        local motors = {}
        local origC0 = {}
        for _, d in ipairs(char:GetDescendants()) do
            if d:IsA("Motor6D") then
                motors[d.Name] = d
                origC0[d] = d.C0
            end
        end
        local rig = {
            char = char,
            hum = hum,
            hrp = hrp,
            baseCF = hrp.CFrame,
            isR15 = isR15,
            isSpectator = isSpectator,
            motors = motors,
            origC0 = origC0
        }
        local function setM(name, deltaCF, alpha)
            local m = motors[name]
            if m and m.Parent and origC0[m] then
                m.C0 = m.C0:Lerp(origC0[m] * deltaCF, alpha or 0.35)
            end
        end
        function rig:Pose(poseName, t)
            t = t or os.clock()
            local wob = math.sin(t * 28) * 0.08
            if isR15 then
                if poseName == "terror_up" then
                    setM("Neck", CFrame.Angles(math.rad(48), wob, 0))
                    setM("Waist", CFrame.Angles(math.rad(-14), 0, wob * 0.5))
                    setM("RightShoulder", CFrame.Angles(math.rad(155) + wob, 0, math.rad(22)))
                    setM("LeftShoulder", CFrame.Angles(math.rad(155) - wob, 0, math.rad(-22)))
                    setM("RightElbow", CFrame.Angles(math.rad(35), 0, 0))
                    setM("LeftElbow", CFrame.Angles(math.rad(35), 0, 0))
                elseif poseName == "clutch_chest" then
                    setM("Neck", CFrame.Angles(math.rad(-32), wob * 2, 0))
                    setM("Waist", CFrame.Angles(math.rad(-35), 0, wob))
                    setM("RightShoulder", CFrame.Angles(math.rad(65), math.rad(-45), math.rad(-35)))
                    setM("LeftShoulder", CFrame.Angles(math.rad(65), math.rad(45), math.rad(35)))
                    setM("RightElbow", CFrame.Angles(math.rad(95), 0, 0))
                    setM("LeftElbow", CFrame.Angles(math.rad(95), 0, 0))
                    setM("RightHip", CFrame.Angles(math.rad(35), 0, 0))
                    setM("LeftHip", CFrame.Angles(math.rad(35), 0, 0))
                    setM("RightKnee", CFrame.Angles(math.rad(-65), 0, 0))
                    setM("LeftKnee", CFrame.Angles(math.rad(-65), 0, 0))
                elseif poseName == "kneel_bound" then
                    setM("Neck", CFrame.Angles(math.rad(-45), 0, 0))
                    setM("Waist", CFrame.Angles(math.rad(-55), 0, 0))
                    setM("RightShoulder", CFrame.Angles(math.rad(-45), 0, math.rad(-25)))
                    setM("LeftShoulder", CFrame.Angles(math.rad(-45), 0, math.rad(25)))
                    setM("RightHip", CFrame.Angles(math.rad(15), 0, 0))
                    setM("LeftHip", CFrame.Angles(math.rad(15), 0, 0))
                    setM("RightKnee", CFrame.Angles(math.rad(-105), 0, 0))
                    setM("LeftKnee", CFrame.Angles(math.rad(-105), 0, 0))
                elseif poseName == "vecna_float" then
                    setM("Neck", CFrame.Angles(math.rad(55), 0, 0))
                    setM("Waist", CFrame.Angles(math.rad(28), 0, 0))
                    setM("RightShoulder", CFrame.Angles(math.rad(20), 0, math.rad(68) + wob))
                    setM("LeftShoulder", CFrame.Angles(math.rad(20), 0, math.rad(-68) - wob))
                    setM("RightHip", CFrame.Angles(math.rad(-18), 0, math.rad(18)))
                    setM("LeftHip", CFrame.Angles(math.rad(-18), 0, math.rad(-18)))
                elseif poseName == "vecna_snap" then
                    setM("Neck", CFrame.Angles(math.rad(75), math.rad(55), math.rad(40)), 0.6)
                    setM("RightShoulder", CFrame.Angles(math.rad(-110), math.rad(70), math.rad(125)), 0.6)
                    setM("LeftShoulder", CFrame.Angles(math.rad(130), math.rad(-60), math.rad(-120)), 0.6)
                    setM("RightHip", CFrame.Angles(math.rad(85), 0, math.rad(95)), 0.6)
                    setM("LeftHip", CFrame.Angles(math.rad(-75), 0, math.rad(-95)), 0.6)
                elseif poseName == "crucified" then
                    setM("Neck", CFrame.Angles(math.rad(-28), 0, math.rad(12)))
                    setM("RightShoulder", CFrame.Angles(0, 0, math.rad(88)))
                    setM("LeftShoulder", CFrame.Angles(0, 0, math.rad(-88)))
                    setM("RightHip", CFrame.Angles(math.rad(-10), 0, math.rad(-4)))
                    setM("LeftHip", CFrame.Angles(math.rad(-10), 0, math.rad(4)))
                elseif poseName == "electrocuted" then
                    local j = math.sin(t * 65) * 0.45
                    setM("Neck", CFrame.Angles(j, -j, j * 0.5), 0.8)
                    setM("Waist", CFrame.Angles(j * 0.6, j, 0), 0.8)
                    setM("RightShoulder", CFrame.Angles(math.rad(95) + j, 0, math.rad(45) - j), 0.8)
                    setM("LeftShoulder", CFrame.Angles(math.rad(95) - j, 0, math.rad(-45) + j), 0.8)
                    setM("RightHip", CFrame.Angles(j * 0.7, 0, 0), 0.8)
                    setM("LeftHip", CFrame.Angles(-j * 0.7, 0, 0), 0.8)
                elseif poseName == "drag_hell" then
                    local c = math.sin(t * 18) * 0.35
                    setM("Neck", CFrame.Angles(math.rad(55), 0, 0))
                    setM("RightShoulder", CFrame.Angles(math.rad(170) + c, 0, math.rad(12)))
                    setM("LeftShoulder", CFrame.Angles(math.rad(170) - c, 0, math.rad(-12)))
                elseif poseName == "flail" then
                    local f1 = math.sin(t * 22) * 1.1
                    local f2 = math.cos(t * 22) * 1.1
                    setM("RightShoulder", CFrame.Angles(math.rad(120) + f1, 0, math.rad(40)))
                    setM("LeftShoulder", CFrame.Angles(math.rad(120) + f2, 0, math.rad(-40)))
                    setM("RightHip", CFrame.Angles(f2 * 0.7, 0, 0))
                    setM("LeftHip", CFrame.Angles(f1 * 0.7, 0, 0))
                elseif poseName == "frozen_scream" then
                    setM("Neck", CFrame.Angles(math.rad(25), 0, 0), 0.7)
                    setM("RightShoulder", CFrame.Angles(math.rad(135), 0, math.rad(20)), 0.7)
                    setM("LeftShoulder", CFrame.Angles(math.rad(135), 0, math.rad(-20)), 0.7)
                    setM("RightElbow", CFrame.Angles(math.rad(75), 0, 0), 0.7)
                    setM("LeftElbow", CFrame.Angles(math.rad(75), 0, 0), 0.7)
                end
            else
                if poseName == "terror_up" then
                    setM("Neck", CFrame.Angles(math.rad(-42), 0, wob))
                    setM("Right Shoulder", CFrame.Angles(0, 0, math.rad(155) + wob))
                    setM("Left Shoulder", CFrame.Angles(0, 0, math.rad(-155) - wob))
                elseif poseName == "clutch_chest" then
                    setM("Neck", CFrame.Angles(math.rad(30), 0, wob * 2))
                    setM("Right Shoulder", CFrame.Angles(math.rad(35), math.rad(-45), math.rad(85)))
                    setM("Left Shoulder", CFrame.Angles(math.rad(35), math.rad(45), math.rad(-85)))
                elseif poseName == "kneel_bound" then
                    setM("Neck", CFrame.Angles(math.rad(45), 0, 0))
                    setM("Right Shoulder", CFrame.Angles(0, 0, math.rad(-40)))
                    setM("Left Shoulder", CFrame.Angles(0, 0, math.rad(40)))
                    setM("Right Hip", CFrame.Angles(0, 0, math.rad(-80)))
                    setM("Left Hip", CFrame.Angles(0, 0, math.rad(80)))
                elseif poseName == "vecna_float" then
                    setM("Neck", CFrame.Angles(math.rad(-45), 0, 0))
                    setM("Right Shoulder", CFrame.Angles(0, math.rad(-35), math.rad(75) + wob))
                    setM("Left Shoulder", CFrame.Angles(0, math.rad(35), math.rad(-75) - wob))
                elseif poseName == "vecna_snap" then
                    setM("Neck", CFrame.Angles(math.rad(-70), math.rad(55), math.rad(45)), 0.6)
                    setM("Right Shoulder", CFrame.Angles(math.rad(95), math.rad(65), math.rad(-130)), 0.6)
                    setM("Left Shoulder", CFrame.Angles(math.rad(-95), math.rad(-65), math.rad(130)), 0.6)
                    setM("Right Hip", CFrame.Angles(0, math.rad(60), math.rad(95)), 0.6)
                    setM("Left Hip", CFrame.Angles(0, math.rad(-60), math.rad(-95)), 0.6)
                elseif poseName == "crucified" then
                    setM("Right Shoulder", CFrame.Angles(0, 0, math.rad(90)))
                    setM("Left Shoulder", CFrame.Angles(0, 0, math.rad(-90)))
                elseif poseName == "electrocuted" then
                    local j = math.sin(t * 65) * 0.5
                    setM("Neck", CFrame.Angles(j, 0, -j), 0.8)
                    setM("Right Shoulder", CFrame.Angles(j, 0, math.rad(110) + j), 0.8)
                    setM("Left Shoulder", CFrame.Angles(-j, 0, math.rad(-110) - j), 0.8)
                elseif poseName == "drag_hell" then
                    local c = math.sin(t * 18) * 0.35
                    setM("Right Shoulder", CFrame.Angles(0, 0, math.rad(170) + c))
                    setM("Left Shoulder", CFrame.Angles(0, 0, math.rad(-170) - c))
                elseif poseName == "flail" then
                    local f1 = math.sin(t * 22) * 1.1
                    setM("Right Shoulder", CFrame.Angles(0, 0, math.rad(115) + f1))
                    setM("Left Shoulder", CFrame.Angles(0, 0, math.rad(-115) + f1))
                elseif poseName == "frozen_scream" then
                    setM("Right Shoulder", CFrame.Angles(0, 0, math.rad(135)), 0.7)
                    setM("Left Shoulder", CFrame.Angles(0, 0, math.rad(-135)), 0.7)
                end
            end
        end
        local function shakeCamera(intensity, duration)
            task.spawn(function()
                local cam = workspace.CurrentCamera
                if not cam then return end
                local t0 = os.clock()
                while (os.clock() - t0) < duration do
                    local p = (os.clock() - t0) / duration
                    local cur = intensity * (1 - p)
                    local dx = (math.random() - 0.5) * 2 * cur
                    local dy = (math.random() - 0.5) * 2 * cur
                    cam.CFrame = cam.CFrame * CFrame.Angles(math.rad(dx), math.rad(dy), math.rad(dx * 0.4))
                    RunService.RenderStepped:Wait()
                end
            end)
        end
        local function highlightVictim(targetChar, fillCol, outlineCol, duration)
            if not targetChar then return end
            local h = Instance.new("Highlight")
            h.Name = "HONKUKI_KillHighlight"
            h.FillColor = fillCol
            h.OutlineColor = outlineCol or Color3.fromRGB(255, 255, 255)
            h.FillTransparency = 0.2
            h.OutlineTransparency = 0.05
            h.Adornee = targetChar
            h.Parent = targetChar
            Debris:AddItem(h, duration)
            TweenService:Create(h, TweenInfo.new(duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                FillTransparency = 1,
                OutlineTransparency = 1
            }):Play()
        end
        local function spawnShockwaveRing(pos, color, maxRadius, duration)
            local ring = Instance.new("Part")
            ring.Name = "HONKUKI_ShockRing"
            ring.Shape = Enum.PartType.Cylinder
            ring.Material = Enum.Material.Neon
            ring.Color = color
            ring.Size = Vector3.new(0.35, 2.5, 2.5)
            ring.CFrame = CFrame.new(pos) * CFrame.Angles(0, 0, math.rad(90))
            ring.Anchored = true
            ring.CanCollide = false
            ring.Parent = workspace
            TweenService:Create(ring, TweenInfo.new(duration or 0.65, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                Size = Vector3.new(0.08, maxRadius or 38, maxRadius or 38),
                Transparency = 1
            }):Play()
            Debris:AddItem(ring, (duration or 0.65) + 0.1)
        end
        local function spawnParticleBurst(parentPart, count, colorSeq, sizeSeq, speedRange)
            local emitter = Instance.new("ParticleEmitter")
            emitter.Color = colorSeq
            emitter.Size = sizeSeq or NumberSequence.new({ NumberSequenceKeypoint.new(0, 1.8), NumberSequenceKeypoint.new(1, 0) })
            emitter.Speed = speedRange or NumberRange.new(35, 75)
            emitter.SpreadAngle = Vector2.new(180, 180)
            emitter.Lifetime = NumberRange.new(0.6, 1.4)
            emitter.Rate = 0
            emitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 1) })
            emitter.Parent = parentPart
            emitter:Emit(count or 50)
            Debris:AddItem(emitter, 1.8)
        end
        function rig:FinishDeath(style)
            pcall(function()
                if not char or not char.Parent then return end
                local deathPos = (hrp and hrp.Position) or (rig.baseCF and rig.baseCF.Position) or Vector3.zero
                local effectMap = {
                    ["supernova"] = KillEffects.supernova,
                    ["zeus"] = KillEffects.zeus_smite,
                    ["lightning"] = KillEffects.zeus_smite,
                    ["senbonzakura"] = KillEffects.senbonzakura,
                    ["sakura"] = KillEffects.senbonzakura,
                    ["slash"] = KillEffects.senbonzakura,
                    ["decapitate"] = KillEffects.senbonzakura,
                    ["black_hole"] = KillEffects.black_hole,
                    ["implode"] = KillEffects.black_hole,
                    ["void"] = KillEffects.black_hole,
                    ["malevolent_cleave"] = KillEffects.malevolent_cleave,
                    ["cleave"] = KillEffects.malevolent_cleave,
                    ["sukuna"] = KillEffects.malevolent_cleave,
                    ["angelic_rapture"] = KillEffects.angelic_rapture,
                    ["angel"] = KillEffects.angelic_rapture,
                    ["ice_shatter"] = KillEffects.ice_shatter,
                    ["shatter"] = KillEffects.ice_shatter,
                    ["ice"] = KillEffects.ice_shatter,
                    ["grim_reaper"] = KillEffects.grim_reaper,
                    ["reaper"] = KillEffects.grim_reaper,
                    ["soul"] = KillEffects.grim_reaper,
                    ["nuclear_detonation"] = KillEffects.nuclear_detonation,
                    ["blast"] = KillEffects.nuclear_detonation,
                    ["nuke"] = KillEffects.nuclear_detonation,
                    ["c4"] = KillEffects.nuclear_detonation,
                    ["dragon_hellfire"] = KillEffects.dragon_hellfire,
                    ["ash"] = KillEffects.dragon_hellfire,
                    ["fire"] = KillEffects.dragon_hellfire,
                    ["hellfire"] = KillEffects.dragon_hellfire,
                    ["cyber_matrix"] = KillEffects.cyber_matrix,
                    ["glitch"] = KillEffects.cyber_matrix,
                    ["confetti_party"] = KillEffects.confetti_party,
                    ["party"] = KillEffects.confetti_party,
                    ["flatten"] = KillEffects.nuclear_detonation
                }
                local selectedEffect = effectMap[style] or KillEffects.supernova
                selectedEffect(char, deathPos)
                for _, p in ipairs(char:GetDescendants()) do
                    if p:IsA("BasePart") then p.Anchored = false end
                end
                if char == LP.Character then
                    pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true) end)
                    pcall(function() hum:ChangeState(Enum.HumanoidStateType.Dead) end)
                    hum.Health = 0
                    pcall(function() char:BreakJoints() end)
                    task.delay(0.2, function()
                        local vHeight = (workspace.FallenPartsDestroyHeight or -500) - 250
                        if hrp and hrp.Parent then hrp.CFrame = CFrame.new(hrp.Position.X, vHeight, hrp.Position.Z) end
                    end)
                else
                    for _, p in ipairs(char:GetDescendants()) do
                        if p:IsA("BasePart") then
                            p.Transparency = 1
                            p.CanCollide = false
                        elseif p:IsA("Decal") then
                            p.Transparency = 1
                        end
                    end
                    pcall(function() char:BreakJoints() end)
                    pcall(function() hum.Health = 0 end)
                    local victimPlr = Players:GetPlayerFromCharacter(char)
                    if victimPlr and victimPlr ~= LP then
                        task.spawn(function()
                            if _G.HONKUKIFlingPlayer then
                                pcall(function() _G.HONKUKIFlingPlayer(victimPlr) end)
                            else
                                local myChar = LP.Character
                                local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                local tHrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
                                if myHrp and tHrp then
                                    local origCF = myHrp.CFrame
                                    local bav = Instance.new("BodyAngularVelocity")
                                    bav.AngularVelocity = Vector3.new(0, 999999, 0)
                                    bav.MaxTorque = Vector3.new(0, math.huge, 0)
                                    bav.P = math.huge
                                    bav.Parent = myHrp
                                    local t0 = tick()
                                    while tick() - t0 < 0.75 and tHrp.Parent and myHrp.Parent do
                                        myHrp.CFrame = tHrp.CFrame
                                        task.wait()
                                    end
                                    bav:Destroy()
                                    myHrp.Velocity = Vector3.zero
                                    myHrp.RotVelocity = Vector3.zero
                                    myHrp.CFrame = origCF
                                end
                            end
                        end)
                    end
                end
            end)
        end
        return rig
    end
    local function runPoseLoop(rig, poseName, duration, perFrameFn)
        local st = os.clock()
        while os.clock() - st < duration do
            if not rig.char or not rig.char.Parent then break end
            local elapsed = os.clock() - st
            rig:Pose(poseName, os.clock())
            if perFrameFn then pcall(perFrameFn, elapsed, elapsed / duration) end
            RunService.RenderStepped:Wait()
        end
    end
