    local function ExecuteBrutal(execId, extra, targetChar)
        task.spawn(function()
            local char = targetChar or LP.Character
            if not char then return end
            local isSpec = (char ~= LP.Character)
            local fn = Executions[tostring(execId or "nuke")] or Executions.nuke
            local rig = createVictimRig(char, isSpec)
            if not rig then return end
            local fx = Instance.new("Folder")
            fx.Name = "HONKUKI_ExecFX_" .. tostring(execId)
            fx.Parent = workspace
            Debris:AddItem(fx, 14)
            pcall(fn, rig, fx, extra)
        end)
    end
    local Weapons = {}
    local WeaponOrder = {
        "reaper_scythe", "yamato_katana", "cursed_dual_katana", "mjolnir_hammer",
        "infinity_gauntlet", "holy_excalibur", "megumin_staff", "cyber_railgun",
        "poseidon_trident", "hellfire_chain", "sith_lightsaber", "shadow_daggers",
        "gear5_gauntlets", "cyber_guitar", "celestial_bow", "mini_nuke_rpg",
        "gravity_gun", "elder_wand", "pumpkin_staff", "cyber_hoverboard",
        "witch_broom", "seraphim_wings", "ironman_repulsor", "royal_aegis"
    }
    do
        local function addBladeTrail(handle, p0Off, p1Off, col)
            local a0 = Instance.new("Attachment", handle)
            a0.Position = p0Off
            local a1 = Instance.new("Attachment", handle)
            a1.Position = p1Off
            local tr = Instance.new("Trail", handle)
            tr.Attachment0 = a0
            tr.Attachment1 = a1
            tr.Color = ColorSequence.new(col or Color3.fromRGB(255, 50, 90), Color3.fromRGB(255, 255, 255))
            tr.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.15),
                NumberSequenceKeypoint.new(1, 1)
            })
            tr.Lifetime = 0.28
            tr.LightEmission = 1
            tr.FaceCamera = true
            return tr
        end
        local function addGlow(part, col, range, bright)
            local pl = Instance.new("PointLight", part)
            pl.Color = col
            pl.Range = range or 14
            pl.Brightness = bright or 2.5
            return pl
        end
        local function playWeaponAnim(style, dur)
            task.spawn(function()
                local char = LP.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if not (char and hum) then return end
                local isR15 = (hum.RigType == Enum.HumanoidRigType.R15)
                local rMot, lMot, wMot
                for _, d in ipairs(char:GetDescendants()) do
                    if d:IsA("Motor6D") then
                        if d.Name == "RightShoulder" or d.Name == "Right Shoulder" then rMot = d
                        elseif d.Name == "LeftShoulder" or d.Name == "Left Shoulder" then lMot = d
                        elseif d.Name == "Waist" or d.Name == "RootJoint" then wMot = d end
                    end
                end
                local rOrig = rMot and rMot.C0
                local lOrig = lMot and lMot.C0
                local wOrig = wMot and wMot.C0
                local dTime = dur or 0.32
                local st = os.clock()
                while os.clock() - st < dTime do
                    local a = (os.clock() - st) / dTime
                    local swing = math.sin(a * math.pi)
                    pcall(function()
                        if isR15 then
                            if style == "slash_down" then
                                if rMot then rMot.C0 = rOrig * CFrame.Angles(math.rad(135 - a * 185), math.rad(-15), math.rad(-15)) end
                                if wMot then wMot.C0 = wOrig * CFrame.Angles(math.rad(-15 * swing), math.rad(-30 * swing), 0) end
                            elseif style == "slash_wide" then
                                if rMot then rMot.C0 = rOrig * CFrame.Angles(math.rad(85), math.rad(75 - a * 160), math.rad(25)) end
                                if wMot then wMot.C0 = wOrig * CFrame.Angles(0, math.rad(55 - a * 110), 0) end
                            elseif style == "dual_x" then
                                if rMot then rMot.C0 = rOrig * CFrame.Angles(math.rad(130 - a * 175), math.rad(35 - a * 70), 0) end
                                if lMot then lMot.C0 = lOrig * CFrame.Angles(math.rad(130 - a * 175), math.rad(-35 + a * 70), 0) end
                                if wMot then wMot.C0 = wOrig * CFrame.Angles(math.rad(-18 * swing), 0, 0) end
                            elseif style == "spin_360" then
                                if rMot then rMot.C0 = rOrig * CFrame.Angles(math.rad(90), 0, math.rad(75)) end
                                if wMot then wMot.C0 = wOrig * CFrame.Angles(0, a * math.pi * 2, 0) end
                            elseif style == "cast_sky" then
                                if rMot then rMot.C0 = rOrig * CFrame.Angles(math.rad(165 * swing), 0, math.rad(12)) end
                                if lMot then lMot.C0 = lOrig * CFrame.Angles(math.rad(145 * swing), 0, math.rad(-12)) end
                            elseif style == "shoot" then
                                local kick = math.sin(a * math.pi) * 28
                                if rMot then rMot.C0 = rOrig * CFrame.Angles(math.rad(90 + kick), 0, 0) end
                            end
                        else
                            if style == "slash_down" or style == "slash_wide" then
                                if rMot then rMot.C0 = rOrig * CFrame.Angles(0, 0, math.rad(130 - a * 180)) end
                            elseif style == "dual_x" then
                                if rMot then rMot.C0 = rOrig * CFrame.Angles(0, 0, math.rad(135 - a * 180)) end
                                if lMot then lMot.C0 = lOrig * CFrame.Angles(0, 0, math.rad(-135 + a * 180)) end
                            elseif style == "cast_sky" then
                                if rMot then rMot.C0 = rOrig * CFrame.Angles(0, 0, math.rad(160 * swing)) end
                            elseif style == "shoot" then
                                if rMot then rMot.C0 = rOrig * CFrame.Angles(0, 0, math.rad(90 + swing * 25)) end
                            end
                        end
                    end)
                    RunService.RenderStepped:Wait()
                end
                pcall(function()
                    if rMot and rOrig then rMot.C0 = rOrig end
                    if lMot and lOrig then lMot.C0 = lOrig end
                    if wMot and wOrig then wMot.C0 = wOrig end
                end)
            end)
        end
        local function spawnSlashWave(originCF, col, width, dist, speed)
            local wave = mkPart({
                Material = Enum.Material.Neon,
                Color = col or Color3.fromRGB(255, 40, 90),
                Size = Vector3.new(width or 12, 0.45, 3.2),
                CFrame = originCF * CFrame.new(0, 0, -3),
                Transparency = 0.1
            })
            local mesh = Instance.new("SpecialMesh", wave)
            mesh.MeshType = Enum.MeshType.Sphere
            TweenService:Create(wave, TweenInfo.new(speed or 0.55, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                CFrame = originCF * CFrame.new(0, 0, -(dist or 65)),
                Size = Vector3.new((width or 12) * 1.6, 0.25, 4.5),
                Transparency = 1
            }):Play()
            Debris:AddItem(wave, (speed or 0.55) + 0.05)
        end
        local function newBaseTool(name, tip, gripCF, handleProps)
            local tool = Instance.new("Tool")
            tool.Name = name
            tool.ToolTip = tip or name
            tool.RequiresHandle = true
            tool.CanBeDropped = false
            tool:SetAttribute("HONKUKICustomTool", true)
            if gripCF then tool.Grip = gripCF end
            local hProps = handleProps or {}
            hProps.Name = "Handle"
            hProps.Anchored = false
            hProps.CanCollide = false
            hProps.Parent = tool
            local handle = mkPart(hProps)
            return tool, handle
        end
        local function attachFlightSystem(tool, speed, extraRigFn)
            local flyConn, bv, bg, rigFolder
            tool.Equipped:Connect(function()
                local char = LP.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if not (char and hrp and hum) then return end
                rigFolder = Instance.new("Folder", char)
                rigFolder.Name = "HONKUKI_FlightRig"
                if extraRigFn then pcall(extraRigFn, char, hrp, rigFolder) end
                bv = Instance.new("BodyVelocity", hrp)
                bv.MaxForce = Vector3.new(9e5, 9e5, 9e5)
                bv.Velocity = Vector3.zero
                bg = Instance.new("BodyGyro", hrp)
                bg.MaxTorque = Vector3.new(9e5, 9e5, 9e5)
                bg.P = 12000
                bg.D = 600
                hum.PlatformStand = true
                playSfx(169445602, 2.5, 1.35, hrp, 3)
                local boostMult = 1
                tool.Activated:Connect(function()
                    boostMult = 2.6
                    playSfx(138186576, 3.5, 1.5, hrp, 3)
                    shakeCamera(1.4, 0.35)
                    spawnShockwave(hrp.Position, Color3.fromRGB(56, 189, 248), 22, 0.45)
                    task.delay(0.9, function() boostMult = 1 end)
                end)
                flyConn = RunService.RenderStepped:Connect(function()
                    if not (char.Parent and hrp.Parent and bv.Parent) then return end
                    local cam = workspace.CurrentCamera
                    if not cam then return end
                    local move = Vector3.zero
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then move = move + cam.CFrame.LookVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then move = move - cam.CFrame.LookVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then move = move + cam.CFrame.RightVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then move = move - cam.CFrame.RightVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then move = move + Vector3.new(0, 1, 0) end
                    if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then move = move - Vector3.new(0, 1, 0) end
                    if move.Magnitude < 0.05 and hum.MoveDirection.Magnitude > 0.05 then
                        move = cam.CFrame.LookVector
                    end
                    local spd = (speed or 95) * boostMult
                    bv.Velocity = (move.Magnitude > 0.05) and (move.Unit * spd) or Vector3.new(0, math.sin(os.clock() * 3) * 2.5, 0)
                    local bank = UserInputService:IsKeyDown(Enum.KeyCode.A) and 22 or (UserInputService:IsKeyDown(Enum.KeyCode.D) and -22 or 0)
                    bg.CFrame = cam.CFrame * CFrame.Angles(0, 0, math.rad(bank))
                end)
            end)
            tool.Unequipped:Connect(function()
                if flyConn then flyConn:Disconnect(); flyConn = nil end
                if bv then bv:Destroy(); bv = nil end
                if bg then bg:Destroy(); bg = nil end
                if rigFolder then rigFolder:Destroy(); rigFolder = nil end
                local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                if hum then hum.PlatformStand = false end
            end)
        end
        Weapons.reaper_scythe = function()
            local tool, h = newBaseTool("💀 เคียวยมทูต", "Soul Reaper Scythe", CFrame.new(0, -1.5, 0), {
