                local dome = mkPart({ Shape = Enum.PartType.Ball, Material = Enum.Material.ForceField, Color = Color3.fromRGB(70, 185, 255), Size = Vector3.new(22, 22, 22), CFrame = CFrame.new(domePos), Transparency = 0.35 })
                for i = 1, 12 do
                    local p1 = domePos + Vector3.new(math.random(-10,10), math.random(-10,10), math.random(-10,10))
                    local p2 = domePos + Vector3.new(math.random(-10,10), math.random(-10,10), math.random(-10,10))
                    local cut = mkPart({ Color = Color3.fromRGB(190, 240, 255), Size = Vector3.new(0.14, 0.14, (p1-p2).Magnitude), CFrame = CFrame.lookAt(p1:Lerp(p2,0.5), p2) })
                    TweenService:Create(cut, TweenInfo.new(0.35), { Transparency = 1 }):Play()
