        Weapons.cursed_dual_katana = function()
            local tool, h = newBaseTool("🔥 ดาบคู่ต้องสาป CDK", "Cursed Dual Katana", CFrame.new(0, -1.5, 0) * CFrame.Angles(math.rad(90), 0, 0), {
                Material = Enum.Material.Metal, Color = Color3.fromRGB(30, 12, 18), Size = Vector3.new(0.22, 1.5, 0.26)
            })
            local rBlade = mkPart({ Color = Color3.fromRGB(255, 35, 65), Size = Vector3.new(0.12, 5.4, 0.3), Parent = tool })
            weldTo(h, rBlade, CFrame.new(0, 3.5, 0))
            addBladeTrail(h, Vector3.new(0, 1, 0), Vector3.new(0, 6.2, 0), Color3.fromRGB(255, 30, 65))
            local offBlade
            tool.Equipped:Connect(function()
                local char = LP.Character
                local lHand = char and (char:FindFirstChild("LeftHand") or char:FindFirstChild("Left Arm"))
                if lHand then
                    offBlade = mkPart({ Color = Color3.fromRGB(168, 55, 255), Size = Vector3.new(0.12, 5.4, 0.3), Parent = char })
                    weldTo(lHand, offBlade, CFrame.new(0, -0.8, -2.5) * CFrame.Angles(math.rad(-90), 0, 0))
                    addBladeTrail(offBlade, Vector3.new(0, -2.6, 0), Vector3.new(0, 2.6, 0), Color3.fromRGB(168, 55, 255))
                end
            end)
            tool.Unequipped:Connect(function() if offBlade then offBlade:Destroy(); offBlade = nil end end)
            tool.Activated:Connect(function()
                local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                playWeaponAnim("dual_x", 0.3)
                playSfx(12222208, 4, 1.2, h, 2)
                spawnSlashWave(hrp.CFrame * CFrame.Angles(0, 0, math.rad(38)), Color3.fromRGB(255, 35, 65), 16, 80, 0.5)
                spawnSlashWave(hrp.CFrame * CFrame.Angles(0, 0, math.rad(-38)), Color3.fromRGB(168, 55, 255), 16, 80, 0.5)
                hrp.CFrame = hrp.CFrame * CFrame.new(0, 0, -14)
                shakeCamera(1.5, 0.3)
            end)
            return tool
        end
