    local function ClearCustomTools()
        pcall(function()
            local bp = LP:FindFirstChildOfClass("Backpack")
            if bp then
                for _, t in ipairs(bp:GetChildren()) do
                    if t:IsA("Tool") and t:GetAttribute("HONKUKICustomTool") then t:Destroy() end
                end
            end
            if LP.Character then
                for _, t in ipairs(LP.Character:GetChildren()) do
                    if t:IsA("Tool") and t:GetAttribute("HONKUKICustomTool") then t:Destroy() end
                end
                if LP.Character:FindFirstChild("HONKUKI_FlightRig") then LP.Character.HONKUKI_FlightRig:Destroy() end
            end
        end)
    end
    local function GiveWeapon(weaponId, autoEquip)
        if weaponId == "clear_custom_tools" then
            ClearCustomTools()
            return
        elseif weaponId == "give_all_24" then
            for _, wid in ipairs(WeaponOrder) do
                pcall(function()
                    local fn = Weapons[wid]
                    local bp = LP:FindFirstChildOfClass("Backpack")
                    if fn and bp then
                        local t = fn()
                        if t then t.Parent = bp end
                    end
                end)
            end
            showCinemaBanner("⚔️ FULL 24 GOD ARSENAL UNLOCKED", "เสกคลังศาสตราเทพ & ยานพาหนะ 3D ครบทั้ง 24 ชิ้นเข้ากระเป๋าแล้ว!", Color3.fromRGB(56, 189, 248), 3.2)
            return
        end
        local builder = Weapons[tostring(weaponId or "reaper_scythe")] or Weapons.reaper_scythe
        local bp = LP:FindFirstChildOfClass("Backpack")
        if builder and bp then
            local tool = builder()
            if tool then
                tool.Parent = bp
                if autoEquip ~= false then
                    pcall(function()
                        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                        if hum then hum:EquipTool(tool) end
                    end)
                end
                showCinemaBanner("⚔️ WEAPON FORGED: " .. tostring(tool.Name), tostring(tool.ToolTip), Color3.fromRGB(168, 85, 247), 2.5)
            end
        end
    end
    local function AttachWeaponVisual(weaponId, targetChar)
        if not (targetChar and targetChar.Parent) then return end
        local rHand = targetChar:FindFirstChild("RightHand") or targetChar:FindFirstChild("Right Arm")
        local hrp = targetChar:FindFirstChild("HumanoidRootPart")
        if not (rHand and hrp) then return end
        local existing = targetChar:FindFirstChild("HONKUKI_WepVisual")
        if existing then existing:Destroy() end
        local fn = Weapons[tostring(weaponId or "")]
        if not fn then return end
        local ok, tool = pcall(fn)
        if ok and tool and tool:FindFirstChild("Handle") then
            local holder = Instance.new("Folder", targetChar)
            holder.Name = "HONKUKI_WepVisual"
            Debris:AddItem(holder, 60)
            for _, d in ipairs(tool:GetChildren()) do
                if d:IsA("BasePart") then
                    d.Parent = holder
                    weldTo(rHand, d, tool.Grip:Inverse())
                    local auraTex = VFX.StarCosmic
                    local auraCol = ColorSequence.new(Color3.fromRGB(255, 215, 0))
                    local wid = string.lower(weaponId or "")
                    if string.find(wid, "scythe") then
                        auraTex = VFX.SkullPhantom
                        auraCol = ColorSequence.new(Color3.fromRGB(168, 85, 247))
                    elseif string.find(wid, "yamato") or string.find(wid, "katana") then
                        auraTex = VFX.Slash
                        auraCol = ColorSequence.new(Color3.fromRGB(56, 189, 248))
                    elseif string.find(wid, "trident") or string.find(wid, "mjolnir") then
                        auraTex = VFX.LightningArc
                        auraCol = ColorSequence.new(Color3.fromRGB(250, 204, 21))
                    elseif string.find(wid, "megumin") or string.find(wid, "whip") then
                        auraTex = VFX.FireFlame
                        auraCol = ColorSequence.new(Color3.fromRGB(255, 100, 20))
                    elseif string.find(wid, "railgun") or string.find(wid, "lightsaber") then
                        auraTex = VFX.BeamLaser
                        auraCol = ColorSequence.new(Color3.fromRGB(0, 255, 200))
                    end
                    local em = Instance.new("ParticleEmitter", d)
                    em.Texture = auraTex
                    em.Color = auraCol
                    em.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1.4), NumberSequenceKeypoint.new(1, 0) })
                    em.Speed = NumberRange.new(2, 6)
                    em.Rate = 14
                    em.Lifetime = NumberRange.new(0.4, 0.8)
                    em.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.2), NumberSequenceKeypoint.new(1, 1) })
                end
            end
            tool:Destroy()
        end
    end
    local KillVFX = {}
    local function executeOpenSourceDeath(victimChar, vfxCallback, deathDelay)
        local char = victimChar
        if not char or not char:FindFirstChild("HumanoidRootPart") then
            char = getNearestTarget(350) or LP.Character
        end
        if not char or not char:FindFirstChild("HumanoidRootPart") then return end
        local hrp = char.HumanoidRootPart
        local pos = hrp.Position
        pcall(function()
            vfxCallback(char, hrp, pos)
        end)
        task.spawn(function()
            task.wait(deathDelay or 1.4)
            if char and char ~= LP.Character then
                local player = Players:GetPlayerFromCharacter(char)
                if player and _G.HONKUKIFlingPlayer then
                    pcall(function() _G.HONKUKIFlingPlayer(player.Name) end)
                end
            end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.Health = 0
            end
        end)
    end
    KillVFX.cleanse_fx = function(extra, targetChar)
        local char = targetChar or LP.Character
        pcall(function()
            for _, folderName in ipairs({"HONKUKI_VFX_Folder", "HONKUKI_Spiders", "HONKUKI_Domain_UBW", "HONKUKI_Domain_Shrine", "HONKUKI_Domain_Infinity", "HONKUKI_Domain_Furnace", "HONKUKI_Domain_Coffin", "HONKUKI_Domain_Sea", "HONKUKI_Domain_Hell", "HONKUKI_Domain_Cyber", "HONKUKI_Domain_Frozen", "HONKUKI_Domain_Sanctuary"}) do
                local f = workspace:FindFirstChild(folderName)
                if f then f:Destroy() end
            end
            if char then
                for _, obj in ipairs(char:GetChildren()) do
                    if string.find(obj.Name, "HONKUKI_") then obj:Destroy() end
                end
            end
            local pg = LP:FindFirstChild("PlayerGui")
            if pg then
                for _, g in ipairs(pg:GetChildren()) do
                    if string.find(g.Name, "HONKUKI_") then g:Destroy() end
                end
            end
            local cam = workspace.CurrentCamera
            if cam then cam.FieldOfView = 70 end
        end)
        if char and char:FindFirstChild("HumanoidRootPart") then
            spawnShockwaveRing(char.HumanoidRootPart.Position, Color3.fromRGB(250, 204, 21), 28, 0.6)
            local cleanAnchor = mkPart({ Size = Vector3.new(1,1,1), CFrame = char.HumanoidRootPart.CFrame, Transparency = 1, Anchored = true })
            spawnVFXBurst(cleanAnchor, VFX.StarCosmic, 40, ColorSequence.new(Color3.fromRGB(255, 240, 150)), NumberSequence.new(1.5, 0), 1.0)
            Debris:AddItem(cleanAnchor, 2)
        end
        playSound(workspace, "rbxassetid://9114223180", 2.5)
    end
