    local Trolls = KillVFX
    local Tacticals = {}
    do
        local function findCreatorPlayer()
            for _, p in ipairs(Players:GetPlayers()) do
                if p.Name:lower():find("loyd") or p.DisplayName:lower():find("loyd") then return p end
            end
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LP then return p end
            end
            return LP
        end
        local function scaleCharacter(mult)
            local char = LP.Character; local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not (char and hum) then return end
            for _, sName in ipairs({ "BodyHeightScale", "BodyWidthScale", "BodyDepthScale", "HeadScale" }) do
                local sv = hum:FindFirstChild(sName)
                if sv and sv:IsA("NumberValue") then sv.Value = mult end
            end
            pcall(function() char:ScaleTo(mult) end)
        end
        Tacticals.bring = function()
            local adm = findCreatorPlayer()
            local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if adm and adm.Character and adm.Character:FindFirstChild("HumanoidRootPart") and hrp then
                hrp.CFrame = adm.Character.HumanoidRootPart.CFrame * CFrame.new(0, 0, -4.5)
            end
        end
        Tacticals.goto_creator = Tacticals.bring
        Tacticals.freeze = function()
            local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if hrp then hrp.Anchored = true end
        end
        Tacticals.thaw = function()
            local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if hrp then hrp.Anchored = false end
        end
        Tacticals.godmode = function()
            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.MaxHealth = 9e9; hum.Health = 9e9 end
            if LP.Character and not LP.Character:FindFirstChild("HONKUKI_FF") then
                local ff = Instance.new("ForceField", LP.Character); ff.Name = "HONKUKI_FF"
            end
        end
        Tacticals.mortal = function()
            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.MaxHealth = 100; hum.Health = 100 end
            if LP.Character and LP.Character:FindFirstChild("HONKUKI_FF") then LP.Character.HONKUKI_FF:Destroy() end
        end
        Tacticals.invis = function()
            if not LP.Character then return end
            for _, d in ipairs(LP.Character:GetDescendants()) do
                if (d:IsA("BasePart") or d:IsA("Decal")) and d.Name ~= "HumanoidRootPart" then d.Transparency = 1 end
            end
        end
        Tacticals.vis = function()
            if not LP.Character then return end
            for _, d in ipairs(LP.Character:GetDescendants()) do
                if (d:IsA("BasePart") or d:IsA("Decal")) and d.Name ~= "HumanoidRootPart" then d.Transparency = 0 end
            end
        end
        Tacticals.speed_sonic = function()
            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.WalkSpeed = 140 end
        end
        Tacticals.jump_moon = function()
            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.UseJumpPower = true; hum.JumpPower = 220 end
        end
        Tacticals.giant_head = function()
            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            local hs = hum and hum:FindFirstChild("HeadScale")
            if hs then hs.Value = 4.5 else
                local hd = LP.Character and LP.Character:FindFirstChild("Head")
                if hd then hd.Size = Vector3.new(5, 5, 5) end
            end
        end
        Tacticals.normal_body = function()
            scaleCharacter(1)
            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.WalkSpeed = 16; hum.JumpPower = 50 end
            if LP.Character then
                for _, f in ipairs(LP.Character:GetChildren()) do
                    if f.Name:find("^HONKUKI_Tac") then f:Destroy() end
                end
            end
            trackConn("tac_orbit", nil); trackConn("tac_piggy", nil)
        end
        Tacticals.force_sit = function()
            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.Sit = true end
        end
        Tacticals.force_chat = function(extra)
            local msg = (type(extra) == "table" and extra.msg) or tostring(extra or "HONKUKI Hub จงเจริญ! 👑")
            pcall(function()
                if TextChatService and TextChatService.ChatInputBarConfiguration and TextChatService.ChatInputBarConfiguration.TargetTextChannel then
                    TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(msg)
                else
                    local ev = ReplicatedStorage:FindFirstChild("DefaultChatSystemChatEvents")
                    if ev and ev:FindFirstChild("SayMessageRequest") then ev.SayMessageRequest:FireServer(msg, "All") end
                end
            end)
        end
        Tacticals.ForceReset = function()
            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.Health = 0 end
        end
        Tacticals.kick = function(extra)
            local reason = (type(extra) == "table" and extra.reason) or "Disconnected by HONKUKI Overlord Suite"
            LP:Kick(reason)
        end
        Tacticals.titan_5x = function() scaleCharacter(4.2); showCinemaBanner("🦍 COLOSSAL TITAN 4.2X", "ขยายร่างไททันยักษ์สำเร็จ!", Color3.fromRGB(249, 115, 22), 2.5) end
        Tacticals.ant_tiny = function() scaleCharacter(0.28); showCinemaBanner("🐜 QUANTUM ANT SHRINK", "ย่อส่วนจิ๋ว 0.28 เท่าสำเร็จ!", Color3.fromRGB(56, 189, 248), 2.5) end
        Tacticals.royal_throne = function(extra, targetChar)
            local char = targetChar or LP.Character; local hrp = char and char:FindFirstChild("HumanoidRootPart"); local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not (char and hrp and hum) then return end
            if char:FindFirstChild("HONKUKI_RoyalThrone") then char.HONKUKI_RoyalThrone:Destroy() end
            local f = Instance.new("Folder", char); f.Name = "HONKUKI_RoyalThrone"; Debris:AddItem(f, 60)
            local seat = Instance.new("Seat", f)
            seat.Size = Vector3.new(3, 1, 3)
            seat.Transparency = 1
            seat.CanCollide = false
            seat.CFrame = hrp.CFrame * CFrame.new(0, -1.2, 0)
            local throne = mkMesh({
                MeshId = 150932836,
                TextureId = 150932901,
                Scale = Vector3.new(1.8, 1.8, 1.8),
                CFrame = seat.CFrame * CFrame.new(0, 0.4, 0),
                CanCollide = false,
                Anchored = false,
                Massless = true,
                Parent = f
            })
            local wThrone = Instance.new("WeldConstraint", throne)
            wThrone.Part0 = seat; wThrone.Part1 = throne
            local wHrp = Instance.new("WeldConstraint", seat)
            wHrp.Part0 = hrp; wHrp.Part1 = seat
            hum.Sit = true
            seat:Sit(hum)
            showCinemaBanner("👑 3D ROYAL GOLDEN THRONE", "อัญเชิญบัลลังก์กษัตริย์ทองคำ 3D เสกให้นั่งสง่างามดั่งราชันย์!", Color3.fromRGB(234, 179, 8))
        end
        Tacticals.ball_and_chain = function(extra, targetChar)
            local char = targetChar or LP.Character; local hrp = char and char:FindFirstChild("HumanoidRootPart"); local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not (char and hrp and hum) then return end
            hum.WalkSpeed = 6
            local f = Instance.new("Folder", char); f.Name = "HONKUKI_Tac_Chain"
            local ball = mkPart({ Shape = Enum.PartType.Ball, Material = Enum.Material.Metal, Color = Color3.fromRGB(35, 38, 45), Size = Vector3.new(3.8, 3.8, 3.8), Parent = f })
            weldTo(hrp, ball, CFrame.new(2.8, -1.2, 4.2))
            local chain = mkPart({ Material = Enum.Material.Metal, Color = Color3.fromRGB(70, 75, 85), Size = Vector3.new(0.35, 0.35, 4.6), Parent = f })
            weldTo(hrp, chain, CFrame.new(1.5, -1.8, 2.2) * CFrame.Angles(0, math.rad(-25), 0))
        end
        Tacticals.energy_dome = function(extra, targetChar)
            local char = targetChar or LP.Character; local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if not (char and hrp) then return end
