        local Orbit3D = {}
        local PI = math.pi
        local TAU = math.pi * 2
        function Orbit3D.Look(pos, target, rollDeg)
            local diff = target - pos
            if diff.Magnitude < 0.001 then diff = Vector3.new(0, 0, -1) end
            local fwd = diff.Unit
            local ny = math.clamp((math.abs(fwd.Y) - 0.72) / 0.28, 0, 1)
            local smoothNy = ny * ny * (3 - 2 * ny)
            local up = Vector3.new(0.15 * smoothNy, 1 - 0.85 * smoothNy, 0.98 * smoothNy).Unit
            local cf = CFrame.lookAt(pos, pos + fwd, up)
            if rollDeg and rollDeg ~= 0 then
                cf = cf * CFrame.Angles(0, 0, math.rad(rollDeg))
            end
            return cf
        end
        function Orbit3D.SymmetryPair(i, total)
            if i == total then return 0, total, total end
            local side = (i % 2 == 0) and 1 or -1
            local rank = math.ceil(i / 2)
            local maxR = math.floor((total - 1) / 2)
            return side, rank, maxR
        end
        function Orbit3D.B001(t, i, total, r)
            local side, rank, maxR = Orbit3D.SymmetryPair(i, total)
            local S = r * 2.2
            if side == 0 then
                local bob = math.sin(t * 4) * (r * 0.25)
                local pos = Vector3.new(0, 5.5 + bob, 1.0)
                return CFrame.new(pos) * CFrame.Angles(0, t * 6, math.rad(45))
            end
            local u = rank / maxR
            local beat = math.sin(t * 3.2 - u * 1.8)
            local flare = 1.15 + 0.20 * math.sin(t * 1.6)
            local spanX = side * (1.5 + (u ^ 0.85) * S * 1.45 * flare)
            local archY = 1.5 + math.sin(u * PI * 0.85) * (S * 0.85) + beat * (u * S * 0.45) - (u ^ 2) * (S * 0.35)
            local sweepZ = 2.0 + math.cos(beat * 0.8) * (u * S * 0.55) + u * 2.5
            local pos = Vector3.new(spanX, archY, sweepZ)
            local tipTarget = pos + Vector3.new(side * 4, beat * 2 - u * 2, 2)
            return Orbit3D.Look(pos, tipTarget, side * 35)
        end
