    local PuppetState = { fwd = 0, right = 0, lastTick = 0, sprint = false }
    trackConn("puppet_mover", RunService.RenderStepped:Connect(function()
        if os.clock() - PuppetState.lastTick > 0.85 then return end
        if PuppetState.fwd == 0 and PuppetState.right == 0 then return end
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hum and hrp then
            if PuppetState.sprint and hum.WalkSpeed < 36 then hum.WalkSpeed = 42 end
            local look = Vector3.new(hrp.CFrame.LookVector.X, 0, hrp.CFrame.LookVector.Z)
            if look.Magnitude < 0.01 then look = Vector3.new(0, 0, -1) else look = look.Unit end
            local rightV = Vector3.new(hrp.CFrame.RightVector.X, 0, hrp.CFrame.RightVector.Z)
            if rightV.Magnitude < 0.01 then rightV = Vector3.new(1, 0, 0) else rightV = rightV.Unit end
            hum:Move(look * PuppetState.fwd + rightV * PuppetState.right, false)
        end
    end))
    local function PuppetInput(pld)
        if type(pld) ~= "table" then return end
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if pld.active == false then
            PuppetState.fwd = 0
            PuppetState.right = 0
            return
        end
        PuppetState.lastTick = os.clock()
        if pld.w ~= nil or pld.s ~= nil then
            PuppetState.fwd = (pld.w and 1 or 0) - (pld.s and 1 or 0)
        elseif pld.fwd ~= nil then
            PuppetState.fwd = tonumber(pld.fwd) or 0
        end
        if pld.a ~= nil or pld.d ~= nil then
            PuppetState.right = (pld.d and 1 or 0) - (pld.a and 1 or 0)
        elseif pld.right ~= nil then
            PuppetState.right = tonumber(pld.right) or 0
        end
        if pld.sprint ~= nil then PuppetState.sprint = (pld.sprint == true) end
        if pld.speed and hum then hum.WalkSpeed = tonumber(pld.speed) or 28 end
        if pld.sit ~= nil and hum then hum.Sit = (pld.sit == true) end
        if pld.jump and hum then hum.Jump = true; hum:ChangeState(Enum.HumanoidStateType.Jumping) end
        if pld.yaw ~= nil and hrp then
            hrp.CFrame = CFrame.new(hrp.Position) * CFrame.Angles(0, math.rad(tonumber(pld.yaw) or 0), 0)
        elseif pld.turn and hrp then
            hrp.CFrame = hrp.CFrame * CFrame.Angles(0, math.rad(tonumber(pld.turn) or 0), 0)
        end
        if pld.dash and hrp then hrp.Velocity = hrp.CFrame.LookVector * 140 + Vector3.new(0, 35, 0) end
    end
    local function PuppetStunt(stuntId)
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not (char and hum and hrp) then return end
        trackConn("puppet_stunt", nil)
        if stuntId == "stop_stunt" then
            hum.PlatformStand = false; hum.Sit = false; hum.WalkSpeed = 16; hrp.Anchored = false
        elseif stuntId == "backflip" or stuntId == "frontflip" then
            local dir = (stuntId == "backflip") and 1 or -1
            task.spawn(function()
                local base = hrp.CFrame
                for i = 1, 24 do
                    local a = i / 24
                    hrp.CFrame = (base * CFrame.new(0, math.sin(a * math.pi) * 9, dir * a * 6)) * CFrame.Angles(dir * a * math.pi * 2, 0, 0)
                    RunService.RenderStepped:Wait()
                end
            end)
        elseif stuntId == "breakdance" then
            local st = os.clock()
            trackConn("puppet_stunt", RunService.RenderStepped:Connect(function()
                if os.clock() - st > 8 then trackConn("puppet_stunt", nil); return end
                hrp.CFrame = CFrame.new(hrp.Position) * CFrame.Angles(math.rad(75), os.clock() * 18, 0)
            end))
        elseif stuntId == "moonwalk" then
            local st = os.clock()
            trackConn("puppet_stunt", RunService.RenderStepped:Connect(function()
                if os.clock() - st > 6 then trackConn("puppet_stunt", nil); return end
                hrp.CFrame = hrp.CFrame * CFrame.new(0, 0, 0.28)
            end))
        elseif stuntId == "levitate_zen" then
            local base = hrp.CFrame
            hrp.Anchored = true; hum.Sit = true
            trackConn("puppet_stunt", RunService.RenderStepped:Connect(function()
                hrp.CFrame = base * CFrame.new(0, 5.5 + math.sin(os.clock() * 2.5) * 1.2, 0) * CFrame.Angles(0, os.clock() * 0.8, 0)
            end))
        elseif stuntId == "play_dead" then
            hum.PlatformStand = true
            hrp.CFrame = hrp.CFrame * CFrame.new(0, -1.5, 0) * CFrame.Angles(math.rad(90), 0, 0)
        elseif stuntId == "super_jump" then
            hrp.Velocity = Vector3.new(0, 240, 0)
            spawnShockwave(hrp.Position, Color3.fromRGB(56, 189, 248), 22, 0.5)
        elseif stuntId == "headspin" then
            local st = os.clock()
            trackConn("puppet_stunt", RunService.RenderStepped:Connect(function()
                if os.clock() - st > 8 then trackConn("puppet_stunt", nil); return end
                hrp.CFrame = CFrame.new(hrp.Position) * CFrame.Angles(math.rad(180), os.clock() * 22, 0)
            end))
        elseif stuntId == "drop_tools" then
            hum:UnequipTools()
        elseif stuntId == "walk_to_creator" then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LP and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                    hum:MoveTo(p.Character.HumanoidRootPart.Position)
                    break
                end
            end
        elseif stuntId == "cheer_jump" then
            pcall(function() Players:Chat("/e cheer") end); hum.Jump = true
        elseif stuntId == "dab_pose" or stuntId == "t_pose" or stuntId == "bow_respect" or stuntId == "zombie_walk" or stuntId == "air_swim" or stuntId == "crab_walk" then
            pcall(function() Players:Chat("/e dance3") end)
            if stuntId == "air_swim" then
                local st = os.clock()
                trackConn("puppet_stunt", RunService.RenderStepped:Connect(function()
                    if os.clock() - st > 8 then trackConn("puppet_stunt", nil); return end
                    hrp.CFrame = hrp.CFrame * CFrame.new(0, math.sin(os.clock()*4)*0.15, -0.35)
                end))
            end
        end
    end
