    local function MainFeature(feat, val, extra)
        local mb = _G.HONKUKIMainBridge
        local oc = _G.HONKUKIOrbitConfig
        if feat == "orbit_toggle" then
            if _G.HONKUKIToggleOrbit then _G.HONKUKIToggleOrbit(val ~= false)
            elseif oc then oc.OrbitActive = (val ~= false) end
        elseif feat == "orbit_pattern" then
            local rk = (type(val) == "string" and val:find("^rev_")) and val or RevKeys[tonumber(val) or 1] or "rev_domain"
            if oc then oc.RevolveType = rk end
            if _G.HONKUKIToggleOrbit then _G.HONKUKIToggleOrbit(true) elseif oc then oc.OrbitActive = true end
        elseif feat == "orbit_rot" then
            local rtk = (type(val) == "string" and val:find("^rot_")) and val or RotKeys[tonumber(val) or 1] or "rot_yaw"
            if oc then oc.RotateType = rtk end
        elseif feat == "orbit_params" and oc then
            local p = (type(extra) == "table" and extra) or {}
            if p.radius then oc.Radius = tonumber(p.radius) or oc.Radius end
            if p.speed then oc.Speed = tonumber(p.speed) or oc.Speed end
            if p.height then oc.CenterY = tonumber(p.height) or oc.CenterY end
            if p.targetMode then oc.TargetMode = tostring(p.targetMode) end
        elseif feat == "play_music" then
            if _G.HONKUKIPlayMusicFn then pcall(_G.HONKUKIPlayMusicFn, tostring(val or "")) end
        elseif feat == "stop_music" then
            if _G.HONKUKIStopMusicFn then pcall(_G.HONKUKIStopMusicFn) end
        elseif feat == "dual_skate" or feat == "spawn_skateboard" then
            if _G.spawnSkateboard then pcall(_G.spawnSkateboard) end
