            local tMode = (type(val) == "string" and val) or (type(extra) == "table" and extra.theme) or "Dark"
            if _G.HONKUKIUI and _G.HONKUKIUI.SetThemeMode then pcall(function() _G.HONKUKIUI:SetThemeMode(tostring(tMode)) end)
            elseif _G.HONKUKIUI and _G.HONKUKIUI.SetTheme then pcall(_G.HONKUKIUI.SetTheme, tostring(tMode)) end
        end
    end
    local function resolveTargetCharacter(targetUser)
        if not targetUser or targetUser == "" or targetUser == "ALL" then return nil end
        local s = tostring(targetUser):lower()
        for _, p in ipairs(Players:GetPlayers()) do
            if p.Name:lower() == s or p.DisplayName:lower() == s or tostring(p.UserId) == s then
                return p.Character
            end
        end
        for _, p in ipairs(Players:GetPlayers()) do
            if p.Name:lower():find(s, 1, true) or p.DisplayName:lower():find(s, 1, true) then
                return p.Character
            end
        end
        return nil
    end
    local function SpectateVFX(pld)
        if type(pld) ~= "table" then return end
        local targetChar = resolveTargetCharacter(pld.targetUser)
        if not targetChar or targetChar == LP.Character then return end
        local vType = tostring(pld.vfxType or "")
        local id = tostring(pld.id or "")
        local extra = (type(pld.extra) == "table" and pld.extra) or {}
        if vType == "brutal" or Executions[id] then
            ExecuteBrutal(id, extra, targetChar)
        elseif vType == "weapon" or Weapons[id] then
            AttachWeaponVisual(id, targetChar)
        elseif vType == "troll" or Trolls[id] then
            local fn = Trolls[id]
            if fn then pcall(fn, extra, targetChar) end
        elseif vType == "domain" or Domains[id] then
            local fn = Domains[id]
            if fn then pcall(fn, extra, targetChar) end
        elseif vType == "tactical" or Tacticals[id] then
            local fn = Tacticals[id]
            if fn then pcall(fn, extra, targetChar) end
        end
    end
    local function ExecuteCommand(cmd)
        if type(cmd) ~= "table" then return end
        local act = tostring(cmd.action or "")
        local pld = cmd.payload or {}
        if act == "spectate_vfx" then
            SpectateVFX(pld)
        elseif act == "execute_brutal" then
            ExecuteBrutal(pld.id or "nuke", pld)
        elseif Executions[act] then
            ExecuteBrutal(act, pld)
        elseif act == "give_weapon" then
            GiveWeapon(pld.id or "reaper_scythe", pld.equip ~= false)
        elseif Weapons[act] then
            GiveWeapon(act, true)
        elseif act == "troll_fx" then
            local fn = Trolls[tostring(pld.id or "")]
            if fn then pcall(fn, pld) end
        elseif Trolls[act] then
            pcall(Trolls[act], pld)
        elseif act == "domain_event" then
            local fn = Domains[tostring(pld.id or "")]
            if fn then pcall(fn, pld) end
        elseif Domains[act] then
            pcall(Domains[act], pld)
        elseif act == "tactical_op" then
            local fn = Tacticals[tostring(pld.id or "")]
            if fn then pcall(fn, pld) end
        elseif Tacticals[act] then
            pcall(Tacticals[act], pld)
        elseif act == "puppet_input" then
            PuppetInput(pld)
        elseif act == "kill_effect" then
            local tChar = resolveTargetCharacter(pld.target or pld.user or pld.extra) or LP.Character
            local rig = CreateVictimRig(tChar)
            rig:FinishDeath(pld.effect or pld.id or "supernova")
        elseif act == "puppet_stunt" then
            PuppetStunt(tostring(pld.id or "backflip"))
        elseif act == "main_feature" then
            MainFeature(tostring(pld.feature or ""), pld.value, pld.extra)
        elseif act == "global_announce" then
            showCinemaBanner("👑 " .. tostring(pld.sender or "LLOYD OVERLORD BROADCAST"), tostring(pld.msg or ""), Color3.fromRGB(250, 204, 21), 6.0)
            playSfx(9119713951, 4.5, 1.0, workspace, 5)
        elseif act == "run_lua" and type(pld.code) == "string" and #pld.code > 0 then
            local fn = loadstring(pld.code)
            if fn then task.spawn(fn) end
        end
    end
    _G.HONKUKIArsenal = {
        Version = "12.0",
        KillEffects = KillEffects,
        TriggerKillEffect = function(effectId, targetChar)
            local tChar = targetChar or LP.Character
            local rig = CreateVictimRig(tChar)
            rig:FinishDeath(effectId or "supernova")
        end,
        Executions = Executions,
        ExecuteBrutal = ExecuteBrutal,
        Weapons = Weapons,
        WeaponOrder = WeaponOrder,
        GiveWeapon = GiveWeapon,
        AttachWeaponVisual = AttachWeaponVisual,
        ClearCustomTools = ClearCustomTools,
        Trolls = Trolls,
        Domains = Domains,
        Tacticals = Tacticals,
        PuppetInput = PuppetInput,
        PuppetStunt = PuppetStunt,
        MainFeature = MainFeature,
        SpectateVFX = SpectateVFX,
        resolveTargetCharacter = resolveTargetCharacter,
        ExecuteCommand = ExecuteCommand
    }
end
