                Title = "Teleport",
                Content = AppState.LangMode == "th" and "ไม่พบตัวละครของผู้เล่นเป้าหมายในขณะนี้" or "Target player is not available",
                Icon = Icons.Close
            })
            return
        end
        local myChar = LocalPlayer.Character
