local function getBoomboxTool()
    local char = LocalPlayer.Character
    if char then
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") and string.lower(child.Name):find("boombox", 1, true) then return child end
        end
    end
    local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
    if bp then
        for _, child in ipairs(bp:GetChildren()) do
            if child:IsA("Tool") and string.lower(child.Name):find("boombox", 1, true) then return child end
        end
    end
    return nil
end
local function equipBoombox()
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local tool = getBoomboxTool()
    if not tool and ToolPicker then
        pcall(function() ToolPicker:InvokeServer("PickingTools", "Boombox") end)
        local start = os.clock()
        while os.clock() - start < 1.5 do
            tool = getBoomboxTool()
            if tool then break end
            task.wait(0.05)
        end
    end
    if tool then
        for _, p in ipairs(tool:GetDescendants()) do
            if p:IsA("BasePart") then p.LocalTransparencyModifier = 0 end
            if p:IsA("Sound") and (p.Name == "PlayersChoice" or p.Name == "120232514292241" or p.Name == _G.HONKUKICurrentSongName or p.Name == "กันดักลอยด์ 4  argon" or p:FindFirstAncestorOfClass("Tool")) then
                local targetTitle = _G.HONKUKICurrentSongName or "กันดักลอยด์ 4  argon"
                pcall(function() p.Name = targetTitle end)
            end
        end
    end
    if tool and char and tool.Parent ~= char then
        if hum then hum:EquipTool(tool) else tool.Parent = char end
        task.wait(0.1)
    end
    return tool
end
