local _HEAVY_CONTAINER_SOUND_CACHE = setmetatable({}, { __mode = "k" })
local function getCachedContainerSounds(container, forceRefresh)
    local now = os.clock()
    local cached = _HEAVY_CONTAINER_SOUND_CACHE[container]
    if not forceRefresh and cached and (now - cached.ts) < 4.5 then
        return cached.sounds
    end
    local sounds = {}
    for _, d in ipairs(container:GetDescendants()) do
        if d:IsA("Sound") then
            table.insert(sounds, d)
        end
    end
    _HEAVY_CONTAINER_SOUND_CACHE[container] = { sounds = sounds, ts = now }
    return sounds
end
local function invalidateContainerSoundCache(inst)
    if not inst then
        _HEAVY_CONTAINER_SOUND_CACHE = setmetatable({}, { __mode = "k" })
        return
    end
    local cur = inst
    while cur do
        if _HEAVY_CONTAINER_SOUND_CACHE[cur] then
            _HEAVY_CONTAINER_SOUND_CACHE[cur] = nil
        end
        cur = cur.Parent
    end
end
local function isLikelySfxSoundName(lowerName)
    if KNOWN_MUSIC_SOUND_NAMES[lowerName] then return false end
