        _PREWARMED_TITLE_IDS[cidStr] = true
        getSongNameAsync(cidStr)
    end
    return true, cleanRealId, (wasProtected or isObfuscatedPayload)
end
local function doesModelBelongToPlayer(model, p, pLower, pHum)
    if not model or not p then return false end
    if pHum and pHum.SeatPart and pHum.SeatPart:IsDescendantOf(model) then
        return true
    end
    local mLower = (model.Name or ""):lower()
    if mLower == pLower or mLower == (pLower .. "car") or mLower == (pLower .. "horse") then
        return true
    end
    if #pLower >= 3 then
        local idx = mLower:find(pLower, 1, true)
        if idx then
            local beforeCh = (idx > 1) and mLower:sub(idx - 1, idx - 1) or ""
            local afterPos = idx + #pLower
            local afterCh = (afterPos <= #mLower) and mLower:sub(afterPos, afterPos) or ""
            local sepBefore = (beforeCh == "" or not beforeCh:match("[%w_]"))
            local sepAfter = (afterCh == "" or not afterCh:match("[%w_]") or mLower:sub(afterPos, afterPos + 2) == "car" or mLower:sub(afterPos, afterPos + 4) == "horse")
            if sepBefore and sepAfter then
                return true
            end
        end
    end
    local attrKeys = { "Owner", "Player", "PlayerName", "HouseOwner", "UserId", "OwnerId" }
    for _, key in ipairs(attrKeys) do
        local okA, attrVal = pcall(function() return model:GetAttribute(key) end)
        if okA and attrVal ~= nil then
            if type(attrVal) == "string" and attrVal:lower() == pLower then
                return true
            elseif type(attrVal) == "number" and attrVal == p.UserId then
                return true
            end
        end
    end
    local valNames = { "Owner", "PlayerObject", "HouseOwner", "PlayerName", "Player", "User" }
    for _, vName in ipairs(valNames) do
        local ch = model:FindFirstChild(vName)
        if ch then
            if ch:IsA("ObjectValue") and (ch.Value == p or (p.Character and ch.Value == p.Character)) then
                return true
            elseif ch:IsA("StringValue") and ch.Value:lower() == pLower then
                return true
            elseif (ch:IsA("IntValue") or ch:IsA("NumberValue")) and ch.Value == p.UserId then
                return true
            end
        end
    end
    return false
end
local function extractModelOwnerMeta(model)
    local meta = {
        mLower = (model.Name or ""):lower(),
        strOwners = {},
        numOwners = {},
        objOwners = {},
    }
    local attrKeys = { "Owner", "Player", "PlayerName", "HouseOwner", "UserId", "OwnerId" }
    for _, key in ipairs(attrKeys) do
        local okA, attrVal = pcall(function() return model:GetAttribute(key) end)
        if okA and attrVal ~= nil then
            if type(attrVal) == "string" and attrVal ~= "" then
                table.insert(meta.strOwners, attrVal:lower())
            elseif type(attrVal) == "number" then
                table.insert(meta.numOwners, attrVal)
            end
        end
    end
    local valNames = { "Owner", "PlayerObject", "HouseOwner", "PlayerName", "Player", "User" }
    for _, vName in ipairs(valNames) do
        local ch = model:FindFirstChild(vName)
        if ch then
            if ch:IsA("ObjectValue") and ch.Value then
                table.insert(meta.objOwners, ch.Value)
            elseif ch:IsA("StringValue") and ch.Value ~= "" then
                table.insert(meta.strOwners, ch.Value:lower())
            elseif (ch:IsA("IntValue") or ch:IsA("NumberValue")) then
                table.insert(meta.numOwners, ch.Value)
            end
        end
    end
    return meta
end
local function matchModelOwnerMeta(model, meta, p, pLower, pHum)
    if pHum and pHum.SeatPart and pHum.SeatPart:IsDescendantOf(model) then
        return true
    end
    local mLower = meta.mLower
    if mLower == pLower or mLower == (pLower .. "car") or mLower == (pLower .. "horse") then
        return true
    end
    if #pLower >= 3 then
        local idx = mLower:find(pLower, 1, true)
        if idx then
            local beforeCh = (idx > 1) and mLower:sub(idx - 1, idx - 1) or ""
            local afterPos = idx + #pLower
            local afterCh = (afterPos <= #mLower) and mLower:sub(afterPos, afterPos) or ""
            local sepBefore = (beforeCh == "" or not beforeCh:match("[%w_]"))
            local sepAfter = (afterCh == "" or not afterCh:match("[%w_]") or mLower:sub(afterPos, afterPos + 2) == "car" or mLower:sub(afterPos, afterPos + 4) == "horse")
            if sepBefore and sepAfter then
                return true
            end
        end
    end
    for _, sOwn in ipairs(meta.strOwners) do
        if sOwn == pLower then return true end
    end
    for _, nOwn in ipairs(meta.numOwners) do
        if nOwn == p.UserId then return true end
    end
    for _, oOwn in ipairs(meta.objOwners) do
        if oOwn == p or (p.Character and oOwn == p.Character) then return true end
    end
    return false
end
local function formatAloggerRawPreview(rawSoundId, maxLen)
    local rawStr = tostring(rawSoundId or "")
    if rawStr == "" then return "—" end
    local limit = maxLen or 110
    local cleanAscii = rawStr:gsub("[%c]", " ")
    if #cleanAscii <= limit then
        return cleanAscii
    end
    local head = cleanAscii:sub(1, math.floor(limit * 0.62))
    local tail = cleanAscii:sub(-math.floor(limit * 0.28))
    return string.format("%s ... %s (%d chars)", head, tail, #rawStr)
end
local function scanActiveMusicPlayers(includeUndecoded)
    local myChar = LocalPlayer.Character
    local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
    local myPos = (myHrp and myHrp.Position) or Vector3.zero
    local results = {}
    local vehiclesFolder = workspace:FindFirstChild("Vehicles")
    local vehicleEntries = {}
    if vehiclesFolder then
        for _, veh in ipairs(vehiclesFolder:GetChildren()) do
            table.insert(vehicleEntries, { model = veh, meta = extractModelOwnerMeta(veh) })
        end
    end
    local lotsFolder = workspace:FindFirstChild("001_Lots")
    local lotEntries = {}
    if lotsFolder then
        for _, lot in ipairs(lotsFolder:GetChildren()) do
            table.insert(lotEntries, { model = lot, meta = extractModelOwnerMeta(lot) })
        end
    end
    local noMotorWsEntries = {}
    local horseWsEntries = {}
    for _, obj in ipairs(workspace:GetChildren()) do
        if obj:IsA("Model") or obj:IsA("Folder") then
            local oName = obj.Name
            if oName == "NoMotorVehicleModel" then
                table.insert(noMotorWsEntries, { model = obj, meta = extractModelOwnerMeta(obj) })
            elseif oName:lower():find("horse", 1, true) then
                table.insert(horseWsEntries, { model = obj, meta = extractModelOwnerMeta(obj) })
            end
        end
    end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            local foundEntries = {}
            local seenSoundInsts = {}
            local seenSourceTrackKeys = {}
            local pChar = p.Character
            local pHum = pChar and pChar:FindFirstChildOfClass("Humanoid")
            local pLower = (p.Name or ""):lower()
            local function recordSoundMatch(desc, sourceTag, cId, wProt)
                if not desc or seenSoundInsts[desc] then return end
                seenSoundInsts[desc] = true
                local rawSid = getEffectiveSoundUri(desc)
                local dedupTrack = tostring(cId or rawSid)
                local srcKey = sourceTag .. "|" .. dedupTrack
                if seenSourceTrackKeys[srcKey] then return end
                seenSourceTrackKeys[srcKey] = true
                table.insert(foundEntries, {
                    sound = desc,
                    source = sourceTag,
                    preDecodedId = cId,
                    preWasProtected = wProt,
                    rawSid = rawSid,
                })
            end
            local function scanContainer(container, sourceTag, requireKnownOrLong, strictNonMusicTool, useCachedSounds)
                if not container then return false end
                local matchedAny = false
                if useCachedSounds then
                    local cachedList = getCachedContainerSounds(container, false)
                    for _, desc in ipairs(cachedList) do
                        if desc.Parent and desc.Name == "PlayersChoice" then
                            local okSnd, cId, wProt = isSoundValidPlayerMusic(desc, false, false)
                            if okSnd then
                                recordSoundMatch(desc, sourceTag, cId, wProt)
                                matchedAny = true
                            end
                        end
                    end
                    for _, desc in ipairs(cachedList) do
                        if desc.Parent and desc.Name ~= "PlayersChoice" then
                            local okSnd, cId, wProt = isSoundValidPlayerMusic(desc, requireKnownOrLong, strictNonMusicTool)
                            if okSnd then
                                recordSoundMatch(desc, sourceTag, cId, wProt)
                                matchedAny = true
                            end
                        end
                    end
                    return matchedAny
                end
                for _, desc in ipairs(container:GetDescendants()) do
                    if desc:IsA("Sound") then
                        if desc.Name == "PlayersChoice" then
                            local okSnd, cId, wProt = isSoundValidPlayerMusic(desc, false, false)
                            if okSnd then
                                recordSoundMatch(desc, sourceTag, cId, wProt)
                                matchedAny = true
                            end
                        else
                            local okSnd, cId, wProt = isSoundValidPlayerMusic(desc, requireKnownOrLong, strictNonMusicTool)
                            if okSnd then
                                recordSoundMatch(desc, sourceTag, cId, wProt)
                                matchedAny = true
                            end
                        end
                    end
                end
                return matchedAny
            end
            local function checkPlayerTools(container)
                if not container then return false end
                local matchedAny = false
                local fallbackTools = {}
                for _, item in ipairs(container:GetChildren()) do
                    if item:IsA("Tool") then
                        local tLower = item.Name:lower()
                        if tLower:find("boombox", 1, true)
                            or tLower:find("gramophone", 1, true)
                            or tLower:find("radio", 1, true)
                            or tLower:find("speaker", 1, true)
                            or tLower:find("stereo", 1, true)
                            or tLower:find("music", 1, true)
                            or tLower:find("jukebox", 1, true)
                            or tLower:find("megaphone", 1, true)
                            or tLower:find("dj", 1, true)
                        then
                            if scanContainer(item, "Boombox", true, false, false) then
                                matchedAny = true
                            end
                        else
                            table.insert(fallbackTools, item)
                        end
                    end
                end
                for _, item in ipairs(fallbackTools) do
                    if scanContainer(item, "Boombox", true, true, false) then
                        matchedAny = true
                    end
                end
                return matchedAny
            end
            local function checkNoMotorInContainer(container)
                if not container then return false end
                local matchedAny = false
                for _, child in ipairs(container:GetChildren()) do
                    if child.Name == "NoMotorVehicleModel" then
                        if scanContainer(child, "NoMotorVehicle", true, false, false) then
                            matchedAny = true
                        end
                    end
                end
                return matchedAny
            end
            if pChar then
                checkPlayerTools(pChar)
                checkNoMotorInContainer(pChar)
            end
            local wsPlr = workspace:FindFirstChild(p.Name)
            if wsPlr and wsPlr ~= pChar then
                checkNoMotorInContainer(wsPlr)
            end
            if p:FindFirstChild("Backpack") then
                checkPlayerTools(p.Backpack)
            end
            if pHum and pHum.SeatPart then
                local seatModel = pHum.SeatPart:FindFirstAncestorOfClass("Model")
                if seatModel and seatModel ~= pChar then
                    local smLower = seatModel.Name:lower()
                    local tag = (seatModel.Name == "NoMotorVehicleModel") and "NoMotorVehicle"
                        or (smLower:find("horse", 1, true) and "Horse" or "Vehicle")
                    scanContainer(seatModel, tag, true, false, false)
                end
            end
            for _, entry in ipairs(noMotorWsEntries) do
                if matchModelOwnerMeta(entry.model, entry.meta, p, pLower, pHum) then
                    scanContainer(entry.model, "NoMotorVehicle", true, false, false)
                end
            end
            for _, entry in ipairs(horseWsEntries) do
                if matchModelOwnerMeta(entry.model, entry.meta, p, pLower, pHum) then
                    scanContainer(entry.model, "Horse", true, false, false)
                end
            end
            for _, entry in ipairs(vehicleEntries) do
                if matchModelOwnerMeta(entry.model, entry.meta, p, pLower, pHum) then
                    local tag = entry.model.Name:lower():find("horse", 1, true) and "Horse" or "Vehicle"
                    scanContainer(entry.model, tag, true, false, false)
                end
            end
            for _, entry in ipairs(lotEntries) do
                if matchModelOwnerMeta(entry.model, entry.meta, p, pLower, pHum) then
                    scanContainer(entry.model, "House", true, false, true)
                end
            end
            if pChar then
                scanContainer(pChar, "Character", true, false, false)
            end
            if wsPlr and wsPlr ~= pChar then
                scanContainer(wsPlr, "Character", true, false, false)
            end
            for _, fEntry in ipairs(foundEntries) do
                local foundSound = fEntry.sound
                local foundSource = fEntry.source
                local rawSid = fEntry.rawSid or getEffectiveSoundUri(foundSound)
                local pHrp = pChar and pChar:FindFirstChild("HumanoidRootPart")
                local targetPos = (pHrp and pHrp.Position)
                    or (foundSound.Parent and foundSound.Parent:IsA("BasePart") and foundSound.Parent.Position)
                if not targetPos then
                    local ancPart = foundSound:FindFirstAncestorOfClass("BasePart")
                    if ancPart then
                        targetPos = ancPart.Position
                    else
                        local ancModel = foundSound:FindFirstAncestorOfClass("Model")
                        if ancModel and type(ancModel.GetPivot) == "function" then
                            local okPiv, cf = pcall(function() return ancModel:GetPivot() end)
                            if okPiv and cf then targetPos = cf.Position end
                        end
                    end
                end
                local dist = myHrp and ((targetPos or myPos) - myPos).Magnitude or 0
                local cleanRealId = fEntry.preDecodedId
                local wasProtected = fEntry.preWasProtected
                if not cleanRealId and not wasProtected then
                    cleanRealId, wasProtected = decodeAudioId(rawSid, true)
                end
                local isObf = wasProtected or (#rawSid > 60) or (rawSid:find("%", 1, true) ~= nil) or (rawSid:find("&", 1, true) ~= nil)
                local bypassOk = (cleanRealId ~= nil and cleanRealId ~= "" and cleanRealId ~= "0")
                if bypassOk and _G.HONKUKIIgnoredVehicleSfxIds and _G.HONKUKIIgnoredVehicleSfxIds[tostring(cleanRealId)] then
                    bypassOk = false
                end
                if bypassOk or includeUndecoded then
                    if not (cleanRealId and _G.HONKUKIIgnoredVehicleSfxIds and _G.HONKUKIIgnoredVehicleSfxIds[tostring(cleanRealId)]) then
                        local resolvedIdStr = bypassOk and cleanRealId or "PROTECTED_V15"
                        table.insert(results, {
                            player = p,
                            name = p.Name,
                            displayName = p.DisplayName,
                            distance = dist,
                            realId = resolvedIdStr,
                            rawSoundId = rawSid,
                            wasProtected = isObf,
                            bypassSuccess = bypassOk,
                            source = foundSource,
                            entryKey = p.Name .. "|" .. foundSource .. "|" .. tostring(resolvedIdStr),
                            songTitle = (cleanRealId and songNameCache[tostring(cleanRealId)]) or nil,
                        })
                    end
                end
            end
        end
    end
    table.sort(results, function(a, b)
        if math.abs(a.distance - b.distance) > 0.5 then
            return a.distance < b.distance
        end
        return tostring(a.entryKey) < tostring(b.entryKey)
    end)
    return results
end
