local function findVehicleMusicSound(nmModel, targetTitle)
    if not nmModel then return nil end
    local sfxNames = { Engine = true, Rolling = true, Brake = true, Horn = true, Bell = true }
    local preferred = { "WindDiving_Whoosh", "PlayersChoice", "Music", "120232514292241" }
    for _, pname in ipairs(preferred) do
        local cand = nmModel:FindFirstChild(pname, true)
        if cand and cand:IsA("Sound") and not sfxNames[cand.Name] then
            return cand
        end
    end
    if targetTitle and not sfxNames[targetTitle] then
        for _, d in ipairs(nmModel:GetDescendants()) do
            if d:IsA("Sound") and d.Name == targetTitle and not d.SoundId:find("123728962822472", 1, true) then
                return d
            end
        end
    end
    for _, d in ipairs(nmModel:GetDescendants()) do
        if d:IsA("Sound") and not sfxNames[d.Name] and not d.SoundId:find("123728962822472", 1, true) then
            return d
        end
    end
    return nmModel:FindFirstChildWhichIsA("Sound", true)
end
local function applySafeSoundFallback(snd, expectedUri)
    if not snd then return end
    if #expectedUri >= 200000 then
        expectedUri = string.sub(expectedUri, 1, 199500)
    end
    local waited = 0
    while waited < 1.1 do
        local sid = snd.SoundId
        if sid ~= "" and sid ~= "rbxassetid://0" and sid:sub(1, 13) == "rbxassetid://" then
            if snd.IsPlaying then
                return
            end
            break
        end
        task.wait(0.1)
        waited = waited + 0.1
    end
    if snd.SoundId == "" or snd.SoundId == "rbxassetid://0" then
        pcall(function()
            snd.SoundId = expectedUri
        end)
    end
    if not snd.IsPlaying then
        pcall(function()
            snd.Looped = true
            if snd.Volume <= 0.05 then snd.Volume = 1 end
            snd:Play()
        end)
    end
end
