            local expectedUri = "rbxassetid://" .. payloadToSend
            applySafeSoundFallback(snd, expectedUri)
            if snd and HONKUKIUI.NowPlayingCard and HONKUKIUI.NowPlayingCard.SetActiveSound then
                HONKUKIUI.NowPlayingCard:SetActiveSound(snd)
            end
        end)
    end
    local devDisplay = (useBoombox and useRideable and ("Boombox + " .. selectedRideable))
        or (useBoombox and "Boombox")
        or selectedRideable
    HONKUKIUI:Notify({
        Title = AppState.LangMode == "en" and "Playing (V16 Protected)" or "กำลังเล่นเพลง (เกราะกันดัก V16)",
        Content = (AppState.LangMode == "en" and "Device: " or "อุปกรณ์: ") .. devDisplay .. " | " .. (customSongTitle or (_G.HONKUKISongTitleCache and _G.HONKUKISongTitleCache[cleaned]) or "Protected Audio"),
        Icon = Icons.Play
    })
    if HONKUKIUI.NowPlayingCard then
        local targetTitle = antiStealEnabled and "กันดักลอยด์ 4  argon" or (_G.HONKUKICurrentSongName or "กันดักลอยด์ 4  argon")
        local char = LocalPlayer.Character
        local nmModel = char and char:FindFirstChild("NoMotorVehicleModel")
        local activeSnd = findVehicleMusicSound(nmModel, targetTitle)
            or (char and char:FindFirstChild("Boombox") and (char.Boombox:FindFirstChild(targetTitle, true) or char.Boombox:FindFirstChild("กันดักลอยด์ 4  argon", true) or char.Boombox:FindFirstChild("PlayersChoice", true) or char.Boombox:FindFirstChild("120232514292241", true) or char.Boombox:FindFirstChildWhichIsA("Sound", true)))
        if activeSnd then
            pcall(function() activeSnd.Name = targetTitle end)
            if HONKUKIUI.NowPlayingCard.SetActiveSound then
                HONKUKIUI.NowPlayingCard:SetActiveSound(activeSnd)
            end
        end
        HONKUKIUI.NowPlayingCard:Show(cleaned, customSongTitle or (_G.HONKUKISongTitleCache and _G.HONKUKISongTitleCache[cleaned]) or _G.HONKUKICurrentSongName, devDisplay, playlistContext)
    end
end
