local function escapeRichText(str)
    str = tostring(str or "")
    str = str:gsub("&", "&amp;")
    str = str:gsub("<", "&lt;")
    str = str:gsub(">", "&gt;")
    str = str:gsub('"', "&quot;")
    str = str:gsub("'", "&apos;")
    return str
end
local function analyzeRawPayloadForAlogger(rawStr, realIdStr)
    rawStr = tostring(rawStr or "")
    realIdStr = tostring(realIdStr or "")
    local entries = {}
    local realStart, realEnd, realHow = nil, nil, "direct"
    if realIdStr ~= "" and realIdStr ~= "0" and realIdStr ~= "PROTECTED_V15" then
        local initPos = 1
        local lastDirectStart, lastDirectEnd = nil, nil
        while initPos <= #rawStr do
            local ds, de = rawStr:find(realIdStr, initPos, true)
            if not ds then break end
            lastDirectStart, lastDirectEnd = ds, de
            local prevSlice = rawStr:sub(math.max(1, ds - 16), ds - 1):lower()
            if prevSlice:find("id=", 1, true) then
                realStart, realEnd, realHow = ds, de, "direct"
            end
            initPos = de + 1
        end
        if not realStart and lastDirectStart then
            realStart, realEnd, realHow = lastDirectStart, lastDirectEnd, "direct"
        end
        if not realStart then
            local pos = 1
            local n = #rawStr
            while pos <= n do
                local nextAmp = rawStr:find("[&%?\n]", pos)
                local segEnd = nextAmp and (nextAmp - 1) or n
                if segEnd >= pos then
                    local seg = rawStr:sub(pos, segEnd)
                    local dec = decodeAudioId(seg, true)
                    if tostring(dec or "") == realIdStr then
                        realStart, realEnd, realHow = pos, segEnd, "encoded"
                        break
                    end
                    local compactDigits = seg:gsub("%%%s*3%s*(%d)", "%1"):gsub("%%%s*[0-9A-Fa-f]%s*[0-9A-Fa-f]", ""):gsub("%D+", "")
                    if compactDigits == realIdStr or (realIdStr ~= "" and compactDigits:find(realIdStr, 1, true)) then
                        realStart, realEnd, realHow = pos, segEnd, "encoded"
                        break
                    end
                end
                if not nextAmp then break end
                pos = nextAmp + 1
            end
        end
    end
    local searchIdx = 1
    while searchIdx <= #rawStr do
        local s, e = rawStr:find("%d%d%d%d+", searchIdx)
        if not s then break end
        local numStr = rawStr:sub(s, e)
        local strippedNum = numStr:match("^0*(%d+)") or numStr
        local isRealHere = false
        if realIdStr ~= "" and (numStr == realIdStr or strippedNum == realIdStr) then
            if not realStart or (s >= realStart and e <= realEnd) then
                isRealHere = true
            end
        end
        table.insert(entries, {
            num = numStr,
            startPos = s,
            endPos = e,
            isReal = isRealHere,
            how = (strippedNum ~= numStr) and "zeropad" or "direct",
        })
        searchIdx = e + 1
    end
    local foundRealInEntries = false
    for _, ent in ipairs(entries) do
        if ent.isReal then
            foundRealInEntries = true
            if not realStart then
                realStart, realEnd = ent.startPos, ent.endPos
            end
            break
        end
    end
    if not foundRealInEntries and realIdStr ~= "" and realIdStr ~= "0" and realIdStr ~= "PROTECTED_V15" then
        for _, ent in ipairs(entries) do
            local strippedNum = ent.num:match("^0*(%d+)") or ent.num
            if ent.num == realIdStr or strippedNum == realIdStr then
                ent.isReal = true
                foundRealInEntries = true
                realStart, realEnd = ent.startPos, ent.endPos
                break
            end
        end
    end
    if not foundRealInEntries and realIdStr ~= "" and realIdStr ~= "0" and realIdStr ~= "PROTECTED_V15" then
        local insStart = realStart or math.max(1, #rawStr)
        local insEnd = realEnd or #rawStr
        local inserted = false
        for i, ent in ipairs(entries) do
            if insStart < ent.startPos then
                table.insert(entries, i, {
                    num = realIdStr,
                    startPos = insStart,
                    endPos = insEnd,
                    isReal = true,
                    how = realHow or "encoded",
                })
                inserted = true
                break
            end
        end
        if not inserted then
            table.insert(entries, {
                num = realIdStr,
                startPos = insStart,
                endPos = insEnd,
                isReal = true,
                how = realHow or "encoded",
            })
        end
    end
    local realOrderIdx = nil
    for i, ent in ipairs(entries) do
        ent.order = i
        if ent.isReal and not realOrderIdx then
            realOrderIdx = i
        end
    end
    local totalCount = #entries
    local fakeCount = math.max(0, totalCount - (realOrderIdx and 1 or 0))
    local beforeFakeCount = realOrderIdx and math.max(0, realOrderIdx - 1) or 0
    local afterFakeCount = realOrderIdx and math.max(0, totalCount - realOrderIdx) or 0
    local beforeRealCtx = ""
    if realStart and realStart > 1 then
        beforeRealCtx = rawStr:sub(math.max(1, realStart - 48), realStart - 1):lower()
    end
    local hasIdParam = (beforeRealCtx:find("id=", 1, true) ~= nil)
        or (beforeRealCtx:find("id%3d", 1, true) ~= nil)
        or (beforeRealCtx:find("assetid", 1, true) ~= nil)
    local hasUrlHex = (rawStr:find("%%%x%x") ~= nil)
    local hasZeroPad = false
    if realStart and realEnd then
        local rawSlice = rawStr:sub(realStart, realEnd)
        if rawSlice:match("^0+%d") then hasZeroPad = true end
    end
    local reasonTh, reasonEn
    if totalCount <= 1 and not rawStr:find("[&%?]") then
        reasonTh = "เหตุผล: เป็นรหัสเพลงมาตรฐานที่ต่อท้าย rbxassetid:// โดยตรง ไม่มีเลขขยะหรือพารามิเตอร์หลอกพ่วงมา"
        reasonEn = "Reason: Clean standard SoundId directly after rbxassetid:// with no bait or decoy parameters."
    elseif realHow == "encoded" or hasUrlHex or hasZeroPad then
        local techTh = (realHow == "encoded" or hasUrlHex) and "เข้ารหัสอำพราง (URL/Hex Encoding)" or "เติมเลขศูนย์นำหน้า (Zero-Padding)"
        local techEn = (realHow == "encoded" or hasUrlHex) and "URL/Hex encoding" or "leading zero-padding"
        reasonTh = string.format(
            "เหตุผล: เลขชุดนี้ (ลำดับที่ #%d จาก %d ชุด) อยู่หลังพารามิเตอร์บังคับใช้จริงและถูก%sเพื่อหลบตัวดึงทั่วไป ส่วนเลขอื่นอีก %d ชุดเป็นตัวล่อ (Bait)",
            realOrderIdx or 1, totalCount, techTh, fakeCount
        )
        reasonEn = string.format(
            "Reason: Position #%d of %d sits in the active parameter and uses %s to evade basic loggers, while the other %d numbers are bait.",
            realOrderIdx or 1, totalCount, techEn, fakeCount
        )
    elseif hasIdParam and beforeFakeCount > 0 then
        if afterFakeCount > 0 then
            reasonTh = string.format(
                "เหตุผล: อยู่หลังพารามิเตอร์ &id= ตัวที่มีผลจริง (ลำดับที่ #%d) ซึ่งระบบ Roblox จะใช้ทับค่าเลขหลอกด้านหน้า %d ชุด และข้ามเลขพารามิเตอร์ปลอมด้านหลังอีก %d ชุด",
                realOrderIdx or 1, beforeFakeCount, afterFakeCount
            )
            reasonEn = string.format(
                "Reason: Located at active &id= parameter (pos #%d), which overrides %d preceding bait number(s) while ignoring %d trailing decoy parameter(s).",
                realOrderIdx or 1, beforeFakeCount, afterFakeCount
            )
        else
            reasonTh = string.format(
                "เหตุผล: อยู่หลังพารามิเตอร์ &id= ตัวสุดท้าย (ลำดับที่ #%d จาก %d ชุด) ซึ่งระบบ Roblox จะใช้ค่าตัวสุดท้ายทับเลขหลอกด้านหน้าทั้ง %d ชุด",
                realOrderIdx or 1, totalCount, beforeFakeCount
            )
            reasonEn = string.format(
                "Reason: Located at the final &id= parameter (pos #%d of %d), overriding all %d preceding bait number(s) in Roblox's URI parser.",
                realOrderIdx or 1, totalCount, beforeFakeCount
            )
        end
    elseif (realOrderIdx == 1) and afterFakeCount > 0 then
        reasonTh = string.format(
            "เหตุผล: เลขลำดับที่ #1 อยู่หลัง rbxassetid:// โดยตรง ส่วนเลขต่อท้ายอีก %d ชุดอยู่ในพารามิเตอร์ปลอม (Decoy Keys) ที่ระบบ Roblox ไม่อ่านค่า",
            afterFakeCount
        )
        reasonEn = string.format(
            "Reason: Position #1 sits directly after rbxassetid://, while the %d trailing number(s) are inside dummy parameters ignored by Roblox.",
            afterFakeCount
        )
    else
        reasonTh = string.format(
            "เหตุผล: ผ่านการคัดกรองโครงสร้าง URI และตัดรหัสเสียงหลอกออกทั้งหมด จึงระบุได้ว่าลำดับที่ #%d จาก %d ชุดคือรหัสเพลงที่เล่นจริง",
            realOrderIdx or 1, math.max(1, totalCount)
        )
        reasonEn = string.format(
            "Reason: Verified via URI parser after stripping decoy/SFX bait IDs; position #%d of %d is the active audio track.",
            realOrderIdx or 1, math.max(1, totalCount)
        )
    end
    return {
        entries = entries,
        totalCount = totalCount,
        fakeCount = fakeCount,
        realOrderIdx = realOrderIdx,
        realStart = realStart,
        realEnd = realEnd,
        realHow = realHow,
        rawLen = #rawStr,
        reasonTh = reasonTh,
        reasonEn = reasonEn,
    }
end
