scrollToRealIdInDrawer = function()
    if not currentCardTarget then return end
    if not isAloggerExpanded then
        isAloggerExpanded = true
        renderAloggerDrawer()
    elseif not activeRealTargetFrame or not activeRealTargetFrame.Parent then
        renderAloggerDrawer()
    end
    task.spawn(function()
        RunService.Heartbeat:Wait()
        RunService.Heartbeat:Wait()
        if not activeRealTargetFrame or not activeRealTargetFrame.Parent then return end
        local targetY = (activeRealTargetFrame.AbsolutePosition.Y - adScroll.AbsolutePosition.Y) + adScroll.CanvasPosition.Y - 8
        targetY = math.max(0, targetY)
        pcall(function()
            TweenService:Create(
                adScroll,
                TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                { CanvasPosition = Vector2.new(0, targetY) }
            ):Play()
        end)
        if activeRealTargetStroke and activeRealTargetStroke.Parent then
            activeRealTargetStroke.Thickness = 2
            activeRealTargetStroke.Transparency = 0
            task.delay(0.9, function()
                if activeRealTargetStroke and activeRealTargetStroke.Parent then
                    activeRealTargetStroke.Thickness = 1.2
                    activeRealTargetStroke.Transparency = 0.2
                end
            end)
        end
    end)
end
