    PlaySound(Sounds.Click, 0.8)
    scrollToRealIdInDrawer()
end)
renderAloggerDrawer = function()
    local isEn = (AppState.LangMode == "en")
    if not currentCardTarget then
        aloggerDrawerWrap.Visible = false
        return
    end
    aloggerDrawerWrap.Visible = true
    local rawStr = tostring(currentCardTarget.rawSoundId or "")
    local realIdStr = tostring(currentCardTarget.realId or "")
    local info = analyzeRawPayloadForAlogger(rawStr, realIdStr)
    local fakeEntries = {}
    for _, ent in ipairs(info.entries) do
        if not ent.isReal then
            table.insert(fakeEntries, ent)
        end
    end
    local displayReal = (realIdStr ~= "" and realIdStr) or "—"
    rhValueLbl.Text = "<u>" .. escapeRichText(displayReal) .. "</u>"
    rhCopyBtn.Text = isEn and "Copy Real ID" or "คัดลอกเลขจริง"
    rhJumpBtn.Text = isEn and "Jump to Real ID" or "เลื่อนไปหาเลขจริง"
    adCopyFullStrBtn.Text = isEn and "Copy Full String" or "คัดลอก String ทั้งหมด"
    if info.realOrderIdx then
        rhTitleLbl.Text = isEn
            and string.format("REAL AUDIO ID (Underlined)  •  Position #%d of %d", info.realOrderIdx, info.totalCount)
            or string.format("เลขเพลงจริง (ขีดเส้นใต้)  •  อยู่ลำดับที่ #%d จากทั้งหมด %d ชุด", info.realOrderIdx, info.totalCount)
    else
        rhTitleLbl.Text = isEn and "REAL AUDIO ID (Decoded)" or "เลขเพลงจริงที่ถอดรหัสได้"
    end
    rhReasonLbl.Text = isEn and info.reasonEn or info.reasonTh
    adSummaryLbl.Text = isEn
        and string.format("Bait: %d  |  String: %d chars", #fakeEntries, info.rawLen)
        or string.format("เลขหลอก: %d ชุด  |  ความยาว String: %d ตัวอักษร", #fakeEntries, info.rawLen)
    adBody.Visible = isAloggerExpanded
    adToggleBadge.Text = isAloggerExpanded
        and (isEn and "Hide" or "ย่อเก็บ")
        or (isEn and "Expand String" or "เปิดดูทั้งหมด")
    tabRawBtn.Text = isEn and "Full String (Underlined)" or "ดู String ทั้งหมด"
    tabNumbersBtn.Text = isEn and ("All Numbers (" .. info.totalCount .. ")") or ("ลำดับเลขทั้งหมด (" .. info.totalCount .. ")")
    jumpInTabBtn.Text = isEn and "Scroll to Real ID" or "เลื่อนไปจุดเลขจริง"
    copyAllNumsBtn.Text = isEn and "Copy Bait Only" or "คัดลอกเฉพาะเลขหลอก"
    tabRawStroke.Transparency = (aloggerViewMode == "raw") and 0.15 or 0.65
    tabNumbersStroke.Transparency = (aloggerViewMode == "numbers") and 0.15 or 0.65
    activeRealTargetFrame = nil
    activeRealTargetStroke = nil
    if not isAloggerExpanded then return end
    for _, ch in ipairs(adScroll:GetChildren()) do
        if not ch:IsA("UIListLayout") and not ch:IsA("UIPadding") then
            ch:Destroy()
        end
    end
    if aloggerViewMode == "numbers" then
        if #info.entries == 0 then
            local emptyLbl = Instance.new("TextLabel")
            emptyLbl.Size = UDim2.new(1, 0, 0, 24)
            emptyLbl.BackgroundTransparency = 1
            emptyLbl.Font = FontNormal
            emptyLbl.TextSize = 11
            emptyLbl.TextColor3 = Theme.TextSecondary
            emptyLbl.TextXAlignment = Enum.TextXAlignment.Left
            emptyLbl.Text = isEn and "No number sequences found." or "ไม่พบชุดตัวเลขในรายการนี้"
            emptyLbl.Parent = adScroll
            HONKUKIUI:Bind(emptyLbl, "TextColor3", "TextSecondary")
            return
        end
        local fakeCounter = 0
        for idx, ent in ipairs(info.entries) do
            if ent.isReal then
                local realRow = Instance.new("Frame")
                realRow.Size = UDim2.new(1, 0, 0, 0)
                realRow.AutomaticSize = Enum.AutomaticSize.Y
                realRow.BackgroundColor3 = Theme.ButtonBg
                realRow.BackgroundTransparency = 0.18
                realRow.BorderSizePixel = 0
                realRow.LayoutOrder = idx
                realRow.Parent = adScroll
                HONKUKIUI:Bind(realRow, "BackgroundColor3", "ButtonBg")
                Instance.new("UICorner", realRow).CornerRadius = UDim.new(0, 6)
                local rSt = Instance.new("UIStroke")
                rSt.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                rSt.Color = Theme.AccentCyan
                rSt.Transparency = 0.2
                rSt.Thickness = 1.2
                rSt.Parent = realRow
                HONKUKIUI:BindAccent(rSt, "Color")
                activeRealTargetFrame = realRow
                activeRealTargetStroke = rSt
                local rPad = Instance.new("UIPadding")
                rPad.PaddingTop = UDim.new(0, 6)
                rPad.PaddingBottom = UDim.new(0, 6)
                rPad.PaddingLeft = UDim.new(0, 8)
                rPad.PaddingRight = UDim.new(0, 8)
                rPad.Parent = realRow
                local rLayout = Instance.new("UIListLayout")
                rLayout.SortOrder = Enum.SortOrder.LayoutOrder
                rLayout.Padding = UDim.new(0, 3)
                rLayout.Parent = realRow
                local rTop = Instance.new("Frame")
                rTop.Size = UDim2.new(1, 0, 0, 20)
                rTop.BackgroundTransparency = 1
                rTop.LayoutOrder = 1
                rTop.Parent = realRow
                local rLbl = Instance.new("TextLabel")
                rLbl.Size = UDim2.new(1, -76, 1, 0)
                rLbl.BackgroundTransparency = 1
                rLbl.Font = FontBold
                rLbl.RichText = true
                rLbl.TextSize = 12
                rLbl.TextColor3 = Theme.TextPrimary
                rLbl.TextXAlignment = Enum.TextXAlignment.Left
                rLbl.Text = isEn
                    and string.format("Order #%d [REAL ID]   |   <u><font color=\"#38BDF8\">%s</font></u>", ent.order, escapeRichText(realIdStr ~= "" and realIdStr or ent.num))
                    or string.format("ลำดับที่ #%d [เลขเพลงจริง]   |   <u><font color=\"#38BDF8\">%s</font></u>", ent.order, escapeRichText(realIdStr ~= "" and realIdStr or ent.num))
                rLbl.Parent = rTop
                HONKUKIUI:Bind(rLbl, "TextColor3", "TextPrimary")
                local rCopyLbl = Instance.new("TextLabel")
                rCopyLbl.Size = UDim2.fromOffset(70, 20)
                rCopyLbl.AnchorPoint = Vector2.new(1, 0.5)
                rCopyLbl.Position = UDim2.new(1, 0, 0.5, 0)
                rCopyLbl.BackgroundTransparency = 1
                rCopyLbl.Font = FontBold
                rCopyLbl.TextSize = 10.5
                rCopyLbl.TextColor3 = Theme.AccentCyan
                rCopyLbl.TextXAlignment = Enum.TextXAlignment.Right
                rCopyLbl.Text = isEn and "Copy Real" or "คัดลอกเลขจริง"
                rCopyLbl.Parent = rTop
                HONKUKIUI:BindAccent(rCopyLbl, "TextColor3")
                local rReason = Instance.new("TextLabel")
                rReason.Size = UDim2.new(1, 0, 0, 0)
                rReason.AutomaticSize = Enum.AutomaticSize.Y
                rReason.BackgroundTransparency = 1
                rReason.Font = FontNormal
                rReason.TextSize = 10.5
                rReason.TextColor3 = Theme.TextSecondary
                rReason.TextXAlignment = Enum.TextXAlignment.Left
                rReason.TextWrapped = true
                rReason.LayoutOrder = 2
                rReason.Text = isEn and info.reasonEn or info.reasonTh
                rReason.Parent = realRow
                HONKUKIUI:Bind(rReason, "TextColor3", "TextSecondary")
                local clickBtn = Instance.new("TextButton")
                clickBtn.Size = UDim2.new(1, 0, 1, 0)
                clickBtn.BackgroundTransparency = 1
                clickBtn.Text = ""
                clickBtn.Parent = realRow
                clickBtn.MouseButton1Click:Connect(function()
                    PlaySound(Sounds.Click, 0.75)
                    copyToClipboardSafe(realIdStr ~= "" and realIdStr or ent.num)
                    rCopyLbl.Text = isEn and "Copied" or "คัดลอกแล้ว"
                    task.delay(1.0, function()
                        if rCopyLbl and rCopyLbl.Parent then
                            rCopyLbl.Text = (AppState.LangMode == "en") and "Copy Real" or "คัดลอกเลขจริง"
                        end
                    end)
                end)
            else
                fakeCounter = fakeCounter + 1
                local rowWrap = Instance.new("Frame")
                rowWrap.Size = UDim2.new(1, 0, 0, 24)
                rowWrap.BackgroundColor3 = Theme.ButtonBg
                rowWrap.BackgroundTransparency = 0.48
                rowWrap.BorderSizePixel = 0
                rowWrap.LayoutOrder = idx
                rowWrap.Parent = adScroll
                HONKUKIUI:Bind(rowWrap, "BackgroundColor3", "ButtonBg")
                Instance.new("UICorner", rowWrap).CornerRadius = UDim.new(0, 5)
                local leftLbl = Instance.new("TextLabel")
                leftLbl.Size = UDim2.new(1, -76, 1, 0)
                leftLbl.Position = UDim2.new(0, 8, 0, 0)
                leftLbl.BackgroundTransparency = 1
                leftLbl.Font = FontNormal
                leftLbl.TextSize = 11
                leftLbl.TextColor3 = Theme.TextSecondary
                leftLbl.TextXAlignment = Enum.TextXAlignment.Left
                leftLbl.TextTruncate = Enum.TextTruncate.AtEnd
                leftLbl.Text = isEn
                    and string.format("Order #%d (Bait #%d)   |   %s", ent.order, fakeCounter, ent.num)
                    or string.format("ลำดับที่ #%d (เลขหลอกชุดที่ %d)   |   %s", ent.order, fakeCounter, ent.num)
                leftLbl.Parent = rowWrap
                HONKUKIUI:Bind(leftLbl, "TextColor3", "TextSecondary")
                local rightLbl = Instance.new("TextLabel")
                rightLbl.Size = UDim2.fromOffset(64, 24)
                rightLbl.AnchorPoint = Vector2.new(1, 0.5)
                rightLbl.Position = UDim2.new(1, -6, 0.5, 0)
                rightLbl.BackgroundTransparency = 1
                rightLbl.Font = FontNormal
                rightLbl.TextSize = 10
                rightLbl.TextColor3 = Theme.TextSecondary
                rightLbl.TextXAlignment = Enum.TextXAlignment.Right
                rightLbl.Text = isEn and "Copy" or "แตะคัดลอก"
                rightLbl.Parent = rowWrap
                HONKUKIUI:Bind(rightLbl, "TextColor3", "TextSecondary")
                local clickBtn = Instance.new("TextButton")
                clickBtn.Size = UDim2.new(1, 0, 1, 0)
                clickBtn.BackgroundTransparency = 1
                clickBtn.Text = ""
                clickBtn.Parent = rowWrap
                clickBtn.MouseButton1Click:Connect(function()
                    PlaySound(Sounds.Click, 0.7)
                    copyToClipboardSafe(ent.num)
                    rightLbl.Text = isEn and "Copied" or "คัดลอกแล้ว"
                    task.delay(1.0, function()
                        if rightLbl and rightLbl.Parent then
                            rightLbl.Text = (AppState.LangMode == "en") and "Copy" or "แตะคัดลอก"
                        end
                    end)
                end)
            end
        end
    else
        local cleanRaw = rawStr:gsub("[%c]", " ")
        local chunkSize = 380
        local totalLen = #cleanRaw
        if totalLen == 0 then
            local emptyLbl = Instance.new("TextLabel")
            emptyLbl.Size = UDim2.new(1, 0, 0, 24)
            emptyLbl.BackgroundTransparency = 1
            emptyLbl.Font = FontNormal
            emptyLbl.TextSize = 11
            emptyLbl.TextColor3 = Theme.TextSecondary
            emptyLbl.TextXAlignment = Enum.TextXAlignment.Left
            emptyLbl.Text = isEn and "(Empty)" or "(ไม่มีข้อมูล)"
            emptyLbl.Parent = adScroll
            return
        end
        local chunkIdx = 0
        for cStart = 1, totalLen, chunkSize do
            chunkIdx = chunkIdx + 1
            local cEnd = math.min(totalLen, cStart + chunkSize - 1)
            local hasRealOverlap = info.realStart and info.realEnd and (cStart <= info.realEnd) and (cEnd >= info.realStart)
            local chunkBox = Instance.new("Frame")
            chunkBox.Size = UDim2.new(1, 0, 0, 0)
            chunkBox.AutomaticSize = Enum.AutomaticSize.Y
            chunkBox.BackgroundColor3 = Theme.ButtonBg
            chunkBox.BackgroundTransparency = hasRealOverlap and 0.18 or 0.48
            chunkBox.BorderSizePixel = 0
            chunkBox.LayoutOrder = chunkIdx
            chunkBox.Parent = adScroll
            HONKUKIUI:Bind(chunkBox, "BackgroundColor3", "ButtonBg")
            Instance.new("UICorner", chunkBox).CornerRadius = UDim.new(0, 6)
            if hasRealOverlap then
                local st = Instance.new("UIStroke")
                st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                st.Color = Theme.AccentCyan
                st.Transparency = 0.2
                st.Thickness = 1.2
                st.Parent = chunkBox
                HONKUKIUI:BindAccent(st, "Color")
                if not activeRealTargetFrame then
                    activeRealTargetFrame = chunkBox
                    activeRealTargetStroke = st
                end
            end
            local pd = Instance.new("UIPadding")
            pd.PaddingTop = UDim.new(0, 6)
            pd.PaddingBottom = UDim.new(0, 6)
            pd.PaddingLeft = UDim.new(0, 8)
            pd.PaddingRight = UDim.new(0, 8)
            pd.Parent = chunkBox
            local chunkLayout = Instance.new("UIListLayout")
            chunkLayout.SortOrder = Enum.SortOrder.LayoutOrder
            chunkLayout.Padding = UDim.new(0, 5)
            chunkLayout.Parent = chunkBox
            local cfLbl = Instance.new("TextLabel")
            cfLbl.Size = UDim2.new(1, 0, 0, 0)
            cfLbl.AutomaticSize = Enum.AutomaticSize.Y
            cfLbl.BackgroundTransparency = 1
            cfLbl.Font = FontNormal
            cfLbl.RichText = true
            cfLbl.TextSize = 11
            cfLbl.TextColor3 = Theme.TextPrimary
            cfLbl.TextXAlignment = Enum.TextXAlignment.Left
            cfLbl.TextWrapped = true
            cfLbl.LayoutOrder = 1
            local sliceText = cleanRaw:sub(cStart, cEnd)
            if hasRealOverlap and info.realStart and info.realEnd then
                local relStart = math.max(1, info.realStart - cStart + 1)
                local relEnd = math.min(#sliceText, info.realEnd - cStart + 1)
                local beforePart = escapeRichText(sliceText:sub(1, relStart - 1))
                local realPart = escapeRichText(sliceText:sub(relStart, relEnd))
                local afterPart = escapeRichText(sliceText:sub(relEnd + 1))
                local headerTag = isEn
                    and string.format("<b><font color=\"#38BDF8\">[Block #%d — REAL ID UNDERLINED BELOW]</font></b>\n", chunkIdx)
                    or string.format("<b><font color=\"#38BDF8\">[ท่อนที่ %d — ขีดเส้นใต้ตำแหน่งเลขเพลงจริง]</font></b>\n", chunkIdx)
                cfLbl.Text = headerTag .. beforePart .. "<u><b><font color=\"#38BDF8\">" .. realPart .. "</font></b></u>" .. afterPart
            else
                local headerTag = isEn
                    and string.format("[Block #%d — Bait / Garbage Segment]:\n", chunkIdx)
                    or string.format("[ท่อนที่ %d — โค้ดขยะ/เลขหลอก]:\n", chunkIdx)
                cfLbl.Text = escapeRichText(headerTag .. sliceText)
            end
            cfLbl.Parent = chunkBox
            HONKUKIUI:Bind(cfLbl, "TextColor3", "TextPrimary")
            if hasRealOverlap then
                local explainSubBox = Instance.new("Frame")
                explainSubBox.Size = UDim2.new(1, 0, 0, 0)
                explainSubBox.AutomaticSize = Enum.AutomaticSize.Y
                explainSubBox.BackgroundColor3 = Theme.CardBg
                explainSubBox.BackgroundTransparency = 0.2
                explainSubBox.BorderSizePixel = 0
                explainSubBox.LayoutOrder = 2
                explainSubBox.Parent = chunkBox
                HONKUKIUI:Bind(explainSubBox, "BackgroundColor3", "CardBg")
                Instance.new("UICorner", explainSubBox).CornerRadius = UDim.new(0, 6)
                local exSt = Instance.new("UIStroke")
                exSt.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                exSt.Color = Theme.AccentCyan
                exSt.Transparency = 0.45
                exSt.Thickness = 1
                exSt.Parent = explainSubBox
                HONKUKIUI:BindAccent(exSt, "Color")
                local exPad = Instance.new("UIPadding")
                exPad.PaddingTop = UDim.new(0, 5)
                exPad.PaddingBottom = UDim.new(0, 5)
                exPad.PaddingLeft = UDim.new(0, 8)
                exPad.PaddingRight = UDim.new(0, 8)
                exPad.Parent = explainSubBox
                local exLayout = Instance.new("UIListLayout")
                exLayout.SortOrder = Enum.SortOrder.LayoutOrder
                exLayout.Padding = UDim.new(0, 3)
                exLayout.Parent = explainSubBox
                local exIdLine = Instance.new("TextLabel")
                exIdLine.Size = UDim2.new(1, 0, 0, 18)
                exIdLine.BackgroundTransparency = 1
                exIdLine.Font = FontBold
                exIdLine.RichText = true
                exIdLine.TextSize = 12
                exIdLine.TextColor3 = Theme.TextPrimary
                exIdLine.TextXAlignment = Enum.TextXAlignment.Left
                exIdLine.LayoutOrder = 1
                exIdLine.Text = isEn
                    and string.format("Real Audio ID:  <u><b><font color=\"#38BDF8\">%s</font></b></u>  (Position #%d of %d)", escapeRichText(displayReal), info.realOrderIdx or 1, info.totalCount)
                    or string.format("เลขเพลงจริง:  <u><b><font color=\"#38BDF8\">%s</font></b></u>  (ลำดับที่ #%d จาก %d ชุด)", escapeRichText(displayReal), info.realOrderIdx or 1, info.totalCount)
                exIdLine.Parent = explainSubBox
                HONKUKIUI:Bind(exIdLine, "TextColor3", "TextPrimary")
                local exUnderline = Instance.new("Frame")
                exUnderline.Size = UDim2.new(0, 145, 0, 2)
                exUnderline.BackgroundColor3 = Theme.AccentCyan
                exUnderline.BorderSizePixel = 0
                exUnderline.LayoutOrder = 2
                exUnderline.Parent = explainSubBox
                HONKUKIUI:BindAccent(exUnderline, "BackgroundColor3")
                local exReasonLbl = Instance.new("TextLabel")
                exReasonLbl.Size = UDim2.new(1, 0, 0, 0)
                exReasonLbl.AutomaticSize = Enum.AutomaticSize.Y
                exReasonLbl.BackgroundTransparency = 1
                exReasonLbl.Font = FontNormal
                exReasonLbl.TextSize = 10.5
                exReasonLbl.TextColor3 = Theme.TextSecondary
                exReasonLbl.TextXAlignment = Enum.TextXAlignment.Left
                exReasonLbl.TextWrapped = true
                exReasonLbl.LayoutOrder = 3
                exReasonLbl.Text = isEn and info.reasonEn or info.reasonTh
                exReasonLbl.Parent = explainSubBox
                HONKUKIUI:Bind(exReasonLbl, "TextColor3", "TextSecondary")
            end
        end
    end
end
local function toggleAloggerExpand()
    PlaySound(Sounds.Click, 0.8)
    isAloggerExpanded = not isAloggerExpanded
    renderAloggerDrawer()
end
adHeaderBtn.MouseButton1Click:Connect(toggleAloggerExpand)
adToggleBadge.MouseButton1Click:Connect(toggleAloggerExpand)
_G.HONKUKISyncAloggerSelection = function(targetItem, forceExpand)
    if forceExpand and targetItem then
        currentCardTarget = targetItem
        isAloggerExpanded = true
    end
    renderAloggerDrawer()
end
end
updateStealerDetailCard = function()
    local targetItem = nil
    if selectedStealPlayerName and selectedStealPlayerName ~= "None" then
        for _, it in ipairs(cachedActivePlayers) do
            if it.entryKey == selectedStealPlayerName or it.name == selectedStealPlayerName then
                targetItem = it
                break
            end
        end
    end
    if not targetItem and #cachedActivePlayers > 0 then
        targetItem = cachedActivePlayers[1]
        selectedStealPlayerName = targetItem.entryKey or targetItem.name
    end
    currentCardTarget = targetItem
    if _G.HONKUKISyncAloggerSelection then
        pcall(function() _G.HONKUKISyncAloggerSelection(targetItem) end)
    end
    if not targetItem then
        scLine1.Text = AppState.LangMode == "en" and "Target: No players playing music" or "เป้าหมาย: ไม่พบผู้เล่นที่กำลังเปิดเพลงในขณะนี้"
        scLine2.Text = AppState.LangMode == "en" and "Track: (Click Scan to detect active music)" or "ชื่อเพลง: (กดปุ่มตรวจสอบเพื่อค้นหารายการเพลง)"
        scLine3.Text = "ID: —"
        scActionsRow.Visible = false
        return
    end
    scActionsRow.Visible = true
    local distStuds = math.floor(targetItem.distance + 0.5)
    local srcLabel = getMusicSourceLabel(targetItem.source, AppState.LangMode == "en")
    scLine1.Text = string.format("%s (@%s) • %d studs • %s", targetItem.displayName, targetItem.name, distStuds, srcLabel)
    scLine2.Text = AppState.LangMode == "en" and "Loading track title..." or "กำลังดึงข้อมูลชื่อเพลง..."
    getSongNameAsync(targetItem.realId, function(sName)
        if _G.HONKUKIIsVehicleSfxTitle and _G.HONKUKIIsVehicleSfxTitle(sName) then
            if _G.HONKUKIIgnoredVehicleSfxIds and targetItem.realId then
                _G.HONKUKIIgnoredVehicleSfxIds[tostring(targetItem.realId)] = true
            end
            for idx = #cachedActivePlayers, 1, -1 do
                if cachedActivePlayers[idx] == targetItem or tostring(cachedActivePlayers[idx].realId) == tostring(targetItem.realId) then
                    table.remove(cachedActivePlayers, idx)
                end
            end
            if selectedStealPlayerName == targetItem.entryKey or selectedStealPlayerName == targetItem.name then
                selectedStealPlayerName = (#cachedActivePlayers > 0) and (cachedActivePlayers[1].entryKey or cachedActivePlayers[1].name) or nil
            end
            stealPlayerDropdown.Refresh(getStealDropdownItems(), selectedStealPlayerName)
            updateStealerDetailCard()
            return
        end
        targetItem.songTitle = sName
        if currentCardTarget == targetItem and scLine2 and scLine2.Parent then
            scLine2.Text = sName
        end
    end)
    local badge = targetItem.wasProtected and (AppState.LangMode == "en" and "Decoded from Protected Audio" or "ถอดรหัสจากระบบป้องกันสำเร็จ")
        or (AppState.LangMode == "en" and "Standard Audio ID" or "รหัสเพลงมาตรฐาน")
    local idPrefix = AppState.LangMode == "en" and "Audio ID: %s  •  %s" or "รหัสเพลง: %s  •  %s"
    scLine3.Text = string.format(idPrefix, tostring(targetItem.realId), badge)
end
table.insert(HONKUKIUI.LangCallbacks, function()
    pcall(function()
        stealPlayerDropdown.Refresh(getStealDropdownItems(), selectedStealPlayerName, true)
        updateStealerDetailCard()
    end)
end)
local function refreshStealerUI(notifyUser)
    cachedActivePlayers = scanActiveMusicPlayers()
    local dropdownItems = getStealDropdownItems()
    stealPlayerDropdown.Refresh(dropdownItems, selectedStealPlayerName)
    updateStealerDetailCard()
    if notifyUser then
        local count = #cachedActivePlayers
        local uniquePlayers = {}
        local playerCount = 0
        for _, it in ipairs(cachedActivePlayers) do
            if it.name and not uniquePlayers[it.name] then
                uniquePlayers[it.name] = true
                playerCount = playerCount + 1
            end
        end
        if count > 0 then
            HONKUKIUI:Notify({
                Title = AppState.LangMode == "en" and "Music Scan" or "การตรวจสอบระบบเสียง",
                Content = (AppState.LangMode == "en"
                    and string.format("Found %d track(s) from %d player(s)", count, playerCount)
                    or string.format("ตรวจพบเพลง %d รายการ จากผู้เล่น %d คน", count, playerCount)),
                Icon = Icons.Check,
                Duration = 2.0
            })
        else
            HONKUKIUI:Notify({
                Title = AppState.LangMode == "en" and "Music Scan" or "การตรวจสอบระบบเสียง",
                Content = AppState.LangMode == "en" and "No active music found in Boombox / Vehicle" or "ไม่พบผู้เล่นที่กำลังเปิดเพลงในแผนที่ขณะนี้",
                Icon = Icons.Close,
                Duration = 2.0
            })
        end
    end
end
musicBox:AddButton("btn_scan_music", function()
    refreshStealerUI(true)
end)
musicBox:AddButton("btn_steal_music", function()
    cachedActivePlayers = scanActiveMusicPlayers()
    stealPlayerDropdown.Refresh(getStealDropdownItems(), selectedStealPlayerName)
    if #cachedActivePlayers > 0 then
        local nearest = cachedActivePlayers[1]
        selectedStealPlayerName = nearest.entryKey or nearest.name
        updateStealerDetailCard()
        currentMusicId = nearest.realId
        idInput.Set(nearest.realId)
        getSongNameAsync(nearest.realId, function(sName)
            if HONKUKIUI.NowPlayingCard then
                HONKUKIUI.NowPlayingCard:Show(nearest.realId, sName, nearest.displayName .. "'s Music")
            end
        end)
        HONKUKIUI:Notify({
            Title = AppState.LangMode == "en" and "Music Copied" or "ดึงข้อมูลเพลงสำเร็จ",
            Content = (AppState.LangMode == "en" and "Copied from " or "ดึงรหัสเพลงจาก ") .. nearest.displayName .. string.format(" (%d studs)", math.floor(nearest.distance + 0.5)),
            Icon = Icons.Check,
            Duration = 2.2
        })
    else
        updateStealerDetailCard()
        HONKUKIUI:Notify({
            Title = AppState.LangMode == "en" and "Copy Music" or "คัดลอกเพลง",
            Content = AppState.LangMode == "en" and "No nearby music found (PlayersChoice)" or "ไม่พบผู้เล่นที่กำลังเปิดเพลงในบริเวณใกล้เคียง",
            Icon = Icons.Close,
            Duration = 2.0
        })
    end
end)
