    if type(AppState.CapturedAllIds) ~= "table" then AppState.CapturedAllIds = {} end
    do
        local cleanLogs = {}
        for _, entry in ipairs(AppState.CapturedMusicLogs) do
            local eid = tostring(entry and entry.id or "")
            local etitle = tostring(entry and entry.title or "")
            local isBad = (_G.HONKUKIIgnoredVehicleSfxIds and _G.HONKUKIIgnoredVehicleSfxIds[eid])
                or (_G.HONKUKIIsVehicleSfxTitle and _G.HONKUKIIsVehicleSfxTitle(etitle))
            if isBad and eid ~= "" and _G.HONKUKIIgnoredVehicleSfxIds then
                _G.HONKUKIIgnoredVehicleSfxIds[eid] = true
            end
            if not isBad then
                table.insert(cleanLogs, entry)
            end
        end
        AppState.CapturedMusicLogs = cleanLogs
        local cleanIds = {}
        for _, savedId in ipairs(AppState.CapturedAllIds) do
            local sid = tostring(savedId or "")
            if not (_G.HONKUKIIgnoredVehicleSfxIds and _G.HONKUKIIgnoredVehicleSfxIds[sid]) then
                table.insert(cleanIds, savedId)
            end
        end
        AppState.CapturedAllIds = cleanIds
    end
