            vaultIdsPreview.Text = uniqueIds > 0 and ("รหัสเพลงที่ดักจับได้ทั้งหมด: " .. table.concat(AppState.CapturedAllIds, ", ")) or "รหัสเพลงที่ดักจับได้ทั้งหมด: ยังไม่มีข้อมูล"
