    rebuildCapturedLogsUI = function()
        for _, ch in ipairs(logsFeedContainer:GetChildren()) do
            if not ch:IsA("UIListLayout") then ch:Destroy() end
        end
        updateVaultSummaryUI()
        local logs = AppState.CapturedMusicLogs or {}
        local isEn = (AppState.LangMode == "en")
        if #logs == 0 then
            local emptyCard = Instance.new("Frame")
            emptyCard.Size = UDim2.new(1, 0, 0, 44)
            emptyCard.BackgroundColor3 = Theme.ButtonBg
            emptyCard.BackgroundTransparency = Theme.ButtonTrans
