            HONKUKIUI:Bind(ecStroke, "Color", "ButtonBorder")
            HONKUKIUI:Bind(ecStroke, "Transparency", "ButtonBorderTrans")
            local emptyLbl = Instance.new("TextLabel")
            emptyLbl.Size = UDim2.new(1, -20, 1, 0)
            emptyLbl.Position = UDim2.new(0, 10, 0, 0)
            emptyLbl.BackgroundTransparency = 1
            emptyLbl.Font = FontNormal
            emptyLbl.TextSize = 11.5
            emptyLbl.TextColor3 = Theme.TextSecondary
            emptyLbl.Text = isEn and "No captured music logs yet. Enable Auto Interceptor or click Scan Now." or "ยังไม่มีประวัติเพลงที่ดักจับได้ เปิดสวิตช์ดักจับอัตโนมัติหรือกดปุ่มสแกนทันที"
            emptyLbl.Parent = emptyCard
            HONKUKIUI:Bind(emptyLbl, "TextColor3", "TextSecondary")
            return
        end
        local maxRender = math.min(#logs, 25)
        for i = 1, maxRender do
            local entry = logs[i]
            local itemCard = Instance.new("Frame")
            itemCard.Name = "CapturedLog_" .. i
            itemCard.Size = UDim2.new(1, 0, 0, 0)
            itemCard.AutomaticSize = Enum.AutomaticSize.Y
            itemCard.BackgroundColor3 = Theme.ButtonBg
            itemCard.BackgroundTransparency = Theme.ButtonTrans
