            HONKUKIUI:Bind(itemCard, "BackgroundColor3", "ButtonBg")
            HONKUKIUI:Bind(itemCard, "BackgroundTransparency", "ButtonTrans")
            Instance.new("UICorner", itemCard).CornerRadius = UDim.new(0, 12)
            local icStroke = Instance.new("UIStroke")
            icStroke.Color = Theme.ButtonBorder
            icStroke.Transparency = Theme.ButtonBorderTrans
            icStroke.Thickness = 1
            icStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            icStroke.Parent = itemCard
            HONKUKIUI:Bind(icStroke, "Color", "ButtonBorder")
            HONKUKIUI:Bind(icStroke, "Transparency", "ButtonBorderTrans")
            CreateRotatingStrokeGradient(icStroke, true)
            local icLayout = Instance.new("UIListLayout")
            icLayout.SortOrder = Enum.SortOrder.LayoutOrder
            icLayout.Padding = UDim.new(0, 4)
            icLayout.Parent = itemCard
            local icPad = Instance.new("UIPadding")
            icPad.PaddingTop = UDim.new(0, 8)
            icPad.PaddingBottom = UDim.new(0, 8)
            icPad.PaddingLeft = UDim.new(0, 12)
            icPad.PaddingRight = UDim.new(0, 12)
            icPad.Parent = itemCard
            local srcName = getMusicSourceLabel(entry.source, isEn)
            local row1 = Instance.new("TextLabel")
            row1.Size = UDim2.new(1, 0, 0, 17)
            row1.BackgroundTransparency = 1
            row1.Font = FontBold
            row1.TextSize = 12.5
            row1.TextColor3 = Theme.TextPrimary
            row1.TextXAlignment = Enum.TextXAlignment.Left
            row1.TextTruncate = Enum.TextTruncate.AtEnd
            row1.Text = string.format("%s (@%s)  •  %s  •  %s", tostring(entry.displayName or entry.player), tostring(entry.player), tostring(entry.timeStr or "--:--:--"), srcName)
            row1.LayoutOrder = 1
            row1.Parent = itemCard
            HONKUKIUI:Bind(row1, "TextColor3", "TextPrimary")
            local row2 = Instance.new("TextLabel")
            row2.Size = UDim2.new(1, 0, 0, 16)
            row2.BackgroundTransparency = 1
            row2.Font = FontNormal
            row2.TextSize = 12
            row2.TextColor3 = Theme.AccentCyan
            row2.TextXAlignment = Enum.TextXAlignment.Left
            row2.TextTruncate = Enum.TextTruncate.AtEnd
            row2.Text = string.format("%s  •  ID: %s", tostring(entry.title or ("Audio " .. tostring(entry.id))), tostring(entry.id))
            row2.LayoutOrder = 2
