    end
    recordCapturedTrack = function(item)
        if not item or not item.name then return end
        if selectedInterceptTarget ~= "All" and item.name ~= selectedInterceptTarget then
            return
        end
        local trackKey = tostring(item.realId or "")
        if trackKey ~= "" and _G.HONKUKIIgnoredVehicleSfxIds and _G.HONKUKIIgnoredVehicleSfxIds[trackKey] then
            return
        end
        if item.songTitle and _G.HONKUKIIsVehicleSfxTitle and _G.HONKUKIIsVehicleSfxTitle(item.songTitle) then
            if trackKey ~= "" and _G.HONKUKIIgnoredVehicleSfxIds then _G.HONKUKIIgnoredVehicleSfxIds[trackKey] = true end
            return
        end
        local sourceKey = item.name .. "|" .. tostring(item.source or "Audio")
        if lastCapturedByPlayer[sourceKey] == trackKey then
            return
        end
        lastCapturedByPlayer[sourceKey] = trackKey
        local nowTimeStr = "00:00:00"
        pcall(function() nowTimeStr = os.date("%H:%M:%S") end)
        local newEntry = {
            id = tostring(item.realId),
            rawSoundId = tostring(item.rawSoundId or ""),
            title = "กำลังดึงข้อมูลชื่อเพลง...",
            player = item.name,
            displayName = item.displayName or item.name,
            timeStr = nowTimeStr,
            wasProtected = item.wasProtected == true,
            bypassSuccess = item.bypassSuccess ~= false,
            source = item.source or "Boombox",
        }
        table.insert(AppState.CapturedMusicLogs, 1, newEntry)
        while #AppState.CapturedMusicLogs > 60 do
            table.remove(AppState.CapturedMusicLogs)
        end
        if newEntry.bypassSuccess and newEntry.id ~= "" and newEntry.id ~= "UNDECODABLE" then
            local exists = false
            for _, savedId in ipairs(AppState.CapturedAllIds) do
                if tostring(savedId) == newEntry.id then exists = true; break end
            end
            if not exists then
                table.insert(AppState.CapturedAllIds, 1, newEntry.id)
            end
            getSongNameAsync(newEntry.id, function(resolvedName)
                if _G.HONKUKIIsVehicleSfxTitle and _G.HONKUKIIsVehicleSfxTitle(resolvedName) then
                    if _G.HONKUKIIgnoredVehicleSfxIds then _G.HONKUKIIgnoredVehicleSfxIds[tostring(newEntry.id)] = true end
                    for idx = #AppState.CapturedMusicLogs, 1, -1 do
                        if tostring(AppState.CapturedMusicLogs[idx].id) == tostring(newEntry.id) then
                            table.remove(AppState.CapturedMusicLogs, idx)
                        end
                    end
                    for idx = #AppState.CapturedAllIds, 1, -1 do
                        if tostring(AppState.CapturedAllIds[idx]) == tostring(newEntry.id) then
                            table.remove(AppState.CapturedAllIds, idx)
                        end
                    end
                    SaveConfig()
                    if isInterceptorExpanded then rebuildCapturedLogsUI() else updateVaultSummaryUI() end
                    return
                end
                newEntry.title = resolvedName
                SaveConfig()
                if isInterceptorExpanded then
                    rebuildCapturedLogsUI()
                end
            end)
        else
            newEntry.title = "ไม่สามารถถอดรหัสชื่อเพลงได้"
        end
        SaveConfig()
        if isInterceptorExpanded then
            rebuildCapturedLogsUI()
        else
            updateVaultSummaryUI()
        end
    end
    runAutoInterceptPass = function(manualNotify)
        local activeList = scanActiveMusicPlayers(true)
        local beforeCount = #(AppState.CapturedMusicLogs or {})
        for _, it in ipairs(activeList) do
            recordCapturedTrack(it)
        end
        if _G.HONKUKISyncAloggerSelection then
            pcall(function() _G.HONKUKISyncAloggerSelection(currentCardTarget) end)
        end
        local added = #(AppState.CapturedMusicLogs or {}) - beforeCount
        if manualNotify then
            local isEn = (AppState.LangMode == "en")
            HONKUKIUI:Notify({
                Title = isEn and "Auto Interceptor" or "ระบบดักจับเพลงอัตโนมัติ",
                Content = isEn and string.format("Scanned %d active track(s) (%d new)", #activeList, math.max(0, added))
                    or string.format("ตรวจพบเพลงที่กำลังเปิด %d รายการ (บันทึกใหม่ %d รายการ)", #activeList, math.max(0, added)),
                Icon = Icons.Check,
                Duration = 1.8
            })
        end
    end
    createLiquidActionPill(vaultActionsRow, "btn_vault_copy_all", "คัดลอกไอดีทั้งหมด", Icons.Clipboard, Color3.fromRGB(56, 189, 248), function()
        local isEn = (AppState.LangMode == "en")
        local allIds = AppState.CapturedAllIds or {}
        if #allIds == 0 then
            HONKUKIUI:Notify({
                Title = isEn and "Captured Vault" or "คลังรหัสเพลง",
                Content = isEn and "No captured IDs in vault yet" or "ยังไม่มีรหัสเพลงที่ดักจับได้ในคลัง",
                Icon = Icons.Close,
                Duration = 1.8
            })
            return
        end
        local linesOut = {}
        for _, logItem in ipairs(AppState.CapturedMusicLogs or {}) do
            if logItem.bypassSuccess then
                table.insert(linesOut, string.format("[%s] %s (@%s) -> ID: %s | %s",
                    tostring(logItem.timeStr or ""),
                    tostring(logItem.displayName or logItem.player),
                    tostring(logItem.player),
                    tostring(logItem.id),
                    tostring(logItem.title or "")
                ))
            end
        end
        local nl = string.char(10)
        local finalClip = "Captured Audio IDs (" .. #allIds .. "): " .. table.concat(allIds, ", ") .. nl .. table.concat(linesOut, nl)
        copyToClipboardSafe(finalClip)
        HONKUKIUI:Notify({
            Title = isEn and "Copied Vault" or "คัดลอกคลังไอดีสำเร็จ",
            Content = isEn and ("Copied all " .. #allIds .. " captured Audio IDs") or ("คัดลอกรหัสเพลงทั้งหมด " .. #allIds .. " ไอดีเรียบร้อยแล้ว"),
            Icon = Icons.ClipboardCheck,
            Duration = 2.0
        })
    end)
    createLiquidActionPill(vaultActionsRow, "btn_vault_scan_now", "สแกนทันที", Icons.Refresh, Color3.fromRGB(16, 185, 129), function()
        lastCapturedByPlayer = {}
        runAutoInterceptPass(true)
        rebuildCapturedLogsUI()
    end)
    createLiquidActionPill(vaultActionsRow, "btn_vault_clear_all", "ล้างประวัติ", Icons.Trash, Theme.DangerRed, function()
        AppState.CapturedMusicLogs = {}
        AppState.CapturedAllIds = {}
        lastCapturedByPlayer = {}
        SaveConfig()
        rebuildCapturedLogsUI()
        local isEn = (AppState.LangMode == "en")
        HONKUKIUI:Notify({
            Title = isEn and "Cleared" or "ล้างประวัติสำเร็จ",
            Content = isEn and "Cleared all captured music logs" or "ล้างประวัติและคลังไอดีที่ดักจับไว้ทั้งหมดแล้ว",
            Icon = Icons.Trash,
            Duration = 1.6
        })
    end)
    table.insert(HONKUKIUI.LangCallbacks, function()
        pcall(function()
            interceptTargetDrop.Refresh(getInterceptTargetDropdownItems(), selectedInterceptTarget, true)
            updateExpandVisuals()
            if isInterceptorExpanded then
                rebuildCapturedLogsUI()
            end
        end)
    end)
    if _G.HONKUKIAutoInterceptConn then pcall(function() _G.HONKUKIAutoInterceptConn:Disconnect() end) end
    if _G.HONKUKIAutoInterceptDescConn then pcall(function() _G.HONKUKIAutoInterceptDescConn:Disconnect() end) end
    local interceptAccum = 0
    local interceptBurstQueued = false
    _G.HONKUKIAutoInterceptDescConn = workspace.DescendantAdded:Connect(function(desc)
        if not desc or not desc:IsA("Sound") then return end
        invalidateContainerSoundCache(desc)
        if not isAutoInterceptActive or interceptBurstQueued then return end
        local myChar = LocalPlayer and LocalPlayer.Character
        if myChar and desc:IsDescendantOf(myChar) then return end
        local sid = desc.SoundId or ""
        if sid:lower():sub(1, 11) == "rbxasset://" then return end
        interceptBurstQueued = true
        task.delay(0.35, function()
            interceptBurstQueued = false
            if isAutoInterceptActive then
                pcall(function() runAutoInterceptPass(false) end)
            end
        end)
    end)
    _G.HONKUKIAutoInterceptConn = RunService.Heartbeat:Connect(function(dt)
        if not isAutoInterceptActive then return end
        interceptAccum = interceptAccum + dt
        if interceptAccum < 1.15 then return end
        interceptAccum = 0
        pcall(function() runAutoInterceptPass(false) end)
    end)
    rebuildCapturedLogsUI()
    updateExpandVisuals()
end
local favBox = Window_script1:CreateGroupBox("sec_favorites")
