    curNewPlaylist = val
end)
favBox:AddButton("btn_create_playlist", function()
    local name = curNewPlaylist:match("^%s*(.-)%s*$")
    if not name or name == "" then
        HONKUKIUI:Notify({ Title = AppState.LangMode == "en" and "Playlists" or "เพลย์ลิสต์", Content = AppState.LangMode == "en" and "Please enter a playlist name" or "กรุณาระบุชื่อเพลย์ลิสต์ที่ต้องการสร้าง", Icon = Icons.Close })
