        Motion.Press(saveBtn, 0.94, 1.0)
        local sbCorner = Instance.new("UICorner")
        sbCorner.CornerRadius = UDim.new(0, 10)
        sbCorner.Parent = saveBtn
        saveBtn.Activated:Connect(function()
            PlaySound(Sounds.Click, 0.8)
            local rawNewId = idBox.Text
            local newId = assetId(rawNewId)
            if newId == "" then
                HONKUKIUI:Notify({ Title = AppState.LangMode == "en" and "Error" or "ข้อผิดพลาด", Content = AppState.LangMode == "en" and "Invalid Audio ID" or "กรุณากรอกรหัสเพลงที่ถูกต้อง", Icon = Icons.Close })
                return
            end
            local newTitle = titleBox.Text:match("^%s*(.-)%s*$")
            if not newTitle or newTitle == "" then
                newTitle = "Audio " .. newId
            end
            local oldId = tostring(song.id)
            song.title = newTitle
            song.id = newId
            if AppState.FavoriteTracks then
                local found = false
                for idx, tid in ipairs(AppState.FavoriteTracks) do
                    if tostring(tid) == oldId then
                        AppState.FavoriteTracks[idx] = newId
                        found = true
                        break
                    end
                end
                if not found then
                    table.insert(AppState.FavoriteTracks, newId)
                end
            end
            SaveConfig()
            rebuildFavoritesUI()
            if HONKUKIUI.NowPlayingCard and HONKUKIUI.NowPlayingCard.UpdateStarUI then
                HONKUKIUI.NowPlayingCard:UpdateStarUI()
            end
            overlay:Destroy()
            HONKUKIUI:Notify({
                Title = AppState.LangMode == "en" and "Favorites" or "คลังเพลงโปรด",
                Content = (AppState.LangMode == "en" and "Updated: " or "แก้ไขสำเร็จ: ") .. newTitle,
                Icon = Icons.Check,
                Duration = 2.0
            })
        end)
    end
