                    table.remove(AppState.FavoriteItems, idx)
                end
            end
            for idx = #AppState.FavoriteTracks, 1, -1 do
                if tostring(AppState.FavoriteTracks[idx]) == cleanId then
                    table.remove(AppState.FavoriteTracks, idx)
                end
