            Content = AppState.LangMode == "th" and "เปิดใช้งานระบบป้องกันแรงปะทะจากผู้เล่นอื่นและวัตถุเรียบร้อยแล้ว" or "Enabled full protection against players, spawned props & vehicles",
            Icon = Icons.Check,
            Duration = 2.0
        })
    else
        HONKUKIUI:Notify({
            Title = AppState.LangMode == "th" and "ระบบป้องกันแรงกระแทก (Anti-Fling)" or "Anti-Fling Shield",
            Content = AppState.LangMode == "th" and "ปิดใช้งานระบบป้องกันแรงปะทะและคืนค่าการชนตามปกติเรียบร้อยแล้ว" or "Anti-Fling disabled and collisions restored",
            Icon = Icons.Close,
            Duration = 2.0
        })
    end
end)
