local PropSizeCache = {}
local function getPropBoundingInfo(prop)
    if not prop or not prop.Parent then return Vector3.new(2, 2, 2), 2, Vector3.zero end
    local cached = PropSizeCache[prop]
    if cached then
        return cached.size, cached.maxDim, cached.centerOffset
    end
    local sz = Vector3.new(2, 2, 2)
    local maxDim = 2
    local centerOffset = Vector3.zero
    if prop:IsA("Model") then
        local pcallOk, cf, bSz = pcall(function() return prop:GetBoundingBox() end)
        if pcallOk and bSz and bSz.Magnitude > 0.1 then
            sz = bSz
            maxDim = math.max(sz.X, sz.Y, sz.Z)
            local pcallPiv, pivotCF = pcall(function() return prop:GetPivot() end)
            if pcallPiv and pivotCF then
                centerOffset = pivotCF:PointToObjectSpace(cf.Position)
            end
        end
    elseif prop:IsA("BasePart") then
        sz = prop.Size
        maxDim = math.max(sz.X, sz.Y, sz.Z)
    end
    if maxDim < 0.5 then maxDim = 0.5 end
    PropSizeCache[prop] = { size = sz, maxDim = maxDim, centerOffset = centerOffset, time = tick() }
    return sz, maxDim, centerOffset
end
local function getOwnedProps()
    local list, seen = {}, {}
    local tc = workspace:FindFirstChild("WorkspaceCom") and workspace.WorkspaceCom:FindFirstChild("001_TrafficCones")
    if tc then
        for _, p in ipairs(tc:GetChildren()) do
            if p.Name:find(LocalPlayer.Name) and p:FindFirstChild("SetCurrentCFrame") then
                table.insert(list, p)
                seen[p] = true
            end
        end
    end
    for _, p in ipairs(CollectionService:GetTagged("PropRoot")) do
        if p.Name:find(LocalPlayer.Name) and p:FindFirstChild("SetCurrentCFrame") and not seen[p] then
            table.insert(list, p)
            seen[p] = true
        end
    end
    return list
end
local function getOrbitTargetCFrame()
    if OrbitConfig.TargetMode == "Mouse" then
        local mouse = LocalPlayer:GetMouse()
        if mouse and mouse.Hit then return mouse.Hit end
    elseif OrbitConfig.TargetMode == "Nearest" then
        local myChar = LocalPlayer.Character
        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if myHrp then
            local nearestRoot, nearestDist = nil, math.huge
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                    local d = (p.Character.HumanoidRootPart.Position - myHrp.Position).Magnitude
                    if d < nearestDist then nearestDist = d; nearestRoot = p.Character.HumanoidRootPart end
                end
            end
            if nearestRoot then return nearestRoot.CFrame end
        end
    elseif OrbitConfig.TargetMode == "Player" then
        local targetPlr = nil
        if OrbitConfig.TargetPlayer and OrbitConfig.TargetPlayer ~= "" then
            targetPlr = Players:FindFirstChild(OrbitConfig.TargetPlayer)
            if not targetPlr then
                local low = string.lower(OrbitConfig.TargetPlayer)
                for _, p in ipairs(Players:GetPlayers()) do
                    if string.lower(p.Name) == low or string.lower(p.DisplayName) == low or tostring(p.UserId) == low then
                        targetPlr = p
                        break
                    end
                end
            end
        end
        if targetPlr and targetPlr.Character then
            local char = targetPlr.Character
            local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Head")
            if root then return root.CFrame end
        end
        local myChar = LocalPlayer.Character
        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
        return myHrp and myHrp.CFrame or nil
    end
    local char = LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    return hrp and hrp.CFrame or nil
end
local function generateEngineColor(hueProgress, mode)
    local sat = OrbitConfig.RGBSaturation
    local val = OrbitConfig.RGBBrightness
    if mode == "Cyberpunk Neon" then
        local p = (hueProgress * 3) % 3
        if p < 1 then return Color3.fromHSV(0.85, 0.9 * sat, val)
        elseif p < 2 then return Color3.fromHSV(0.52, 0.95 * sat, val)
        else return Color3.fromHSV(0.75, 0.85 * sat, val) end
    elseif mode == "Pastel Dream" then
        return Color3.fromHSV(hueProgress, 0.45 * sat, 1.0 * val)
    elseif mode == "Fire & Magma" then
        local p = (math.sin(hueProgress * math.pi * 2) + 1) * 0.5
        return Color3.fromHSV(0.02 + 0.10 * p, 0.95 * sat, val)
    elseif mode == "Toxic Acid" then
        local p = (math.sin(hueProgress * math.pi * 2) + 1) * 0.5
        return Color3.fromHSV(0.22 + 0.12 * p, 1.0 * sat, val)
    elseif mode == "Ocean Crystal" then
        local p = (math.sin(hueProgress * math.pi * 2) + 1) * 0.5
        return Color3.fromHSV(0.50 + 0.15 * p, 0.85 * sat, val)
    elseif mode == "Galaxy Night" then
        local p = (math.sin(hueProgress * math.pi * 2) + 1) * 0.5
        return Color3.fromHSV(0.70 + 0.15 * p, 0.9 * sat, 0.85 * val)
    elseif mode == "Party Disco" then
        return Color3.fromRGB(math.random(30, 255), math.random(30, 255), math.random(30, 255))
    else
        return Color3.fromHSV(hueProgress, 1.0 * sat, 1.0 * val)
    end
end
local Orbit3D = {}
local PI = math.pi
local TAU = math.pi * 2
local PHI = (1 + math.sqrt(5)) / 2
function Orbit3D.Look(pos, target, rollDeg)
    local diff = target - pos
    if diff.Magnitude < 0.001 then
        diff = Vector3.new(0, 0, -1)
    end
    local fwd = diff.Unit
    local ny = math.clamp((math.abs(fwd.Y) - 0.72) / 0.28, 0, 1)
    local smoothNy = ny * ny * (3 - 2 * ny)
    local up = Vector3.new(0.15 * smoothNy, 1 - 0.85 * smoothNy, 0.98 * smoothNy).Unit
    local cf = CFrame.lookAt(pos, pos + fwd, up)
    if rollDeg and rollDeg ~= 0 then
        local bankRad
        if math.abs(rollDeg) > 95 then
            bankRad = math.sin(math.rad(rollDeg) * 0.22) * math.rad(38)
        else
            bankRad = math.rad(rollDeg)
        end
        cf = cf * CFrame.Angles(0, 0, bankRad)
    end
    return cf
end
function Orbit3D.SampleEdges(u, verts, edges)
    local n = #verts
    local a = (u % 1) * TAU
    local pos = Vector3.zero
    local tan = Vector3.zero
    for k = 1, n do
        local phase = (k - 1) * (TAU / n)
        local w = 0.5 + 0.5 * math.cos(a - phase)
        local w3 = w * w * w
        local dw = -1.5 * w * w * math.sin(a - phase)
        pos = pos + verts[k] * (w3 * (2.2 / n))
        tan = tan + verts[k] * (dw * (2.2 / n))
    end
    if tan.Magnitude < 0.001 then
        tan = Vector3.new(-math.sin(a), 0, math.cos(a))
    end
    return pos, tan.Unit
end
function Orbit3D.TraceCurve(t, i, total, speed, trailSpan, fn, rollSpeed)
    local u = (i - 1) / math.max(1, total)
    local s = t * speed - u * trailSpan
    local p1 = fn(s)
    local p2 = fn(s + 0.04)
    local roll = rollSpeed and (math.sin(s * 1.4 + i * 0.4) * 35) or 0
    return Orbit3D.Look(p1, p2, roll)
end
function Orbit3D.MultiStream(t, i, total, streams, speed, trailSpan, fn, rollSpeed)
    local streamIdx = ((i - 1) % streams) + 1
    local perStream = math.max(1, math.ceil(total / streams))
    local rank = math.floor((i - 1) / streams) + 1
    local u = (rank - 1) / math.max(1, perStream)
    local s = t * speed - u * trailSpan
    local p1 = fn(s, streamIdx, u, rank, perStream)
    local p2 = fn(s + 0.04, streamIdx, u, rank, perStream)
    local roll = rollSpeed and (math.sin(s * 1.4 + i * 0.5) * 35) or 0
    return Orbit3D.Look(p1, p2, roll)
end
function Orbit3D.SymmetryPair(i, total)
    if i == total and (total % 2 == 1) then
        return 0, math.ceil(i / 2), math.floor(total / 2)
    end
    local side = (i % 2 == 0) and 1 or -1
    local rank = math.ceil(i / 2)
    local maxRank = math.max(1, math.floor(total / 2))
    return side, rank, maxRank
end
function Orbit3D.MorphCombo(t, i, total, r, s1, s2, s3, s4, s5, s6, s7)
    local stageTime = (t * 0.24) % 7
    local stage = math.floor(stageTime) + 1
    local blend = stageTime - (stage - 1)
    local fn1, fn2
    if stage == 1 then
        fn1, fn2 = s1, s2
    elseif stage == 2 then
        fn1, fn2 = s2, s3
    elseif stage == 3 then
        fn1, fn2 = s3, s4
    elseif stage == 4 then
        fn1, fn2 = s4, s5
    elseif stage == 5 then
        fn1, fn2 = s5, s6
    elseif stage == 6 then
        fn1, fn2 = s6, s7
    else
        fn1, fn2 = s7, s1
    end
    local cf1 = fn1(t, i, total, r)
    if blend <= 0.42 then
        return cf1
    end
    local cf2 = fn2(t, i, total, r)
    local a = math.clamp((blend - 0.42) / 0.58, 0, 1)
    local alpha = a * a * a * (a * (a * 6 - 15) + 10)
    local p = cf1.Position:Lerp(cf2.Position, alpha)
    local bridge = 4 * alpha * (1 - alpha)
    local radial = Vector3.new(p.X, 0, p.Z)
    if radial.Magnitude > 0.05 then
        radial = radial.Unit
    else
        radial = Vector3.new(0, 0, -1)
    end
    local fwd = (cf1.LookVector * (1 - alpha) + cf2.LookVector * alpha + radial * (bridge * 0.45)).Unit
    local upMix = cf1.UpVector * (1 - alpha) + cf2.UpVector * alpha + Vector3.new(0, bridge * 0.55, 0)
    local right = fwd:Cross(upMix)
    if right.Magnitude < 0.01 then
        right = fwd:Cross(Vector3.zAxis)
    end
    right = right.Unit
    local up = right:Cross(fwd).Unit
    return CFrame.fromMatrix(p, right, up, -fwd)
end
function Orbit3D.B001(t, i, total, r)
    local side, rank, maxR = Orbit3D.SymmetryPair(i, total)
    local S = r * 2.2
    if side == 0 then
        local bob = math.sin(t * 4) * (r * 0.25)
        local pos = Vector3.new(0, 5.5 + bob, 1.0)
        return CFrame.new(pos) * CFrame.Angles(0, t * 6, math.rad(45))
    end
    local u = rank / maxR
    local beat = math.sin(t * 3.2 - u * 1.8)
    local flare = 1.15 + 0.20 * math.sin(t * 1.6)
    local spanX = side * (1.5 + (u ^ 0.85) * S * 1.45 * flare)
    local archY = 1.5 + math.sin(u * PI * 0.85) * (S * 0.85) + beat * (u * S * 0.45) - (u ^ 2) * (S * 0.35)
    local sweepZ = 2.0 + math.cos(beat * 0.8) * (u * S * 0.55) + u * 2.5
    local pos = Vector3.new(spanX, archY, sweepZ)
    local tipTarget = pos + Vector3.new(side * 4, beat * 2 - u * 2, 2)
    return Orbit3D.Look(pos, tipTarget, side * 35)
end
function Orbit3D.B002(t, i, total, r)
    local side, rank, maxR = Orbit3D.SymmetryPair(i, total)
    local S = r * 2.4
    if side == 0 then
        return CFrame.new(0, 2.2, 2.2) * CFrame.Angles(t * 8, t * 5, 0)
    end
    local u = rank / maxR
    local flap = math.sin(t * 3.8 - u * 1.5)
    local fold = 0.75 + 0.45 * math.sin(t * 1.9)
    local x = side * (1.2 + u * S * 1.5 * fold)
    local y = 2.5 + math.sin(u * PI) * (S * 0.9) + flap * u * (S * 0.65)
    local z = 2.2 - math.sin(flap) * u * (S * 0.75)
    local pos = Vector3.new(x, y, z)
    return Orbit3D.Look(pos, Vector3.new(0, 2.0, -S), side * (45 + flap * 30))
end
function Orbit3D.B003(t, i, total, r)
    local S = r * 2.3
