        local x = math.cos(s) * rad + math.sin(s * 0.5) * (S * 0.4)
        local y = math.sin(s * 1.5) * (S * 0.95) + 2.0
        local z = math.sin(s) * rad
        return Vector3.new(x, y, z)
    end, 300)
end
function Orbit3D.B022(t, i, total, r)
    local S = r * 2.2
    return Orbit3D.TraceCurve(t, i, total, 5.0, 2.4, function(s)
        local waveY = math.sin(s * 0.8) * (S * 1.35) + 1.8
        local coilR = S * (0.65 + 0.45 * math.cos(s * 0.8))
        return Vector3.new(math.cos(s * 2.2) * coilR, waveY, math.sin(s * 2.2) * coilR)
    end, 160)
end
function Orbit3D.B023(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.TraceCurve(t, i, total, 2.4, TAU, function(s)
        local x = (math.cos(s) * 0.68 + math.cos(5 * s) * 0.38) * S
        local z = (math.sin(s) * 0.68 - math.sin(5 * s) * 0.38) * S
        local y = 1.6 + math.sin(6 * s + t * 2.0) * (S * 0.42)
        return CFrame.Angles(0, t * 0.6, 0) * Vector3.new(x, y, z)
    end, 60)
end
function Orbit3D.B024(t, i, total, r)
    local S = r * 2.0
    if i <= 9 then
        local a = (TAU / 9) * i + t * 2.0
        local y = ((i % 3) - 1) * (S * 0.45) + 1.2
        local pos = Vector3.new(math.cos(a) * S * 0.75, y, math.sin(a) * S * 0.75)
        return Orbit3D.Look(pos, Vector3.new(0, y, 0), 0)
    else
        local bIdx = i - 9
        local u = bIdx / math.max(1, total - 9)
        local swing = math.sin(t * 4.5) * math.rad(110)
        local reach = (S * 0.8) + u * (S * 1.8)
        local x = math.sin(swing) * reach
        local y = 1.8 + math.cos(swing) * (reach * 0.35)
        local z = -math.cos(swing) * reach
        local pos = Vector3.new(x, y, z)
        return Orbit3D.Look(pos, Vector3.zero, 90)
    end
end
function Orbit3D.B025(t, i, total, r)
    local S = r * 2.3
    local blade = (i - 1) % 4
    local rank = math.floor((i - 1) / 4) + 1
    local maxR = math.max(1, math.ceil(total / 4))
    local u = rank / maxR
    local spin = t * 9.0 + blade * (PI / 2) - u * 1.1
    local rad = (S * 0.25) + u * (S * 1.25) * (0.85 + 0.25 * math.sin(t * 4))
    local y = 1.2 + math.sin(u * PI) * 0.8
    local pos = Vector3.new(math.cos(spin) * rad, y, math.sin(spin) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, 1.2, 0), 90)
end
function Orbit3D.B026(t, i, total, r)
    local S = r * 2.2
    local u = 0.5 + 0.45 * math.sin(t * 1.6 + (i - 1) * (TAU / total))
    local rad = S * (0.35 + 1.15 * (1 - u))
    local a = u * TAU * 2.0 + t * 3.2 + i * (TAU / total)
    local eyeCenter = Vector3.new(0, 2.4, -1.5)
    local offset = Vector3.new(math.cos(a) * rad, math.sin(a) * rad, (0.5 - u) * (S * 0.9))
    local pos = eyeCenter + offset
    return Orbit3D.Look(pos, eyeCenter, 45)
end
function Orbit3D.B027(t, i, total, r)
    local S = r * 2.4
    return Orbit3D.TraceCurve(t, i, total, 7.0, 2.0, function(s)
        local helixR = S * (0.55 + 0.35 * math.sin(s * 3.0))
        local x = math.cos(s * 2.5) * helixR
        local y = 2.0 + math.sin(s * 2.5) * helixR
        local z = math.sin(s * 0.8) * (S * 1.5)
        return Vector3.new(x, y, z)
    end, 400)
end
function Orbit3D.B028(t, i, total, r)
    local S = r * 2.3
    local u = (i - 0.5) / math.max(1, total)
    local arc = (u - 0.5) * PI * 1.35
    local cycle = 0.5 - 0.5 * math.cos(t * 2.0)
    local forwardDist = -1.2 - cycle * (S * 2.2)
    local scale = 0.85 + cycle * 0.55
    local y = 2.4 + math.sin(arc) * (S * 1.25 * scale)
    local z = forwardDist + (1 - math.cos(arc)) * (S * 0.65 * scale)
    local x = math.sin(arc * 2 + t * 1.5) * (S * 0.35)
    local pos = Vector3.new(x, y, z)
    return Orbit3D.Look(pos, pos + Vector3.new(0, 0, -5), 25)
end
function Orbit3D.B029(t, i, total, r)
    local S = r * 2.2
    local a = (TAU / total) * i + t * 2.2
    local wave = 0.5 + 0.5 * math.sin(t * 2.4 + i * (TAU / total) * 2)
    local slashU = wave * wave * wave
    local p1 = Vector3.new(math.cos(a) * S * 1.25, 3.6 + math.sin(t * 3 + i) * 0.5, math.sin(a) * S * 1.25)
    local p2 = Vector3.new(-math.cos(a) * S * 0.95, 0.4, -math.sin(a) * S * 0.95)
    local pos = p1:Lerp(p2, slashU * 0.85)
    return Orbit3D.Look(pos, p2, 35)
end
function Orbit3D.B030(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.MultiStream(t, i, total, 2, 8.0, 1.9, function(s, stream)
        local sign = (stream == 1) and 1 or -1
        local x = math.cos(s) * S * 1.2
        local y = 1.8 + sign * math.cos(s) * (S * 0.95)
        local z = math.sin(s) * S * 1.2
        return Vector3.new(x, y, z)
    end, 360)
end
function Orbit3D.B031(t, i, total, r)
    local S = r * 2.2
    local wave = 0.5 + 0.5 * math.sin(t * 1.8)
    local slamProg = wave * wave * wave
    local height = 6.2 - slamProg * 6.5
    local rad = S * (1.1 + slamProg * 0.55)
    local a = (TAU / total) * i + t * 3.2
    local pos = Vector3.new(math.cos(a) * rad, height + math.sin(a * 3 + t * 2) * 0.5, math.sin(a) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, height - 3, 0), 30)
end
function Orbit3D.B032(t, i, total, r)
    local S = r * 2.1
    local y = 1 - ((i - 0.5) / math.max(1, total)) * 2
    local radAtY = math.sqrt(math.max(0, 1 - y * y))
    local pulse = 0.85 + 0.40 * math.sin(t * 2.4)
    local curR = S * pulse
    local theta = i * (TAU / (PHI ^ 2)) + t * 4.0 - math.cos(t * 2.4) * 1.2
    local pos = Vector3.new(math.cos(theta) * radAtY * curR, 1.5 + y * curR, math.sin(theta) * radAtY * curR)
    return Orbit3D.Look(pos, Vector3.new(0, 1.5, 0), 45)
end
function Orbit3D.B033(t, i, total, r)
    local S = r * 2.1
    return Orbit3D.MultiStream(t, i, total, 3, 3.2, 2.1, function(s, stream, u)
        local a = s * 1.8 + stream * (TAU / 3)
        local w = 0.5 + 0.5 * math.sin(s * 0.75 + u * PI)
        local h = w * (S * 2.2) - (S * 0.8)
        local env = math.sin(w * PI)
        local rad = S * (0.45 + 0.75 * env)
        return Vector3.new(math.cos(a) * rad, h + 1.5, math.sin(a) * rad)
    end, 45)
end
function Orbit3D.B034(t, i, total, r)
    local S = r * 2.2
    local wave = 0.5 + 0.5 * math.sin(t * 2.0 + (i % 3) * 0.6)
    local h = -1.2 + wave * (S * 1.9)
    local a = (TAU / total) * i + t * 2.8
    local rad = S * (0.85 + 0.45 * wave)
    local pos = Vector3.new(math.cos(a) * rad, h, math.sin(a) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, h + 2, 0), 35)
end
function Orbit3D.B035(t, i, total, r)
    local S = r * 2.2
    local isPillar = (i % 3 == 0)
    local a = (TAU / total) * i + t * 2.2
    if not isPillar then
        local rad = S * (0.95 + 0.25 * math.sin(a * 5 - t * 4))
        local pos = Vector3.new(math.cos(a) * rad, -1.8 + math.sin(t * 2 + i) * 0.3, math.sin(a) * rad)
        return Orbit3D.Look(pos, Vector3.new(0, -1.8, 0), 0)
    else
        local u = 0.5 + 0.5 * math.sin(t * 2.0 + i * 0.7)
        local y = -1.8 + u * (S * 2.2)
        local rad = S * 0.85
        local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
        return Orbit3D.Look(pos, Vector3.new(math.cos(a) * rad, y + 5, math.sin(a) * rad), 30)
    end
end
function Orbit3D.B036(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.MultiStream(t, i, total, 2, 2.2, TAU, function(s, stream)
        local dir = (stream == 1) and 1 or -1
        local offset = (stream == 1) and 0 or (PI / 3)
        local a = s * dir + offset
        local x = (math.cos(a) * 0.75 + math.cos(-2 * a) * 0.32) * S
        local z = (math.sin(a) * 0.75 + math.sin(-2 * a) * 0.32) * S
        local y = 1.5 + (stream - 1.5) * 0.7 + math.sin(3 * a + t * 2.0) * 0.35
        return CFrame.Angles(0, t * 0.8 * dir, 0) * Vector3.new(x, y, z)
    end, 30)
end
function Orbit3D.B037(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.TraceCurve(t, i, total, 2.0, TAU, function(s)
        local x = (math.cos(2 * s) * 0.65 + math.cos(-3 * s) * 0.42) * S
        local z = (math.sin(2 * s) * 0.65 + math.sin(-3 * s) * 0.42) * S
        local y = 1.5 + math.sin(5 * s + t * 2.0) * (S * 0.35)
        return CFrame.Angles(math.sin(t * 0.7) * 0.25, t * 0.7, 0) * Vector3.new(x, y, z)
    end, 45)
end
function Orbit3D.B038(t, i, total, r)
    local S = r * 2.1
    return Orbit3D.MultiStream(t, i, total, 2, 2.2, TAU, function(s, stream)
        local dir = (stream == 1) and 1 or -1
        local offset = (stream == 1) and 0 or (PI / 4)
        local a = s * dir + offset + t * 0.8 * dir
        local x = (math.cos(a) * 0.78 + math.cos(-3 * a) * 0.26) * S
        local y = 1.8 + (math.sin(a) * 0.78 + math.sin(-3 * a) * 0.26) * S
        local z = -2.0 + (stream - 1.5) * 0.5 + math.sin(4 * a) * 0.3
        return Vector3.new(x, y, z)
    end, 45)
end
function Orbit3D.B039(t, i, total, r)
    local S = r * 2.1
    local ring = ((i - 1) % 3) + 1
    local perRing = math.max(1, math.ceil(total / 3))
    local idx = math.floor((i - 1) / 3) + 1
    local a = (TAU / perRing) * idx + t * 3.5 * ((ring == 2) and -1 or 1)
    local rad = S * (0.75 + ring * 0.22)
    local p = Vector3.new(math.cos(a) * rad, 0, math.sin(a) * rad)
    local cf = CFrame.Angles(t * 0.9 * ring, ring * (TAU / 3), math.rad(55))
    local wp = cf * p
    return Orbit3D.Look(wp, Vector3.zero, a * 57.3)
end
function Orbit3D.B040(t, i, total, r)
    local S = r * 2.2
    local verts = {
        Vector3.new(1, 1, 1), Vector3.new(1, -1, -1), Vector3.new(-1, 1, -1), Vector3.new(-1, -1, 1)
    }
    local edges = { {1,2},{2,3},{3,1},{1,4},{2,4},{3,4} }
    return Orbit3D.MultiStream(t, i, total, 2, 1.2, 1.0, function(s, stream)
        local dir = (stream == 1) and 1 or -1
        local p = Orbit3D.SampleEdges(s * 0.2, verts, edges) * dir
        local rot = CFrame.Angles(0, t * 2.0 * dir, math.sin(t * 2) * 0.3)
        return rot * (p * (S * 0.75))
    end, 120)
end
function Orbit3D.B041(t, i, total, r)
    local S = r * 2.1
    local verts = {
        Vector3.new(-1,-1,-1), Vector3.new(1,-1,-1), Vector3.new(1,1,-1), Vector3.new(-1,1,-1),
        Vector3.new(-1,-1,1),  Vector3.new(1,-1,1),  Vector3.new(1,1,1),  Vector3.new(-1,1,1)
    }
    local edges = {
        {1,2},{2,3},{3,4},{4,1}, {5,6},{6,7},{7,8},{8,5}, {1,5},{2,6},{3,7},{4,8}
    }
    return Orbit3D.TraceCurve(t, i, total, 0.85, 1.0, function(s)
        local p = Orbit3D.SampleEdges(s * 0.15, verts, edges)
        local w = math.sin(t * 2.0 + s * TAU)
        local scale = S * (0.65 + 0.35 * w)
        local rot = CFrame.Angles(t * 1.1, t * 1.5, t * 0.7)
        return rot * (p * scale)
    end, 90)
end
function Orbit3D.B042(t, i, total, r)
    local S = r * 2.1
    local a = (TAU / total) * i + t * 1.5
    local bloom = (math.sin(t * 2.0) + 1) * 0.5
    local tier = (i % 2 == 0) and 1.0 or 0.68
    local rad = S * tier * (0.3 + 0.95 * bloom)
    local y = -1.2 + (1 - bloom * 0.65) * (S * 1.15 * tier) + math.sin(a * 5 + t * 4) * 0.3
    local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, y + 3.0, 0), 0)
end
function Orbit3D.B043(t, i, total, r)
    local S = r * 2.3
    local u = i / math.max(1, total)
    local rad = S * (0.25 + 1.15 * math.sqrt(u))
    local a = i * (TAU / (PHI ^ 2)) + t * 3.2 - u * 2.5
    local y = math.sin(u * TAU * 2 - t * 5.0) * (S * 0.45)
    local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, 0, 0), a * 57.3)
end
function Orbit3D.B044(t, i, total, r)
    local S = r * 1.9
    return Orbit3D.TraceCurve(t, i, total, 2.2, TAU, function(s)
        local rad = S * (1.0 + 0.45 * math.cos(3 * s))
        local x = rad * math.cos(2 * s)
        local z = rad * math.sin(2 * s)
        local y = S * 0.55 * math.sin(3 * s) + 1.2
        return Vector3.new(x, y, z)
    end, 180)
end
function Orbit3D.B045(t, i, total, r)
    local S = r * 1.9
    return Orbit3D.TraceCurve(t, i, total, 1.8, TAU, function(s)
        local rad = S * (1.0 + 0.48 * math.cos(5 * s))
        local x = rad * math.cos(2 * s)
        local z = rad * math.sin(2 * s)
        local y = S * 0.55 * math.sin(5 * s) + 1.2
        return Vector3.new(x, y, z)
    end, 220)
end
function Orbit3D.B046(t, i, total, r)
    local S = r * 1.9
    return Orbit3D.TraceCurve(t, i, total, 1.6, TAU, function(s)
        local rad = S * (1.0 + 0.45 * math.cos(7 * s))
        local x = rad * math.cos(3 * s)
        local z = rad * math.sin(3 * s)
        local y = S * 0.55 * math.sin(7 * s) + 1.5
        return Vector3.new(x, y, z)
    end, 260)
end
function Orbit3D.B047(t, i, total, r)
    local S = r * 2.2
    return Orbit3D.TraceCurve(t, i, total, 2.8, TAU, function(s)
        local x = math.sin(s) * (S * 1.35)
        local y = math.sin(2 * s) * (S * 0.85) + 1.5
        local z = math.sin(3 * s) * (S * 0.95)
        return CFrame.Angles(0, t * 0.6, 0) * Vector3.new(x, y, z)
    end, 180)
end
function Orbit3D.B048(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.TraceCurve(t, i, total, 2.0, TAU, function(s)
        local petal = math.cos(4 * s)
        local rad = S * (0.42 + 0.88 * (petal * petal))
        local y = petal * (S * 0.55) + 1.2
        return Vector3.new(math.cos(s) * rad, y, math.sin(s) * rad)
    end, 150)
end
function Orbit3D.B049(t, i, total, r)
    local S = r * 2.1
    return Orbit3D.TraceCurve(t, i, total, 3.0, TAU * 2, function(s)
        local halfS = s * 0.5
        local w = S * 0.42 * math.cos(s * 2)
        local x = (S + w * math.cos(halfS)) * math.cos(s)
        local z = (S + w * math.cos(halfS)) * math.sin(s)
        local y = w * math.sin(halfS) + 1.2
        return Vector3.new(x, y, z)
    end, 90)
end
function Orbit3D.B050(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.MultiStream(t, i, total, 2, 3.5, PI, function(s, stream, u)
        local archA = (u - 0.5) * PI * 1.15
        local twist = s * 4.0 + stream * PI
        local x = math.sin(archA) * (S * 1.45)
        local y = math.cos(archA) * (S * 1.25) - 0.5 + math.sin(twist) * 0.8
        local z = math.cos(twist) * (S * 0.35)
        return Vector3.new(x, y, z)
    end, 180)
end
function Orbit3D.B051(t, i, total, r)
    local S = r * 2.0
    local pillar = ((i - 1) % 3) + 1
    local perPillar = math.max(1, math.ceil(total / 3))
    local rank = math.floor((i - 1) / 3) + 1
    local u = (rank - 0.5) / perPillar - 0.5
    local a = pillar * (TAU / 3) + t * 2.0
    local tilt = math.sin(t * 2.5 + pillar) * math.rad(25)
    local centerP = Vector3.new(math.cos(a) * S, 1.5, math.sin(a) * S)
    local upVec = CFrame.Angles(tilt, -a, 0) * Vector3.new(0, u * S * 1.6, 0)
    local pos = centerP + upVec
    return Orbit3D.Look(pos, Vector3.new(0, pos.Y, 0), 0)
end
function Orbit3D.B052(t, i, total, r)
    local S = r * 2.2
    if i == total then
        local bob = math.sin(t * 5) * 0.6
        return CFrame.new(0, S * 1.2 + 2.0 + bob, 0) * CFrame.Angles(0, t * 8, math.rad(45))
    end
    local verts = {
        Vector3.new(-1,-0.7,-1), Vector3.new(1,-0.7,-1), Vector3.new(1,-0.7,1), Vector3.new(-1,-0.7,1),
        Vector3.new(0, 1.1, 0)
    }
    local edges = { {1,2},{2,3},{3,4},{4,1}, {1,5},{2,5},{3,5},{4,5} }
    local u = (i - 1) / math.max(1, total - 1) + t * 0.15
    local p, dir = Orbit3D.SampleEdges(u, verts, edges)
    local rot = CFrame.Angles(0, t * 1.4, 0)
    local wp = rot * (p * S) + Vector3.new(0, 1.2, 0)
    return Orbit3D.Look(wp, wp + (rot * dir), 0)
end
function Orbit3D.B053(t, i, total, r)
    local S = r * 2.1
    local verts = {
        Vector3.new(1.2,0,0), Vector3.new(-1.2,0,0), Vector3.new(0,0,1.2), Vector3.new(0,0,-1.2),
        Vector3.new(0,1.5,0), Vector3.new(0,-1.5,0)
    }
    local edges = {
        {1,3},{3,2},{2,4},{4,1}, {1,5},{2,5},{3,5},{4,5}, {1,6},{2,6},{3,6},{4,6}
    }
    local u = (i - 1) / math.max(1, total) + t * 0.18
    local p, dir = Orbit3D.SampleEdges(u, verts, edges)
    local expand = 1 + 0.35 * math.sin(t * 2.5)
    local rot = CFrame.Angles(math.sin(t) * 0.4, t * 1.8, math.cos(t) * 0.4)
    local wp = rot * (p * (S * expand)) + Vector3.new(0, 1.5, 0)
    return Orbit3D.Look(wp, Vector3.new(0, 1.5, 0), t * 90)
end
function Orbit3D.B054(t, i, total, r)
    local S = r * 2.1
    return Orbit3D.TraceCurve(t, i, total, 2.2, TAU, function(s)
        local u = math.sin(s)
        local rad = S * (0.32 + 0.85 * (u * u))
        local a = s * 4.0 + t * 1.5
        local y = u * (S * 1.25) + 1.5
        return Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    end, 45)
end
function Orbit3D.B055(t, i, total, r)
    local S = r * 1.8
    local a = (TAU / total) * i + t * 2.0
    local isPeak = (i % 2 == 1)
    local rad = S * (isPeak and (0.95 + 0.15 * math.sin(t * 4)) or 0.75)
    local y = 4.2 + (isPeak and (S * 0.55 + math.sin(t * 5 + i) * 0.35) or 0)
    local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, 3.8, 0), 0)
end
function Orbit3D.B056(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.MultiStream(t, i, total, 2, 5.5, 2.5, function(s, stream)
        local rad = S * (0.85 + 0.2 * math.sin(s * 3))
        local a = s * 1.6
        if stream == 1 then
            return CFrame.Angles(math.rad(18), 0, math.rad(12)) * Vector3.new(math.cos(a) * rad * 1.2, 1.2, math.sin(a) * rad * 1.2)
        else
            return CFrame.Angles(math.rad(18), 0, math.rad(12)) * Vector3.new(math.cos(a) * rad * 0.9, 1.2 + math.sin(a) * rad * 0.9, 0)
        end
    end, 240)
end
function Orbit3D.B057(t, i, total, r)
    local S = r * 2.3
    local y = 1 - ((i - 0.5) / math.max(1, total)) * 2
    local radAtY = math.sqrt(math.max(0, 1 - y * y))
    local theta = i * (TAU / (PHI ^ 2)) + t * 2.8
    local curR = S * (0.95 + 0.55 * math.sin(t * 1.8) + 0.15 * math.cos(t * 3.6 + i * 0.4))
    local pos = Vector3.new(math.cos(theta) * radAtY * curR, 1.8 + y * curR, math.sin(theta) * radAtY * curR)
    return Orbit3D.Look(pos, Vector3.new(0, 1.8, 0), 45)
end
function Orbit3D.B058(t, i, total, r)
    local S = r * 2.4
    local prec = CFrame.Angles(math.rad(25), t * 2.2, 0)
    if i <= 7 then
        local a = (TAU / 7) * i + t * 8.0
        local p = prec * Vector3.new(math.cos(a) * S * 0.75, 0, math.sin(a) * S * 0.75) + Vector3.new(0, 1.5, 0)
        return Orbit3D.Look(p, Vector3.new(0, 1.5, 0), 90)
    else
        local jIdx = i - 7
        local pole = (jIdx % 2 == 0) and 1 or -1
        local u = 0.5 + 0.48 * math.sin(t * 2.6 + jIdx * 0.8)
        local h = pole * (1.2 + u * S * 1.9)
        local p = prec * Vector3.new(0, h, 0) + Vector3.new(0, 1.5, 0)
        return Orbit3D.Look(p, p + (prec * Vector3.new(0, pole * 5, 0)), t * 400)
    end
end
function Orbit3D.B059(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.MultiStream(t, i, total, 3, 6.5, 2.0, function(s, stream)
        local localP = Vector3.new(math.cos(s) * S * 1.25, 0, math.sin(s) * S * 0.48)
        local shellCF = CFrame.new(0, 1.5, 0) * CFrame.Angles(math.rad(58), stream * (TAU / 3) + t * 0.5, math.rad(35))
        return shellCF * localP
    end, 300)
end
function Orbit3D.B060(t, i, total, r)
    local S = r * 2.0
    local strand = (i % 2 == 0) and 1 or -1
    local rank = math.ceil(i / 2)
    local maxR = math.max(1, math.ceil(total / 2))
    local u = (rank - 0.5) / maxR - 0.5
    local y = u * (S * 2.2) + 1.5
    local twist = u * TAU * 2.2 + t * 4.5 + (strand == 1 and 0 or PI)
    local rad = S * (0.75 + 0.2 * math.sin(t * 3 + u * 4))
    local pos = Vector3.new(math.cos(twist) * rad, y, math.sin(twist) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, y, 0), 45 * strand)
end
function Orbit3D.B061(t, i, total, r)
    local S = r * 2.2
    if i <= 8 then
        local a = (TAU / 8) * i + t * 2.8
        local pos = Vector3.new(math.cos(a) * S * 0.95, S * 1.45 + 3.0, math.sin(a) * S * 0.95)
        return Orbit3D.Look(pos, Vector3.new(0, 0, 0), 0)
    else
        local lIdx = i - 8
        local u = 0.5 + 0.48 * math.sin(t * 2.8 - lIdx * 0.9)
        local y = -2.0 + u * (S * 1.45 + 5.0)
        local a = u * TAU * 3 + t * 10
        local pos = Vector3.new(math.cos(a) * 0.6, y, math.sin(a) * 0.6)
        return Orbit3D.Look(pos, Vector3.new(0, -10, 0), t * 500)
    end
end
function Orbit3D.B062(t, i, total, r)
    local S = r * 2.0
    if i == total then
        local slugU = 0.5 - 0.5 * math.cos(t * 2.8)
        local z = -1.5 - (slugU ^ 1.5) * (S * 4.5)
        return Orbit3D.Look(Vector3.new(0, 1.5, z), Vector3.new(0, 1.5, z - 10), t * 1000)
    end
    local ring = (i - 1) % 3
    local perRing = math.max(1, math.ceil((total - 1) / 3))
    local idx = math.floor((i - 1) / 3) + 1
    local a = (TAU / perRing) * idx + t * 6.0 * ((ring % 2 == 0) and 1 or -1)
    local rad = S * (0.65 - ring * 0.12)
    local z = -2.2 - ring * (S * 0.65)
    local pos = Vector3.new(math.cos(a) * rad, 1.5 + math.sin(a) * rad, z)
    return Orbit3D.Look(pos, Vector3.new(0, 1.5, z - 5), a * 57.3)
end
function Orbit3D.B063(t, i, total, r)
    local S = r * 2.1
    return Orbit3D.MultiStream(t, i, total, 3, 2.4, 1.8, function(s, stream, u)
        local wallAngle = stream * (TAU / 3) + t * 1.4
        local localA = s * 2.0
        local panelR = S * 0.42
        local centerW = Vector3.new(math.cos(wallAngle) * S, 1.6, math.sin(wallAngle) * S)
        local rightVec = Vector3.new(-math.sin(wallAngle), 0, math.cos(wallAngle))
        local offset = rightVec * (math.cos(localA) * panelR) + Vector3.new(0, math.sin(localA) * panelR, 0)
        return centerW + offset
    end, 30)
end
function Orbit3D.B064(t, i, total, r)
    local S = r * 2.2
    local side, rank, maxR = Orbit3D.SymmetryPair(i, total)
    local u = (side == 0) and 0 or (rank / maxR)
    local localP = Vector3.new(side * u * S * 1.2, 0, u * S * 1.3 - S * 0.6)
    local loopA = t * 2.0
    local flightCF = CFrame.new(math.cos(loopA) * S * 0.6, 2.5 + math.sin(loopA * 2) * (S * 0.5), math.sin(loopA) * S * 0.6)
        * CFrame.Angles(math.cos(loopA * 2) * 0.35, -loopA, math.sin(loopA) * 0.55)
    local wp = flightCF * localP
    local forwardP = flightCF * (localP + Vector3.new(0, 0, -4))
    return Orbit3D.Look(wp, forwardP, math.sin(loopA) * 35)
end
function Orbit3D.B065(t, i, total, r)
    local S = r * 2.0
    return Orbit3D.TraceCurve(t, i, total, 3.2, TAU, function(s)
        local R = S * 0.95
        local mr = S * 0.42
        local coil = s * 8.0
        local rad = R + mr * math.cos(coil)
        return Vector3.new(rad * math.cos(s), 1.2 + mr * math.sin(coil), rad * math.sin(s))
    end, 300)
end
function Orbit3D.B066(t, i, total, r)
    local S = r * 2.1
    local isScanner = (i % 2 == 0)
    local a = (TAU / total) * i + t * (isScanner and -3.5 or 2.5)
    local scanY = isScanner and (math.sin(t * 3.0) * (S * 0.95) + 1.2) or -2.2
    local rad = S * (isScanner and (0.85 + 0.25 * math.cos(t * 3.0)) or 1.15)
    local pos = Vector3.new(math.cos(a) * rad, scanY, math.sin(a) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, scanY, 0), 0)
end
function Orbit3D.B067(t, i, total, r)
    local S = r * 2.1
    local squad = (i - 1) % 3
    local a = (TAU / total) * i + t * (2.5 + squad * 1.5) * ((squad == 1) and -1 or 1)
    local rad = S * (0.65 + squad * 0.35)
    local y = (squad - 1) * (S * 0.55) + 1.5 + math.sin(t * 4 + i) * 0.35
    local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    return Orbit3D.Look(pos, pos + Vector3.new(-math.sin(a), 0, math.cos(a)), 25)
end
function Orbit3D.B068(t, i, total, r)
    local S = r * 2.1
    local axis = (i - 1) % 3
    local perAxis = math.max(1, math.ceil(total / 3))
    local idx = math.floor((i - 1) / 3) + 1
    local a = (TAU / perAxis) * idx + t * 3.5
    local p
    if axis == 0 then
        p = Vector3.new(math.cos(a) * S, 0, math.sin(a) * S)
    elseif axis == 1 then
        p = Vector3.new(math.cos(a) * S, math.sin(a) * S, 0)
    else
        p = Vector3.new(0, math.cos(a) * S, math.sin(a) * S)
    end
    local wp = (CFrame.Angles(t * 0.6, t * 0.8, 0) * p) + Vector3.new(0, 1.5, 0)
    return Orbit3D.Look(wp, Vector3.new(0, 1.5, 0), 0)
end
function Orbit3D.B069(t, i, total, r)
    local S = r * 2.1
    local u = 0.5 + 0.48 * math.sin(t * 1.6 + (i - 1) * (TAU / total))
    local z = (0.5 - u) * (S * 2.6)
    local pinch = 0.45 + 0.85 * ((u - 0.5) * 2) ^ 2
    local a = u * TAU * 3 + t * 5.0
    local rad = S * pinch
    local pos = Vector3.new(math.cos(a) * rad, 1.5 + math.sin(a) * rad, z)
    return Orbit3D.Look(pos, Vector3.new(0, 1.5, z - 5), a * 57.3)
end
function Orbit3D.B070(t, i, total, r)
    local S = r * 2.3
    local u = i / math.max(1, total)
    local rad = S * (0.45 + 0.95 * u)
    local align = 0.5 + 0.5 * math.cos(t * 1.4)
    local a = (TAU / total) * i * align + t * 2.0 + math.sin(t * 1.4 + u * PI) * 0.65
    local y = 1.4 + math.sin(u * TAU + t * 2.2) * (S * 0.35)
    local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, 1.4, 0), 25)
end
function Orbit3D.B071(t, i, total, r)
    local S = r * 2.0
    local u = 0.5 + 0.48 * math.sin(t * 1.4 + (i - 1) * (TAU / total))
    local side = (i % 2 == 0) and 1 or -1
    local a = u * TAU * 2.0 * side + t * 1.5
    local rad = S * (1.1 - u * 0.55)
    local y = -2.2 + u * (S * 2.6)
    local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, y + 1, 0), 0)
end
function Orbit3D.B072(t, i, total, r)
    local S = r * 2.2
    if i <= 9 then
        local xTick = t * 2.0; local tickAngle = (xTick - math.sin(xTick * TAU) / TAU) * (TAU / 12)
        local a = (TAU / 9) * i + tickAngle
        local pos = Vector3.new(math.cos(a) * S * 0.9, 2.2 + math.sin(a) * S * 0.9, 2.0)
        return Orbit3D.Look(pos, Vector3.new(0, 2.2, 2.0), 90)
    else
        local pIdx = i - 9
        local u = pIdx / math.max(1, total - 9)
        local swing = math.sin(t * 2.5 * PI) * math.rad(55)
        local len = u * (S * 1.65)
        local x = math.sin(swing) * len
        local y = 4.5 - math.cos(swing) * len
        local pos = Vector3.new(x, y, 1.6)
        return Orbit3D.Look(pos, Vector3.new(0, 4.5, 1.6), 0)
    end
end
function Orbit3D.B073(t, i, total, r)
    local S = r * 2.5
    return Orbit3D.TraceCurve(t, i, total, 4.2, 1.8, function(s)
        local x = math.cos(s) * (S * 1.6)
        local z = math.sin(s) * (S * 0.55)
        local y = math.sin(s) * (S * 0.85) + 1.5
        return CFrame.Angles(0, t * 0.3, math.rad(25)) * Vector3.new(x, y, z)
    end, 240)
end
function Orbit3D.B074(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.MultiStream(t, i, total, 3, 3.8, 1.5, function(s, stream, u)
        local baseA = (stream - 2) * math.rad(65)
        local wave = math.sin(s * 2.2 - u * 3.0) * (S * 0.45 * u)
        local reach = 1.5 + u * (S * 1.5)
        local x = math.sin(baseA) * reach + wave
        local y = 2.0 + math.cos(s * 1.8 - u * 2.5) * (S * 0.55 * u)
        local z = 2.0 - u * (S * 1.6)
        return Vector3.new(x, y, z)
    end, 90)
end
function Orbit3D.B075(t, i, total, r)
    local S = r * 2.0
    local side, rank, maxR = Orbit3D.SymmetryPair(i, total)
    if side == 0 then
        return CFrame.new(0, 2.0, 1.8) * CFrame.Angles(0, 0, t * 10)
    end
    local u = rank / maxR
    local a = u * TAU * 2 + t * 8.0 * side
    local coneR = u * (S * 0.45)
    local cx = side * (1.8 + u * (S * 0.5))
    local cy = 2.2 + math.sin(a) * coneR
    local cz = 1.6 + u * (S * 0.85) + math.cos(a) * coneR
    local pos = Vector3.new(cx, cy, cz)
    return Orbit3D.Look(pos, Vector3.new(side * 1.8, 2.2, 1.6), t * 300)
end
function Orbit3D.B076(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.MultiStream(t, i, total, 3, 4.2, 1.8, function(s, stream, u)
        local baseA = stream * (TAU / 3) + t * 0.8
        local slither = math.sin(s * 2.0) * 0.45
        local rad = S * (0.75 + 0.35 * math.sin(u * PI))
        local y = -1.5 + u * (S * 1.65) + math.cos(s * 2.5) * 0.6
        return Vector3.new(math.cos(baseA + slither) * rad, y, math.sin(baseA + slither) * rad)
    end, 120)
end
function Orbit3D.B077(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.TraceCurve(t, i, total, 3.2, TAU, function(s)
        local u = 0.5 + 0.48 * math.sin(s)
        local rad = S * (0.35 + 1.15 * u)
        local a = s * 3.0 + t * 2.0
        local y = -1.8 + u * (S * 2.1)
        return Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    end, 45)
end
function Orbit3D.B078(t, i, total, r)
    local S = r * 2.2
    return Orbit3D.MultiStream(t, i, total, 3, 2.8, 2.0, function(s, stream, u)
        local span = (stream - 2) * (S * 0.75) + math.sin(s) * (S * 0.35)
        local curl = s * 1.5
        local y = 1.2 + math.sin(curl) * (S * 0.95) + u * 0.8
        local z = math.cos(curl) * (S * 0.95) - u * 0.6
        return Vector3.new(span, y, z)
    end, 35)
end
function Orbit3D.B079(t, i, total, r)
    local S = r * 2.3
    local u = 0.5 + 0.45 * math.sin(t * 1.8 + (i - 1) * (TAU / total))
    local a = i * (TAU / PHI) + t * 1.2
    local rad = S * (0.35 + 1.15 * u)
    local y = -1.5 + (4 * u * (1 - u)) * (S * 1.9)
    local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    local vy = (4 - 8 * u) * (S * 1.9)
    return Orbit3D.Look(pos, pos + Vector3.new(math.cos(a) * S, vy, math.sin(a) * S), 35)
end
function Orbit3D.B080(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.TraceCurve(t, i, total, 6.8, 2.2, function(s)
        local rad = S * (0.75 + 0.45 * math.sin(s * 4.0))
        local y = math.cos(s * 3.0) * (S * 1.1) + 1.8
        return Vector3.new(math.cos(s * 1.5) * rad, y, math.sin(s * 1.5) * rad)
    end, 450)
end
function Orbit3D.B081(t, i, total, r)
    local S = r * 2.2
    local u = i / math.max(1, total)
    local strike = math.max(0, math.sin(t * 3.2)) ^ 3
    local archA = u * PI * (0.95 + 0.35 * strike)
    local swayX = math.sin(t * 2.5 - u * 2.0) * (S * 0.25 * u)
    local y = -0.5 + math.sin(archA) * (S * 1.45)
    local z = 1.5 + math.cos(archA) * (S * 0.95) - (u ^ 2) * strike * (S * 1.5)
    local pos = Vector3.new(swayX, y, z)
    return Orbit3D.Look(pos, pos + Vector3.new(0, -0.3, -2), 0)
end
function Orbit3D.B082(t, i, total, r)
    local S = r * 2.1
    return Orbit3D.TraceCurve(t, i, total, 4.5, 2.5, function(s)
        local climb = (math.sin(s * 0.7) + 1) * 0.5
        local hood = (climb > 0.7) and 1.45 or 0.85
        local rad = S * hood * (1 - climb * 0.3)
        local y = -2.0 + climb * (S * 1.9)
        return Vector3.new(math.cos(s * 2.0) * rad, y, math.sin(s * 2.0) * rad)
    end, 120)
end
function Orbit3D.B083(t, i, total, r)
    local S = r * 2.1
    local a = (TAU / total) * i + t * 1.8
    local pulse = 1 + 0.35 * math.sin(t * 3.8 - (i % 3) * 0.6)
    local tier = (i % 3)
    local rad = S * (0.45 + tier * 0.35) * pulse
    local y = 4.2 - tier * (S * 0.75) + math.cos(t * 3.8) * 0.8
    local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, 4.8, 0), 0)
end
function Orbit3D.B084(t, i, total, r)
    local S = r * 2.3
    local side, rank, maxR = Orbit3D.SymmetryPair(i, total)
    local u = 0.5 + 0.48 * math.sin(t * 1.6 + (rank / math.max(1, maxR)) * PI)
    local x = side * ((u - 0.5) * 2 * S * 1.35)
    local y = -2.0 + (4 * u * (1 - u)) * (S * 1.65)
    local z = math.sin(u * PI + side) * (S * 0.45)
    local pos = Vector3.new(x, y, z)
    return Orbit3D.Look(pos, pos + Vector3.new(side * 2, (0.5 - u) * 4, 0), 0)
end
function Orbit3D.B085(t, i, total, r)
    local S = r * 2.2
    return Orbit3D.MultiStream(t, i, total, 2, 5.2, 2.2, function(s, stream)
        local offset = (stream == 1) and 0 or PI
        local a = s * 2.2 + offset
        local y = math.sin(s * 0.9) * (S * 1.35) + 1.5
        local rad = S * (0.75 + 0.25 * math.cos(s * 0.9))
        return Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    end, 220)
end
function Orbit3D.B086(t, i, total, r)
    local S = r * 2.2
    local side, rank, maxR = Orbit3D.SymmetryPair(i, total)
    if side == 0 then
        local bob = math.sin(t * 3.0) * 0.4
        return CFrame.new(0, 4.8 + bob, 1.8) * CFrame.Angles(0, t * 2.5, math.rad(45))
    end
    local u = rank / maxR
    local sway = math.sin(t * 2.4 - u * 1.4)
    local x = side * (1.2 + u * S * 1.25)
    local y = 1.0 + math.sin(u * PI * 0.9) * (S * 1.1) + sway * 0.45
    local z = 2.0 - math.cos(u * PI * 0.6) * (S * 0.65)
    local pos = Vector3.new(x, y, z)
    return Orbit3D.Look(pos, Vector3.new(0, 2.0, -S * 2), side * 30)
end
function Orbit3D.B087(t, i, total, r)
    local S = r * 2.1
    local a = (TAU / total) * i + t * 1.8
    local wave = math.sin(t * 4.0 + i * (TAU / 3))
    local y = 2.0 + wave * (S * 0.85)
    local rad = S * (0.95 + 0.15 * wave)
    local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    return Orbit3D.Look(pos, pos + Vector3.new(0, -10, 0), a * 57.3)
end
function Orbit3D.B088(t, i, total, r)
    local S = r * 2.2
    local a = (TAU / total) * i + t * 1.8
    local x = math.cos(a) * S
    local y = 2.5 + math.sin(a) * S
    local z = 2.2 + math.sin(a * 3 + t * 3) * 0.5
    return Orbit3D.Look(Vector3.new(x, y, z), Vector3.new(0, 2.5, 2.2), 0)
end
function Orbit3D.B089(t, i, total, r)
    local S = r * 2.3
    return Orbit3D.TraceCurve(t, i, total, 2.4, TAU, function(s)
        local wing = math.sin(s)
        local localA = s * 2.0
        local cx = wing * (S * 0.65)
        local rad = S * (0.45 + 0.35 * math.cos(s))
        local x = cx + math.cos(localA) * rad * wing
        local y = 1.8 + math.sin(localA) * rad
        local z = math.sin(s * 3) * (S * 0.65)
        return Vector3.new(x, y, z)
    end, 45)
end
function Orbit3D.B090(t, i, total, r)
    local S = r * 2.0
    local tier = (i - 1) % 3
    local perTier = math.max(1, math.ceil(total / 3))
    local idx = math.floor((i - 1) / 3) + 1
    local dir = (tier == 1) and -1 or 1
    local a = (TAU / perTier) * idx + t * (2.2 + tier) * dir
    local rad = S * (1.15 - tier * 0.35)
    local y = 5.8 - tier * (S * 0.55) + math.sin(t * 3 + tier) * 0.3
    local pos = Vector3.new(math.cos(a) * rad, y, math.sin(a) * rad)
    return Orbit3D.Look(pos, Vector3.new(0, 6.5, 0), 0)
end
function Orbit3D.B091(t, i, total, r)
    local S = r * 2.2
    local side, rank, maxR = Orbit3D.SymmetryPair(i, total)
    local u = (side == 0) and 0 or (rank / maxR)
    local thrust = (0.5 + 0.5 * math.sin(t * 2.8 - u * 1.5)) * (S * 0.75)
    local x = side * (u * S * 1.35)
    local y = 1.6 + math.cos(u * PI * 0.8) * (S * 0.65) + math.sin(t * 2.0 + i) * 0.3
    local z = -1.6 + u * (S * 0.85) - thrust
    local pos = Vector3.new(x, y, z)
    return Orbit3D.Look(pos, pos + Vector3.new(0, 0, -10), side * 25)
end
function Orbit3D.B092(t, i, total, r)
    local S = r * 2.1
    local saw = (i - 1) % 3
    local perSaw = math.max(1, math.ceil(total / 3))
    local idx = math.floor((i - 1) / 3) + 1
