    end
    local u = rank / maxR
    local beat = math.sin(t * 3.08 - u * 1.3)
    local flare = 1.05 + 0.22 * math.sin(t * 1.2 + u)
    local spanX = side * (1.35 + (u ^ 0.88) * S * 1.49 * flare)
    local archY = 1.6 + math.sin(u * PI * 0.9) * (S * 0.99) + beat * (u * S * 0.42)
    local sweepZ = 1.6 + math.cos(beat * 0.8 + u) * (u * S * 0.52) + u * 1.4
    local pos = Vector3.new(spanX, archY, sweepZ)
    local target = pos + Vector3.new(side * 3.5, beat * 1.6 - u * 1.5, -3.0)
    return Orbit3D.Look(pos, target, side * 55)
end
