local RotateMath = {}
RotateMath["rot_01"] = function(t, i) return CFrame.identity end
RotateMath["rot_02"] = function(t, i) return CFrame.Angles(0, t * 3.0, 0) end
RotateMath["rot_03"] = function(t, i) return CFrame.Angles(0, -t * 3.0, 0) end
RotateMath["rot_04"] = function(t, i) return CFrame.Angles(t * 4.0, 0, 0) end
RotateMath["rot_05"] = function(t, i) return CFrame.Angles(0, 0, t * 4.5) end
RotateMath["rot_06"] = function(t, i) return CFrame.Angles(0, t * 3.5, 0) end
RotateMath["rot_07"] = function(t, i) return CFrame.Angles(0, 0, t * 4.0) end
RotateMath["rot_08"] = function(t, i) return CFrame.Angles(math.rad(45), t * 2.5, math.rad(45)) end
RotateMath["rot_09"] = function(t, i) return CFrame.new(0, math.sin(t * 2.0 + i * 0.6) * 0.5, 0) * CFrame.Angles(math.sin(t * 1.8 + i) * 0.2, 0, math.cos(t * 1.8 + i) * 0.2) end
RotateMath["rot_10"] = function(t, i) local dir = (i % 2 == 0) and 1 or -1; return CFrame.Angles(0, t * 2.5 * dir, math.rad(25) * dir) end
RotateMath["rot_11"] = function(t, i) return CFrame.Angles(t * 1.5, t * 2.0, t * 1.2) end
RotateMath["rot_12"] = function(t, i) return CFrame.Angles(math.rad(90), t * 4.5, 0) end
RotateMath["rot_13"] = function(t, i) return CFrame.Angles(t * 4.5, 0, 0) end
RotateMath["rot_14"] = function(t, i) return CFrame.Angles(0, 0, math.sin(t * 4.0 + i * 0.4) * math.rad(55)) end
RotateMath["rot_15"] = function(t, i) return CFrame.Angles(math.sin(t * 3.0 + i * 0.5) * 0.8, t * 2.0, math.cos(t * 3.0 + i * 0.5) * 0.8) end
local RevolveDropdownItems = {}
for k, _ in pairs(RevolveMath) do
    table.insert(RevolveDropdownItems, {
        Value = k,
        Key = k,
        Label = T(k, k)
    })
end
table.sort(RevolveDropdownItems, function(a, b) return tostring(a.Value) < tostring(b.Value) end)
local RotateDropdownItems = {}
for k, _ in pairs(RotateMath) do
    table.insert(RotateDropdownItems, {
        Value = k,
        Key = k,
        Label = T(k, k)
    })
end
table.sort(RotateDropdownItems, function(a, b) return tostring(a.Value) < tostring(b.Value) end)
