    end
end)
local function getOrbitTargetOptions()
    local items = {
        { Value = "LocalPlayer", Key = "opt_target_self" },
        { Value = "Nearest", Key = "opt_target_nearest" },
        { Value = "Mouse", Key = "opt_target_mouse" },
    }
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            local label = (p.DisplayName and p.DisplayName ~= p.Name)
                and string.format("%s (@%s)", p.DisplayName, p.Name)
                or p.Name
            table.insert(items, { Value = p.Name, Label = label })
        end
    end
    return items
end
local orbitTargetDrop
orbitTargetDrop = orbitBox:AddDropdown("drop_orbit_target", getOrbitTargetOptions(), "LocalPlayer", function(val)
    if val == "LocalPlayer" or val == "Nearest" or val == "Mouse" then
        OrbitConfig.TargetMode = val
        OrbitConfig.TargetPlayer = ""
    else
        OrbitConfig.TargetMode = "Player"
        OrbitConfig.TargetPlayer = val
        local p = Players:FindFirstChild(val)
        local dName = p and p.DisplayName or val
        HONKUKIUI:Notify({
            Title = AppState.LangMode == "en" and "Orbit Target Locked" or "ล็อคเป้าหมายวงโคจร",
            Content = (AppState.LangMode == "en" and "Locked onto: " or "ล็อคพิกัดโคจรกับ: ") .. dName .. " (@" .. val .. ")",
            Icon = Icons.Check,
            Duration = 2.0
        })
    end
end)
Players.PlayerAdded:Connect(function()
    task.delay(0.5, function()
        pcall(function()
            if orbitTargetDrop then
                local currentVal = (OrbitConfig.TargetMode == "Player") and OrbitConfig.TargetPlayer or OrbitConfig.TargetMode
                orbitTargetDrop.Refresh(getOrbitTargetOptions(), currentVal, true)
            end
        end)
    end)
end)
Players.PlayerRemoving:Connect(function(leavingPlr)
    task.delay(0.2, function()
        pcall(function()
            if OrbitConfig.TargetMode == "Player" and OrbitConfig.TargetPlayer == leavingPlr.Name then
                OrbitConfig.TargetPlayer = ""
                OrbitConfig.TargetMode = "LocalPlayer"
                if orbitTargetDrop then orbitTargetDrop.Set("LocalPlayer", true) end
            end
            if orbitTargetDrop then
                local currentVal = (OrbitConfig.TargetMode == "Player") and OrbitConfig.TargetPlayer or OrbitConfig.TargetMode
                orbitTargetDrop.Refresh(getOrbitTargetOptions(), currentVal, true)
            end
        end)
    end)
end)
task.spawn(function()
    local lastPlayerListStr = ""
    while true do
        task.wait(2.5)
        pcall(function()
            if not orbitTargetDrop then return end
            local plrs = Players:GetPlayers()
            local names = {}
            for _, p in ipairs(plrs) do
                if p ~= LocalPlayer then
                    table.insert(names, p.Name)
                end
            end
            table.sort(names)
            local joinedNames = table.concat(names, ",")
            if joinedNames ~= lastPlayerListStr then
                lastPlayerListStr = joinedNames
                local currentVal = (OrbitConfig.TargetMode == "Player") and OrbitConfig.TargetPlayer or OrbitConfig.TargetMode
                if OrbitConfig.TargetMode == "Player" and not Players:FindFirstChild(OrbitConfig.TargetPlayer) then
                    OrbitConfig.TargetPlayer = ""
                    OrbitConfig.TargetMode = "LocalPlayer"
                    currentVal = "LocalPlayer"
                    orbitTargetDrop.Set("LocalPlayer", true)
                end
                orbitTargetDrop.Refresh(getOrbitTargetOptions(), currentVal, true)
            end
        end)
    end
end)
