propRgbBox:AddButton("btn_auto_dup", function()
    local props = getOwnedProps()
    if #props == 0 then
        HONKUKIUI:Notify({ Title = AppState.LangMode == "en" and "Duplicate" or "คัดลอกวัตถุ", Content = AppState.LangMode == "en" and "Place at least 1 prop before duplicating" or "กรุณาวางวัตถุอย่างน้อย 1 ชิ้นก่อนคัดลอก", Icon = Icons.Close })
        return
    end
    local dup = props[1]:FindFirstChild("DuplicateProp")
    if dup then
        task.spawn(function()
            for i = 1, OrbitConfig.DuplicateTargetAmount do
                dup:InvokeServer()
                task.wait(0.08)
            end
            HONKUKIUI:Notify({ Title = AppState.LangMode == "en" and "Duplicate" or "คัดลอกวัตถุ", Content = AppState.LangMode == "en" and "Duplicated props successfully" or "คัดลอกวัตถุสำเร็จแล้ว", Icon = Icons.Check })
        end)
    end
end)
