local lastStepTick = tick()
_G.NothingPanelOrbitConn = RunService.RenderStepped:Connect(function(dt)
    local now = tick()
    local frameDt = math.clamp(dt or (now - lastStepTick), 0.001, 0.05)
    lastStepTick = now
    if not OrbitConfig.OrbitActive then
        orbitClock = 0
        return
    end
    local targetCF = getOrbitTargetCFrame()
    if not targetCF then return end
    local dirMult = OrbitConfig.ReverseDirection and -1 or 1
    orbitClock = orbitClock + frameDt * OrbitConfig.Speed * dirMult
    rotateClock = rotateClock + frameDt * (OrbitConfig.SelfRotateSpeed * 0.75)
    local timeScaled = orbitClock
    local timeRotate = rotateClock
    local centerCFrame = targetCF
        * CFrame.new(0, OrbitConfig.CenterY + (math.sin(tick() * OrbitConfig.BobSpeed) * OrbitConfig.BobAmplitude), 0)
        * CFrame.Angles(math.rad(OrbitConfig.RotX), math.rad(OrbitConfig.RotY), math.rad(OrbitConfig.RotZ))
    local revolveFunc = RevolveMath[OrbitConfig.RevolveType] or RevolveMath["rev_001"]
    local rotateFunc = RotateMath[OrbitConfig.RotateType] or RotateMath["rot_01"]
    local props = getOwnedProps()
        local totalProps = #props
        if totalProps > 0 then
            local maxPropDim = 2
            local propInfoList = {}
            if OrbitConfig.AutoPropSize then
                for idx, prop in ipairs(props) do
                    local sz, dim, cOff = getPropBoundingInfo(prop)
                    propInfoList[idx] = { size = sz, dim = dim, centerOffset = cOff }
                    if dim > maxPropDim then maxPropDim = dim end
                end
            end
            for i, prop in ipairs(props) do
                local info = propInfoList[i]
                local dim = info and info.dim or 2
                local cOff = info and info.centerOffset or Vector3.zero
                local effRadius = OrbitConfig.Radius * OrbitConfig.SpreadSeparation
                if OrbitConfig.AutoPropSize then
                    local minSafeRadius = maxPropDim * 0.75 + 4
                    if effRadius < minSafeRadius then
                        effRadius = minSafeRadius
                    end
                    effRadius = effRadius + math.max(0, (dim - 3) * 0.35)
                end
                local currentDir = (OrbitConfig.AlternatingDirection and (i % 2 == 0 and -1 or 1)) or 1
                local revCF = revolveFunc(timeScaled * currentDir, i, totalProps, effRadius)
                local propPos = (centerCFrame * revCF).Position
                local faceCF = CFrame.identity
                if OrbitConfig.PropFaceMode == "FaceTarget" then
                    faceCF = CFrame.lookAt(propPos, centerCFrame.Position) * CFrame.Angles(0, math.pi, 0)
                elseif OrbitConfig.PropFaceMode == "FaceOutward" then
                    faceCF = CFrame.lookAt(propPos, propPos + (propPos - centerCFrame.Position))
                elseif OrbitConfig.PropFaceMode == "FaceTangent" then
                    local nextRev = revolveFunc((timeScaled + 0.05) * currentDir, i, totalProps, effRadius)
                    local nextPos = (centerCFrame * nextRev).Position
                    faceCF = CFrame.lookAt(propPos, nextPos)
                else
                    faceCF = centerCFrame * revCF * rotateFunc(timeRotate, i)
                end
                local centerComp = CFrame.identity
                if OrbitConfig.AutoPropSize and cOff.Magnitude > 0.1 then
                    centerComp = CFrame.new(-cOff.X * 0.5, -cOff.Y * 0.5, -cOff.Z * 0.5)
                end
                local finalCF = faceCF
                    * centerComp
                    * CFrame.Angles(math.rad(OrbitConfig.PropOffsetPitch), math.rad(OrbitConfig.PropOffsetYaw), math.rad(OrbitConfig.PropOffsetRoll))
                    * CFrame.Angles(math.rad(i * OrbitConfig.PropPhaseStagger), 0, 0)
                    * CFrame.Angles(
                        math.rad(OrbitConfig.SelfRotateX * timeRotate * 10),
                        math.rad(OrbitConfig.SelfRotateY * timeRotate * 10),
                        math.rad(OrbitConfig.SelfRotateZ * timeRotate * 10)
                    )
                pcall(function() prop:PivotTo(finalCF) end)
                local syncInterval = OrbitConfig.ServerSync + (i % 5) * 0.012
                if not prop:GetAttribute("LastSync") or (now - prop:GetAttribute("LastSync") > syncInterval) then
                    prop:SetAttribute("LastSync", now)
                    task.spawn(function() pcall(function() prop.SetCurrentCFrame:InvokeServer(finalCF) end) end)
                end
            end
        end
end)
HONKUKIUI.CleanupScript2 = function()
end
end)()
